const exactUnits={"Quy tắc nhìn được. Mẫu chọn theo việc.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 7, "text": "Quy tắc"}]}, "Tổng quan · Biểu tượng · Nền · Slide · Giao diện · Biểu đồ": {"role": "role-exception", "selectedSpans": []}, "Các liên kết mở ngay phần tương ứng. Bảng chọn slide theo tình huống nằm ở trang 3–5.": {"role": "explanatory-body", "selectedSpans": [{"start": 53, "end": 68, "text": "theo tình huống"}]}, "Đọc quy tắc và nhìn mẫu chữ, màu, khoảng cách.": {"role": "explanatory-body", "selectedSpans": [{"start": 24, "end": 32, "text": "chữ, màu"}]}, "Năm hình, đủ hai bản màu.": {"role": "explanatory-body", "selectedSpans": [{"start": 13, "end": 24, "text": "hai bản màu"}]}, "Hai kiểu nền và vùng dành cho chữ.": {"role": "explanatory-body", "selectedSpans": [{"start": 4, "end": 12, "text": "kiểu nền"}]}, "27 mẫu; chọn theo tình huống và đầu vào.": {"role": "explanatory-body", "selectedSpans": [{"start": 13, "end": 28, "text": "theo tình huống"}]}, "Chọn nút, đọc trạng thái và dùng điều khiển.": {"role": "explanatory-body", "selectedSpans": [{"start": 10, "end": 24, "text": "đọc trạng thái"}]}, "22 họ; giữ đúng dữ liệu, đơn vị và giới hạn.": {"role": "explanatory-body", "selectedSpans": [{"start": 25, "end": 43, "text": "đơn vị và giới hạn"}]}, "Với slide, xác định câu hỏi trước, chuẩn bị đúng đầu vào, rồi mở mẫu theo số trang. Mẫu không thay cho dữ liệu và nguồn.": {"role": "explanatory-body", "selectedSpans": [{"start": 11, "end": 27, "text": "xác định câu hỏi"}]}, "Số trang là trang PDF, tính bìa là trang 1. Bấm số trang để tới mẫu; dùng mã S01–S27 để gọi đúng loại.": {"role": "explanatory-body", "selectedSpans": [{"start": 44, "end": 56, "text": "Bấm số trang"}]}, "Dùng cùng một ngôn ngữ thiết kế. Chọn thành phần theo việc cần làm, rồi thích nghi nội dung mà không đổi vai trò.": {"role": "explanatory-body", "selectedSpans": [{"start": 49, "end": 66, "text": "theo việc cần làm"}]}, "Chọn một thông điệp chính trước khi bố trí.": {"role": "explanatory-body", "selectedSpans": [{"start": 9, "end": 25, "text": "thông điệp chính"}]}, "Giữ cùng quy tắc chữ, màu và khoảng cách qua các định dạng.": {"role": "explanatory-body", "selectedSpans": [{"start": 17, "end": 25, "text": "chữ, màu"}]}, "Dùng thư viện theo mục đích, không theo tên gọi đơn thuần.": {"role": "explanatory-body", "selectedSpans": [{"start": 14, "end": 27, "text": "theo mục đích"}]}, "Tổng quan sở hữu quy tắc; Thư viện chứa tài sản; Ứng dụng cho thấy cách kết hợp.": {"role": "explanatory-body", "selectedSpans": [{"start": 26, "end": 47, "text": "Thư viện chứa tài sản"}]}, "Mỗi tài sản có mã ổn định, nguồn, giới hạn và cách dùng.": {"role": "explanatory-body", "selectedSpans": [{"start": 15, "end": 25, "text": "mã ổn định"}]}, "Một mẫu đẹp không tự chứng nhận quyền sử dụng hay toàn bộ thư viện.": {"role": "explanatory-body", "selectedSpans": [{"start": 12, "end": 45, "text": "không tự chứng nhận quyền sử dụng"}]}, "Giữ nguyên logo, màu gốc, kiểu chữ và ý nghĩa dữ liệu.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 15, "text": "Giữ nguyên logo"}]}, "Đổi tỷ lệ hình/chữ khi cần; giữ cấu trúc của họ bố cục đã chọn.": {"role": "explanatory-body", "selectedSpans": [{"start": 28, "end": 40, "text": "giữ cấu trúc"}]}, "Thiếu ảnh dùng ô ghi rõ thiếu ảnh; không coi ô trống là hình hoàn tất.": {"role": "explanatory-body", "selectedSpans": [{"start": 17, "end": 33, "text": "ghi rõ thiếu ảnh"}]}, "Xem DESIGN.md để tìm quy tắc theo mục đích.": {"role": "explanatory-body", "selectedSpans": [{"start": 29, "end": 42, "text": "theo mục đích"}]}, "Dùng tệp và mã băm trong source-map.json để kiểm tra nguồn.": {"role": "explanatory-body", "selectedSpans": [{"start": 44, "end": 58, "text": "kiểm tra nguồn"}]}, "Đọc trạng thái từng bản ghi; tài sản đề xuất không tự trở thành tài sản thương hiệu được đăng ký.": {"role": "explanatory-body", "selectedSpans": [{"start": 29, "end": 44, "text": "tài sản đề xuất"}]}, "Giữ nguyên logo MELAB. Khoảng thở và nền nhận giúp hình gốc rõ ràng hơn, không tạo một dấu hiệu nhận diện mới.": {"role": "explanatory-body", "selectedSpans": [{"start": 73, "end": 109, "text": "không tạo một dấu hiệu nhận diện mới"}]}, "Dùng đúng PNG nguồn; không gõ lại tên để thay logo.": {"role": "explanatory-body", "selectedSpans": [{"start": 21, "end": 33, "text": "không gõ lại"}]}, "Giữ tỷ lệ ảnh và dùng cách hiển thị vừa trọn khung.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 9, "text": "Giữ tỷ lệ"}]}, "Khoảng trống và kích thước màn hình dưới đây là đề xuất, chưa phải chuẩn in chính thức.": {"role": "explanatory-body", "selectedSpans": [{"start": 57, "end": 86, "text": "chưa phải chuẩn in chính thức"}]}, "Giữ tỷ lệ, cấu trúc nét và phần rỗng của PNG nguồn; không gõ lại, kéo giãn, cắt cụt hay đổi màu. Mẫu chiều cao32/48/64px là phép thử màn hình; chưa xác nhận kích thước in tối thiểu.": {"role": "explanatory-body", "selectedSpans": [{"start": 52, "end": 64, "text": "không gõ lại"}, {"start": 143, "end": 156, "text": "chưa xác nhận"}]}, "Đề xuất32px ở mẫu chiều cao64px; đo từ phần đã vẽ của hình. Nguồn chưa cung cấp đơn vị chuẩn cho thông số này, không coi đề xuất là chuẩn chính thức.": {"role": "explanatory-body", "selectedSpans": [{"start": 39, "end": 49, "text": "phần đã vẽ"}, {"start": 111, "end": 148, "text": "không coi đề xuất là chuẩn chính thức"}]}, "Dùng PNG nguyên bản trong vùng nền trắng yên. Hình nguồn còn nền trắng; trên nền tối cần vùng nhận sáng có chủ đích hoặc đặt ở vị trí khác. Chưa có biến thể vector/alpha và logo tối được xác nhận.": {"role": "explanatory-body", "selectedSpans": [{"start": 26, "end": 44, "text": "vùng nền trắng yên"}, {"start": 140, "end": 169, "text": "Chưa có biến thể vector/alpha"}]}, "Trong đầu trang website, trang đọc và banner, giữ logo cách vùng chữ và điều khiển. Với video hoặc ảnh, giữ mặt và phụ đề ngoài vùng bảo vệ. Kiểm ở kích thước hiển thị thực tế.": {"role": "explanatory-body", "selectedSpans": [{"start": 128, "end": 139, "text": "vùng bảo vệ"}]}, "Dùng assets/logo.png đúng dấu kiểm tra nguồn trong bản ghi; đặt kiểu contain, giữ tỷ lệ và phép đo đề xuất. Kiểm nền nhận, kích thước nhỏ, phần rỗng và phạm vi quyền trước khi xuất. Không tự biến phiên bản mới thành logo chính thức.": {"role": "explanatory-body", "selectedSpans": [{"start": 30, "end": 44, "text": "kiểm tra nguồn"}, {"start": 152, "end": 165, "text": "phạm vi quyền"}]}, "Be Vietnam Pro · Kích thước mẫu bên phải là 0,75 lần số px, để minh họa phân cấp khi đưa vào trang PDF.": {"role": "explanatory-body", "selectedSpans": [{"start": 63, "end": 80, "text": "minh họa phân cấp"}]}, "Thông số giao diện và vai trò chữ là đề xuất bổ sung; không nhận là kích thước in chính thức của brandkit.": {"role": "explanatory-body", "selectedSpans": [{"start": 22, "end": 33, "text": "vai trò chữ"}]}, "Bảy mức đậm từ 200 đến 800 có trong tài liệu gốc.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 11, "text": "Bảy mức đậm"}]}, "Vai trò đề xuất: tiêu đề 48/58, tiêu đề phần 32/42, đề mục 24/34, nội dung 18/30, chú thích 14/22 và nhãn thao tác 16/24 px; độ đậm theo vai trò chữ: nội dung 400, nhãn 500, tiêu đề 700.": {"role": "explanatory-body", "selectedSpans": [{"start": 8, "end": 15, "text": "đề xuất"}, {"start": 137, "end": 148, "text": "vai trò chữ"}]}, "Giữ chữ rõ ở kích thước đọc; thêm trang thay vì ép nhỏ nội dung.": {"role": "explanatory-body", "selectedSpans": [{"start": 40, "end": 54, "text": "thay vì ép nhỏ"}]}, "Tiger Flame #FE6237; Sunflower Gold #FFB62E.": {"role": "role-exception", "selectedSpans": []}, "Maya Blue #7CC3FF; Electric Sapphire #4164FF.": {"role": "role-exception", "selectedSpans": []}, "Đề xuất xanh sapphire làm màu thao tác; cam và vàng tạo điểm nhấn. Không dùng cam/vàng làm chữ nhỏ trên trắng.": {"role": "explanatory-body", "selectedSpans": [{"start": 8, "end": 21, "text": "xanh sapphire"}]}, "Nội dung chính 18 px, dòng 30 px ở khung đủ rộng.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 14, "text": "Nội dung chính"}]}, "Dùng danh sách cho thông tin song song; bảng cho đối chiếu.": {"role": "explanatory-body", "selectedSpans": [{"start": 19, "end": 38, "text": "thông tin song song"}]}, "Cột chữ dài không quá khoảng 70 ký tự; số liệu thẳng hàng và có đơn vị.": {"role": "explanatory-body", "selectedSpans": [{"start": 39, "end": 57, "text": "số liệu thẳng hàng"}]}, "Điểm nhấn; tránh chữ nhỏ trên trắng.": {"role": "explanatory-body", "selectedSpans": [{"start": 17, "end": 24, "text": "chữ nhỏ"}]}, "Điểm cần chú ý; không tự có nghĩa hoàn tất.": {"role": "explanatory-body", "selectedSpans": [{"start": 16, "end": 42, "text": "không tự có nghĩa hoàn tất"}]}, "Vùng minh họa/nền; giữ chữ đủ tương phản.": {"role": "explanatory-body", "selectedSpans": [{"start": 23, "end": 40, "text": "chữ đủ tương phản"}]}, "Màu thao tác đề xuất; chữ trắng trên nền sapphire.": {"role": "explanatory-body", "selectedSpans": [{"start": 22, "end": 31, "text": "chữ trắng"}]}, "Màu nhận diện không tự thay cho ý nghĩa trạng thái. Dấu chọn, chữ, viền và nhãn phải cùng giải thích điều đang xảy ra.": {"role": "explanatory-body", "selectedSpans": [{"start": 14, "end": 50, "text": "không tự thay cho ý nghĩa trạng thái"}]}, "Tính cả phần đã vẽ, đường viền, bóng và vùng bàn phím khi đặt khoảng cách. Mỗi nhóm có một lớp ngoài chịu trách nhiệm.": {"role": "explanatory-body", "selectedSpans": [{"start": 87, "end": 100, "text": "một lớp ngoài"}]}, "Khoảng cách trong nhóm 16 px; giữa nhóm tối thiểu 32 px.": {"role": "explanatory-body", "selectedSpans": [{"start": 30, "end": 49, "text": "giữa nhóm tối thiểu"}]}, "Dùng cung tròn và góc bo có chủ đích theo hình học nguồn.": {"role": "explanatory-body", "selectedSpans": [{"start": 5, "end": 14, "text": "cung tròn"}]}, "Mỗi thẻ, giao diện và bố cục độc lập có một bóng mềm theo vai trò.": {"role": "explanatory-body", "selectedSpans": [{"start": 40, "end": 52, "text": "một bóng mềm"}]}, "Biểu đồ có bóng ở khung chứa; dấu dữ liệu, trục, chữ và số giữ nguyên.": {"role": "explanatory-body", "selectedSpans": [{"start": 18, "end": 28, "text": "khung chứa"}]}, "Nút giữ bóng khác không ở mọi trạng thái; chỉ forced-colors thay bằng viền.": {"role": "explanatory-body", "selectedSpans": [{"start": 8, "end": 23, "text": "bóng khác không"}]}, "Đường có hướng dùng mũi tên; quan hệ ngang hàng không tự thêm hướng.": {"role": "explanatory-body", "selectedSpans": [{"start": 29, "end": 47, "text": "quan hệ ngang hàng"}]}, "Đầu mũi tên có thể chạm đúng đường bao của đối tượng nhận; không xuyên vào hình, chữ hoặc vùng nội dung. Giữ tuyến nối và nhãn có khoảng trống riêng.": {"role": "explanatory-body", "selectedSpans": [{"start": 24, "end": 38, "text": "đúng đường bao"}, {"start": 59, "end": 70, "text": "không xuyên"}]}, "Nhãn mô tả quan hệ, không lặp lại tên hai đầu.": {"role": "explanatory-body", "selectedSpans": [{"start": 5, "end": 18, "text": "mô tả quan hệ"}]}, "Bóng thuộc khung chứa; không đặt bóng lên chữ, logo hoặc dấu dữ liệu.": {"role": "explanatory-body", "selectedSpans": [{"start": 11, "end": 21, "text": "khung chứa"}]}, "Đo từ phần thực sự đã vẽ, gồm viền, bóng và vùng bàn phím.": {"role": "explanatory-body", "selectedSpans": [{"start": 11, "end": 24, "text": "thực sự đã vẽ"}]}, "Giữ hướng có nghĩa; chạm đúng đường bao, không xuyên nội dung.": {"role": "explanatory-body", "selectedSpans": [{"start": 25, "end": 39, "text": "đúng đường bao"}]}, "Giữ bóng mềm nhìn được cùng đường viền tin cậy.": {"role": "explanatory-body", "selectedSpans": [{"start": 28, "end": 46, "text": "đường viền tin cậy"}]}, "Cấu trúc chỉ rõ quan hệ giữa các phần. Màu, chữ và tài sản được thích nghi theo MELAB; khung nguyên bản phải còn trọn.": {"role": "explanatory-body", "selectedSpans": [{"start": 87, "end": 103, "text": "khung nguyên bản"}]}, "Khung hình gốc 64×64; vùng vẽ chính giữ khoảng trống quanh biên.": {"role": "explanatory-body", "selectedSpans": [{"start": 53, "end": 63, "text": "quanh biên"}]}, "Bản đề xuất: #4164FF trên #FFFFFF và #FFFFFF trên #4164FF. Mã này lấy từ bảng màu; không khẳng định nền xanh trong minh họa PDF có cùng mã.": {"role": "explanatory-body", "selectedSpans": [{"start": 4, "end": 11, "text": "đề xuất"}, {"start": 73, "end": 81, "text": "bảng màu"}]}, "Hai bản đặt cạnh nhau, dùng chung cấu trúc. Không đếm hai màu thành hai loại biểu tượng.": {"role": "explanatory-body", "selectedSpans": [{"start": 44, "end": 61, "text": "Không đếm hai màu"}]}, "Có trạng thái nghỉ, trỏ chuột, nhấn, bàn phím; chọn, bận, vô hiệu khi phù hợp.": {"role": "explanatory-body", "selectedSpans": [{"start": 3, "end": 18, "text": "trạng thái nghỉ"}]}, "Nút chính xanh sapphire/chữ trắng; nút phụ nền trắng/chữ xanh.": {"role": "explanatory-body", "selectedSpans": [{"start": 10, "end": 23, "text": "xanh sapphire"}]}, "Vùng bấm đề xuất tối thiểu 44×44 px; không chỉ dùng màu để thông báo.": {"role": "explanatory-body", "selectedSpans": [{"start": 37, "end": 55, "text": "không chỉ dùng màu"}]}, "Slide dùng khung 1280×720, lề đề xuất 64 px.": {"role": "explanatory-body", "selectedSpans": [{"start": 11, "end": 25, "text": "khung 1280×720"}]}, "Ảnh minh họa trong guideline là tham khảo phong cách: sáng, tương phản, bóng rõ, đồ vật có chủ đích.": {"role": "explanatory-body", "selectedSpans": [{"start": 32, "end": 52, "text": "tham khảo phong cách"}]}, "Không biến ảnh tham khảo thành tài sản tái phân phối khi chưa rõ quyền.": {"role": "explanatory-body", "selectedSpans": [{"start": 57, "end": 70, "text": "chưa rõ quyền"}]}, "Chuyển động cần giải thích một thay đổi hoặc phản hồi. Giữ trạng thái tĩnh tương đương và các điều kiện sử dụng cạnh ví dụ.": {"role": "explanatory-body", "selectedSpans": [{"start": 59, "end": 74, "text": "trạng thái tĩnh"}]}, "Đề xuất phản hồi 160–220 ms; không suy thời lượng từ guideline tĩnh.": {"role": "explanatory-body", "selectedSpans": [{"start": 29, "end": 49, "text": "không suy thời lượng"}]}, "Luôn có trạng thái tĩnh khi người xem giảm chuyển động.": {"role": "explanatory-body", "selectedSpans": [{"start": 38, "end": 54, "text": "giảm chuyển động"}]}, "Dừng khi rời vùng nhìn; nhấn lặp không tạo nhiều tác vụ chồng nhau.": {"role": "explanatory-body", "selectedSpans": [{"start": 33, "end": 55, "text": "không tạo nhiều tác vụ"}]}, "Chọn một điểm nhấn trong mỗi khung.": {"role": "explanatory-body", "selectedSpans": [{"start": 5, "end": 18, "text": "một điểm nhấn"}]}, "Không kéo giãn logo, pha màu tùy tiện hoặc nhập biểu tượng nhận diện thương hiệu khác.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 19, "text": "Không kéo giãn logo"}]}, "Không biến số liệu minh họa thành lời hứa hiệu quả.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 27, "text": "Không biến số liệu minh họa"}]}, "Viết cụ thể, tự nhiên và vừa sức với người đọc. Đây là đề xuất biên tập; chưa có đủ tập mẫu để chứng nhận giọng thương hiệu đã học.": {"role": "explanatory-body", "selectedSpans": [{"start": 55, "end": 71, "text": "đề xuất biên tập"}, {"start": 73, "end": 91, "text": "chưa có đủ tập mẫu"}]}, "Tiếng Việt: dùng câu tự nhiên, hành động cụ thể, nhất quán cách gọi.": {"role": "explanatory-body", "selectedSpans": [{"start": 31, "end": 47, "text": "hành động cụ thể"}]}, "English: use concrete verbs and preserve conditions and uncertainty.": {"role": "explanatory-body", "selectedSpans": [{"start": 41, "end": 67, "text": "conditions and uncertainty"}]}, "Giọng hiện tại là đề xuất biên tập; chưa có đủ tập mẫu để chứng nhận giọng thương hiệu đã học.": {"role": "explanatory-body", "selectedSpans": [{"start": 36, "end": 54, "text": "chưa có đủ tập mẫu"}]}, "Chọn một câu hỏi cần trả lời trước khi chọn mẫu.": {"role": "explanatory-body", "selectedSpans": [{"start": 5, "end": 16, "text": "một câu hỏi"}]}, "Xem chi tiết · Tái sử dụng · Đóng hướng dẫn": {"role": "role-exception", "selectedSpans": []}, "Giữ nguyên tên thương hiệu, số liệu, điều kiện và ý nghĩa.": {"role": "explanatory-body", "selectedSpans": [{"start": 28, "end": 57, "text": "số liệu, điều kiện và ý nghĩa"}]}, "Giữ một hình gốc và hai bản màu tương ứng.": {"role": "explanatory-body", "selectedSpans": [{"start": 20, "end": 31, "text": "hai bản màu"}]}, "Tài liệu, nguồn và nội dung cần đọc.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 8, "text": "Tài liệu"}]}, "Tìm nội dung hoặc kiểm tra một chủ đề.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 12, "text": "Tìm nội dung"}]}, "Xác nhận hoàn tất và trạng thái đúng.": {"role": "explanatory-body", "selectedSpans": [{"start": 21, "end": 36, "text": "trạng thái đúng"}]}, "Ý tưởng, gợi ý và điểm cần khám phá.": {"role": "explanatory-body", "selectedSpans": [{"start": 18, "end": 35, "text": "điểm cần khám phá"}]}, "Đi tiếp trong một luồng có thứ tự.": {"role": "explanatory-body", "selectedSpans": [{"start": 24, "end": 33, "text": "có thứ tự"}]}, "Giữ vùng dành cho chữ và kiểm độ tương phản ở đúng nền sẽ dùng.": {"role": "explanatory-body", "selectedSpans": [{"start": 4, "end": 21, "text": "vùng dành cho chữ"}]}, "Nền hình học dùng ở vùng mở đầu; giữ vùng trái cho chữ và điều chỉnh nhận màu trước khi dùng.": {"role": "explanatory-body", "selectedSpans": [{"start": 37, "end": 54, "text": "vùng trái cho chữ"}]}, "Tiêu đề, thông tin báo cáo và một dải ảnh toàn cảnh.": {"role": "explanatory-body", "selectedSpans": [{"start": 9, "end": 26, "text": "thông tin báo cáo"}]}, "Bắt đầu một báo cáo hoặc buổi trình bày mới.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 19, "text": "Bắt đầu một báo cáo"}]}, "Tiêu đề; chủ đề; thời gian; người trình bày; ảnh mở đầu.": {"role": "explanatory-body", "selectedSpans": [{"start": 28, "end": 43, "text": "người trình bày"}]}, "Cần giải thích kết quả hoặc so sánh số liệu ngay trên trang. Gợi ý: S18 · Biểu đồ, chỉ số và giới hạn.": {"role": "explanatory-body", "selectedSpans": [{"start": 28, "end": 43, "text": "so sánh số liệu"}]}, "Mục lục toàn báo cáo: chỉ liệt kê các phần lớn theo thứ tự.": {"role": "explanatory-body", "selectedSpans": [{"start": 34, "end": 46, "text": "các phần lớn"}]}, "Giới thiệu ba phần lớn theo đúng thứ tự đọc.": {"role": "explanatory-body", "selectedSpans": [{"start": 11, "end": 22, "text": "ba phần lớn"}]}, "Ba tên phần; thứ tự; nhãn ngắn và ảnh định hướng.": {"role": "explanatory-body", "selectedSpans": [{"start": 34, "end": 48, "text": "ảnh định hướng"}]}, "Có quá nhiều mục nhỏ; chuyển chúng sang đầu từng phần. Gợi ý: S03 · Mở phần.": {"role": "explanatory-body", "selectedSpans": [{"start": 68, "end": 75, "text": "Mở phần"}]}, "Mở phần 01: tên phần, ba mục bên trong và cụm ảnh định hướng.": {"role": "explanatory-body", "selectedSpans": [{"start": 46, "end": 60, "text": "ảnh định hướng"}]}, "Báo hiệu chuyển sang một phần mới của báo cáo.": {"role": "explanatory-body", "selectedSpans": [{"start": 21, "end": 33, "text": "một phần mới"}]}, "Số và tên phần; ba mục con; cụm hình cùng chủ đề.": {"role": "explanatory-body", "selectedSpans": [{"start": 37, "end": 48, "text": "cùng chủ đề"}]}, "Cần trình bày lập luận hoặc bảng dữ liệu. Gợi ý: S23 · Các mục nhỏ.": {"role": "explanatory-body", "selectedSpans": [{"start": 28, "end": 40, "text": "bảng dữ liệu"}]}, "Lời cảm ơn, chủ đề báo cáo, dải năm ảnh và người trình bày.": {"role": "explanatory-body", "selectedSpans": [{"start": 12, "end": 26, "text": "chủ đề báo cáo"}]}, "Kết thúc và nhắc lại chủ đề hoặc lời cảm ơn.": {"role": "explanatory-body", "selectedSpans": [{"start": 33, "end": 43, "text": "lời cảm ơn"}]}, "Lời cảm ơn; chủ đề; người trình bày; bộ năm hình.": {"role": "explanatory-body", "selectedSpans": [{"start": 20, "end": 35, "text": "người trình bày"}]}, "Còn kết luận quan trọng chưa được giải thích. Gợi ý: S18 · Biểu đồ, chỉ số và giới hạn.": {"role": "explanatory-body", "selectedSpans": [{"start": 4, "end": 23, "text": "kết luận quan trọng"}]}, "Một hình ngang lớn và một cột giải thích ngắn.": {"role": "explanatory-body", "selectedSpans": [{"start": 22, "end": 40, "text": "một cột giải thích"}]}, "Một hình ngang mang thông điệp chính, cần lời giải thích bên cạnh.": {"role": "explanatory-body", "selectedSpans": [{"start": 20, "end": 36, "text": "thông điệp chính"}]}, "Một hình chính; một nhận định; chú thích ngắn.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 14, "text": "Một hình chính"}]}, "Cần đối chiếu hai hình có vai trò ngang nhau. Gợi ý: S11 · Hai hình đối chiếu.": {"role": "explanatory-body", "selectedSpans": [{"start": 4, "end": 22, "text": "đối chiếu hai hình"}]}, "Ba hình bằng nhau theo một chuỗi; mỗi hình một nhãn.": {"role": "explanatory-body", "selectedSpans": [{"start": 18, "end": 32, "text": "theo một chuỗi"}]}, "Ba hình cùng chủ đề cần được đọc thành một chuỗi.": {"role": "explanatory-body", "selectedSpans": [{"start": 8, "end": 19, "text": "cùng chủ đề"}]}, "Ba hình; nhãn từng hình; thứ tự có chủ đích.": {"role": "explanatory-body", "selectedSpans": [{"start": 25, "end": 31, "text": "thứ tự"}]}, "Hình thuộc các nhóm không liên quan hoặc không có thứ tự. Gợi ý: S07 · Bảng hình bốn lựa chọn.": {"role": "explanatory-body", "selectedSpans": [{"start": 41, "end": 56, "text": "không có thứ tự"}]}, "Bốn hình đồng cấp trong lưới hai hàng.": {"role": "explanatory-body", "selectedSpans": [{"start": 24, "end": 37, "text": "lưới hai hàng"}]}, "So sánh bốn lựa chọn hình ảnh có vai trò ngang nhau.": {"role": "explanatory-body", "selectedSpans": [{"start": 33, "end": 51, "text": "vai trò ngang nhau"}]}, "Bốn hình; một tiêu chí chung; bốn nhãn tương đương.": {"role": "explanatory-body", "selectedSpans": [{"start": 10, "end": 28, "text": "một tiêu chí chung"}]}, "Có sáu chi tiết hoặc một hình phải được ưu tiên rõ. Gợi ý: Sáu chi tiết: S12. Một hình chính: S05; có thêm hai cận cảnh: S09.": {"role": "explanatory-body", "selectedSpans": [{"start": 78, "end": 92, "text": "Một hình chính"}, {"start": 107, "end": 119, "text": "hai cận cảnh"}]}, "Hai hàng hình nhỏ đi cùng lời giải thích; đọc từ trên xuống.": {"role": "explanatory-body", "selectedSpans": [{"start": 42, "end": 59, "text": "đọc từ trên xuống"}]}, "Hai hình cần hai đoạn ngữ cảnh riêng, đọc từ trên xuống.": {"role": "explanatory-body", "selectedSpans": [{"start": 13, "end": 36, "text": "hai đoạn ngữ cảnh riêng"}]}, "Hai hình; hai lời giải thích; thứ tự đọc.": {"role": "explanatory-body", "selectedSpans": [{"start": 10, "end": 28, "text": "hai lời giải thích"}]}, "Hai đối tượng cần đối chiếu trực tiếp theo cùng tiêu chí. Gợi ý: S11 · Hai hình đối chiếu.": {"role": "explanatory-body", "selectedSpans": [{"start": 18, "end": 37, "text": "đối chiếu trực tiếp"}]}, "Một hình dọc lớn; hai cận cảnh ở cột bên.": {"role": "explanatory-body", "selectedSpans": [{"start": 18, "end": 30, "text": "hai cận cảnh"}]}, "Một hình dọc cần được giải thích bằng hai cận cảnh.": {"role": "explanatory-body", "selectedSpans": [{"start": 38, "end": 50, "text": "hai cận cảnh"}]}, "Một hình chính; hai chi tiết; nhãn chỉ rõ quan hệ.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 14, "text": "Một hình chính"}]}, "Các hình không có quan hệ chính–chi tiết, hoặc hình chính là ảnh ngang. Gợi ý: Hình ngang và hai góc bổ trợ: S10. Ba hình ngang vai cùng chủ đề: S06; khác chủ đề thì tách trang.": {"role": "explanatory-body", "selectedSpans": [{"start": 9, "end": 40, "text": "không có quan hệ chính–chi tiết"}, {"start": 132, "end": 143, "text": "cùng chủ đề"}]}, "Một hình ngang chiếm phần lớn; hai hình phụ xếp dọc.": {"role": "explanatory-body", "selectedSpans": [{"start": 4, "end": 14, "text": "hình ngang"}]}, "Cần nhìn toàn cảnh cùng hai góc nhìn bổ trợ.": {"role": "explanatory-body", "selectedSpans": [{"start": 24, "end": 36, "text": "hai góc nhìn"}]}, "Một hình ngang; hai hình phụ; mối liên hệ giữa các hình.": {"role": "explanatory-body", "selectedSpans": [{"start": 30, "end": 41, "text": "mối liên hệ"}]}, "Các hình cần trọng lượng và kích thước bằng nhau. Gợi ý: S06 · Dải hình cùng chủ đề.": {"role": "explanatory-body", "selectedSpans": [{"start": 28, "end": 48, "text": "kích thước bằng nhau"}]}, "Hai hình ngang đối xứng; một tiêu chí chung để đối chiếu.": {"role": "explanatory-body", "selectedSpans": [{"start": 25, "end": 43, "text": "một tiêu chí chung"}]}, "Đối chiếu hai hình theo một tiêu chí chung.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 18, "text": "Đối chiếu hai hình"}]}, "Hai hình; tiêu chí đối chiếu; nhãn và chú thích tương ứng.": {"role": "explanatory-body", "selectedSpans": [{"start": 10, "end": 28, "text": "tiêu chí đối chiếu"}]}, "Không có cơ sở so sánh hoặc khác thang đo mà không ghi rõ. Gợi ý: S05 · Hình lớn và giải thích.": {"role": "explanatory-body", "selectedSpans": [{"start": 28, "end": 41, "text": "khác thang đo"}]}, "Sáu hình nhỏ theo lưới; nhãn nằm trong từng khung.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 12, "text": "Sáu hình nhỏ"}]}, "Trình bày sáu chi tiết cùng nhóm bằng một bảng hình.": {"role": "explanatory-body", "selectedSpans": [{"start": 10, "end": 32, "text": "sáu chi tiết cùng nhóm"}]}, "Sáu hình; sáu nhãn ngắn; quy tắc cắt ảnh thống nhất.": {"role": "explanatory-body", "selectedSpans": [{"start": 25, "end": 40, "text": "quy tắc cắt ảnh"}]}, "Một hình cần chú thích dài hoặc phải là điểm nhìn chính. Gợi ý: S09 · Hình chính và hai chi tiết.": {"role": "explanatory-body", "selectedSpans": [{"start": 40, "end": 55, "text": "điểm nhìn chính"}]}, "Ảnh phủ toàn nền; chữ đặt trên mặt phẳng MELAB có nền kín.": {"role": "explanatory-body", "selectedSpans": [{"start": 50, "end": 57, "text": "nền kín"}]}, "Một ảnh nền có thể tạo bối cảnh cho thông điệp ngắn.": {"role": "explanatory-body", "selectedSpans": [{"start": 36, "end": 51, "text": "thông điệp ngắn"}]}, "Ảnh đủ chất lượng; thông điệp; mặt phẳng chữ có nền kín.": {"role": "explanatory-body", "selectedSpans": [{"start": 48, "end": 55, "text": "nền kín"}]}, "Ảnh làm chữ khó đọc hoặc cần nhiều dữ liệu nhỏ. Gợi ý: S14 · Dải ảnh dọc và thông điệp.": {"role": "explanatory-body", "selectedSpans": [{"start": 29, "end": 46, "text": "nhiều dữ liệu nhỏ"}]}, "Dải ảnh sát cạnh bên trái; thông điệp ở vùng nền riêng.": {"role": "explanatory-body", "selectedSpans": [{"start": 45, "end": 54, "text": "nền riêng"}]}, "Cần thông điệp lớn bên cạnh một dải ảnh dọc.": {"role": "explanatory-body", "selectedSpans": [{"start": 4, "end": 18, "text": "thông điệp lớn"}]}, "Dải hình dọc; tiêu đề ngắn; lời giải thích trong vùng riêng.": {"role": "explanatory-body", "selectedSpans": [{"start": 49, "end": 59, "text": "vùng riêng"}]}, "Ảnh là bằng chứng chính cần xem đầy đủ chiều ngang. Gợi ý: S05 · Hình lớn và giải thích.": {"role": "explanatory-body", "selectedSpans": [{"start": 7, "end": 23, "text": "bằng chứng chính"}]}, "Bảng chiếm vùng chính; nhận định có cột riêng.": {"role": "explanatory-body", "selectedSpans": [{"start": 36, "end": 45, "text": "cột riêng"}]}, "Cần đối chiếu tiêu chí trong bảng và tách nhận định ở cột riêng.": {"role": "explanatory-body", "selectedSpans": [{"start": 37, "end": 51, "text": "tách nhận định"}]}, "Tên hàng/cột; dữ liệu có đơn vị; một nhận định dựa trên bảng.": {"role": "explanatory-body", "selectedSpans": [{"start": 14, "end": 31, "text": "dữ liệu có đơn vị"}]}, "Không có tiêu chí chung hoặc chỉ có một con số nổi bật. Gợi ý: S18 · Biểu đồ, chỉ số và giới hạn.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 23, "text": "Không có tiêu chí chung"}]}, "Hai bảng theo chiều đọc; mỗi bảng có tên nhóm.": {"role": "explanatory-body", "selectedSpans": [{"start": 14, "end": 23, "text": "chiều đọc"}]}, "Hai nhóm dữ kiện cần hai bảng có tên riêng.": {"role": "explanatory-body", "selectedSpans": [{"start": 33, "end": 42, "text": "tên riêng"}]}, "Hai bảng; tên nhóm; đơn vị; phạm vi và nguồn.": {"role": "explanatory-body", "selectedSpans": [{"start": 28, "end": 44, "text": "phạm vi và nguồn"}]}, "Hai bảng thực ra là một bảng bị chia tùy tiện. Gợi ý: S15 · Bảng đối chiếu.": {"role": "explanatory-body", "selectedSpans": [{"start": 32, "end": 45, "text": "chia tùy tiện"}]}, "Ba cột có việc làm và đầu ra; cùng nhịp chữ.": {"role": "explanatory-body", "selectedSpans": [{"start": 10, "end": 28, "text": "việc làm và đầu ra"}]}, "Ba nhóm công việc cần được trình bày song song.": {"role": "explanatory-body", "selectedSpans": [{"start": 27, "end": 46, "text": "trình bày song song"}]}, "Ba tên nhóm; việc làm; đầu ra; các trường tương ứng.": {"role": "explanatory-body", "selectedSpans": [{"start": 35, "end": 51, "text": "trường tương ứng"}]}, "Công việc có thứ tự bắt buộc hoặc quan hệ phụ thuộc. Gợi ý: S19 · Kế hoạch bốn điểm kiểm.": {"role": "explanatory-body", "selectedSpans": [{"start": 34, "end": 51, "text": "quan hệ phụ thuộc"}]}, "Một biểu đồ lớn; chỉ số và diễn giải ở cột bên.": {"role": "explanatory-body", "selectedSpans": [{"start": 27, "end": 36, "text": "diễn giải"}]}, "Một biểu đồ cần chỉ số chính và giới hạn diễn giải bên cạnh.": {"role": "explanatory-body", "selectedSpans": [{"start": 32, "end": 50, "text": "giới hạn diễn giải"}]}, "Biểu đồ đúng họ; số liệu; đơn vị; phạm vi; nguồn và giới hạn.": {"role": "explanatory-body", "selectedSpans": [{"start": 43, "end": 60, "text": "nguồn và giới hạn"}]}, "Chưa có số liệu hoặc đang ghép các chỉ số khác mẫu số. Gợi ý: Thu thập và kiểm dữ liệu trước. Khi cần đối chiếu giá trị cụ thể thay vì xu hướng, dùng S15; bảng cũng phải có dữ liệu hợp lệ.": {"role": "explanatory-body", "selectedSpans": [{"start": 42, "end": 53, "text": "khác mẫu số"}, {"start": 74, "end": 92, "text": "kiểm dữ liệu trước"}]}, "Bốn bước có thứ tự và bảng trách nhiệm.": {"role": "explanatory-body", "selectedSpans": [{"start": 22, "end": 38, "text": "bảng trách nhiệm"}]}, "Trình bày kế hoạch có bốn bước và người chịu trách nhiệm.": {"role": "explanatory-body", "selectedSpans": [{"start": 34, "end": 56, "text": "người chịu trách nhiệm"}]}, "Bốn bước theo thứ tự; đầu ra; mốc kiểm; người phụ trách.": {"role": "explanatory-body", "selectedSpans": [{"start": 40, "end": 55, "text": "người phụ trách"}]}, "Công việc diễn ra song song và không có chuỗi bắt buộc. Gợi ý: S17 · Ba nhóm nội dung.": {"role": "explanatory-body", "selectedSpans": [{"start": 31, "end": 54, "text": "không có chuỗi bắt buộc"}]}, "Tín hiệu tiêu dùng, biểu đồ theo kỳ và ba nhóm sản phẩm minh họa.": {"role": "explanatory-body", "selectedSpans": [{"start": 39, "end": 55, "text": "ba nhóm sản phẩm"}]}, "Một câu hỏi cần đồng thời tín hiệu, xu hướng và nhóm sản phẩm.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 11, "text": "Một câu hỏi"}]}, "Các nhóm cùng phạm vi; dữ liệu theo kỳ; hình sản phẩm; nguồn.": {"role": "explanatory-body", "selectedSpans": [{"start": 23, "end": 38, "text": "dữ liệu theo kỳ"}]}, "Chỉ đang gom nhiều biểu đồ không cùng một câu hỏi. Gợi ý: S18 · Một biểu đồ và diễn giải.": {"role": "explanatory-body", "selectedSpans": [{"start": 27, "end": 49, "text": "không cùng một câu hỏi"}]}, "Khung phạm vi, biểu đồ tỷ trọng, ba chỉ số và bảng nhóm thị trường.": {"role": "explanatory-body", "selectedSpans": [{"start": 15, "end": 31, "text": "biểu đồ tỷ trọng"}]}, "Tóm tắt phạm vi thị trường bằng cơ cấu, chỉ số và bảng nhóm.": {"role": "explanatory-body", "selectedSpans": [{"start": 8, "end": 26, "text": "phạm vi thị trường"}]}, "Phạm vi; mẫu số; tỷ trọng; ba chỉ số; bảng phân nhóm.": {"role": "explanatory-body", "selectedSpans": [{"start": 9, "end": 15, "text": "mẫu số"}]}, "Tỷ trọng không cộng được hoặc nguồn/phạm vi không tương thích. Gợi ý: S18 · Biểu đồ, chỉ số và giới hạn.": {"role": "explanatory-body", "selectedSpans": [{"start": 30, "end": 61, "text": "nguồn/phạm vi không tương thích"}]}, "Hai hàng độc lập; mỗi hàng có bảng và một khung ảnh.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 16, "text": "Hai hàng độc lập"}]}, "Hai nhóm độc lập đều cần bảng kèm một hình minh họa.": {"role": "explanatory-body", "selectedSpans": [{"start": 4, "end": 16, "text": "nhóm độc lập"}]}, "Hai tên nhóm; hai bảng; hình liên quan với từng bảng.": {"role": "explanatory-body", "selectedSpans": [{"start": 24, "end": 38, "text": "hình liên quan"}]}, "Hai hàng cần đối chiếu trực tiếp nhưng khác cột hoặc đơn vị. Gợi ý: S15 · Bảng đối chiếu.": {"role": "explanatory-body", "selectedSpans": [{"start": 39, "end": 59, "text": "khác cột hoặc đơn vị"}]}, "Bốn nhóm giải thích và một ảnh dọc liên hệ chủ đề.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 19, "text": "Bốn nhóm giải thích"}]}, "Giải thích bốn mục nhỏ với một ảnh dọc liên hệ chủ đề.": {"role": "explanatory-body", "selectedSpans": [{"start": 31, "end": 38, "text": "ảnh dọc"}]}, "Bốn tiêu đề; diễn giải ngắn; ảnh có vai trò rõ.": {"role": "explanatory-body", "selectedSpans": [{"start": 36, "end": 46, "text": "vai trò rõ"}]}, "Mỗi mục cần nhiều bằng chứng hoặc dữ liệu chi tiết riêng. Gợi ý: S15 · Bảng đối chiếu.": {"role": "explanatory-body", "selectedSpans": [{"start": 34, "end": 50, "text": "dữ liệu chi tiết"}]}, "Các bước là cột; hành động, điểm khó và cải thiện là hàng.": {"role": "explanatory-body", "selectedSpans": [{"start": 28, "end": 49, "text": "điểm khó và cải thiện"}]}, "Phân tích một hành trình có bước, hành động, điểm khó và cải thiện.": {"role": "explanatory-body", "selectedSpans": [{"start": 45, "end": 66, "text": "điểm khó và cải thiện"}]}, "Tên bước; hành động; khó khăn; đề xuất cải thiện; phạm vi người dùng.": {"role": "explanatory-body", "selectedSpans": [{"start": 31, "end": 48, "text": "đề xuất cải thiện"}]}, "Các cột không phải các bước hoặc thứ tự không có ý nghĩa. Gợi ý: S15 · Bảng đối chiếu tiêu chí.": {"role": "explanatory-body", "selectedSpans": [{"start": 33, "end": 56, "text": "thứ tự không có ý nghĩa"}]}, "Biểu đồ tỷ trọng và hình sản phẩm; bảng số liệu và nhận định thương mại.": {"role": "explanatory-body", "selectedSpans": [{"start": 51, "end": 71, "text": "nhận định thương mại"}]}, "Giải thích cơ cấu sản phẩm bằng tỷ trọng và bảng sản lượng/doanh thu.": {"role": "explanatory-body", "selectedSpans": [{"start": 49, "end": 68, "text": "sản lượng/doanh thu"}]}, "Tỷ trọng; sản lượng; doanh thu; đơn vị; sản phẩm; cùng kỳ và nguồn.": {"role": "explanatory-body", "selectedSpans": [{"start": 50, "end": 66, "text": "cùng kỳ và nguồn"}]}, "Các phần không cùng tổng hoặc số minh họa bị nhận là số kinh doanh thật. Gợi ý: S18 · Biểu đồ, chỉ số và giới hạn.": {"role": "explanatory-body", "selectedSpans": [{"start": 9, "end": 24, "text": "không cùng tổng"}]}, "Bảng so sánh nhiều tiêu chí; bốn câu hỏi kết luận ở cột riêng.": {"role": "explanatory-body", "selectedSpans": [{"start": 33, "end": 49, "text": "câu hỏi kết luận"}]}, "So sánh đối thủ theo tiêu chí và tìm khoảng trống có bằng chứng.": {"role": "explanatory-body", "selectedSpans": [{"start": 21, "end": 49, "text": "tiêu chí và tìm khoảng trống"}]}, "Danh sách đối thủ; tiêu chí; thời điểm; nguồn; câu hỏi kết luận.": {"role": "explanatory-body", "selectedSpans": [{"start": 47, "end": 63, "text": "câu hỏi kết luận"}]}, "Tiêu chí không đồng nhất hoặc dữ liệu thiếu bị nhận là điểm yếu. Gợi ý: S15 · Bảng đối chiếu.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 24, "text": "Tiêu chí không đồng nhất"}]}, "Bảng có hạng, chỉ số, đơn vị và ghi chú; kết luận theo nhiều hàng.": {"role": "explanatory-body", "selectedSpans": [{"start": 41, "end": 49, "text": "kết luận"}]}, "Xếp hạng sản phẩm theo chỉ số có đơn vị và cơ sở rõ.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 17, "text": "Xếp hạng sản phẩm"}]}, "Tên sản phẩm; chỉ số; đơn vị; quy tắc xếp hạng; ghi chú và nguồn.": {"role": "explanatory-body", "selectedSpans": [{"start": 30, "end": 46, "text": "quy tắc xếp hạng"}]}, "Không có cơ sở xếp hạng, khác kỳ hoặc bỏ qua trường hợp đồng hạng. Gợi ý: S15 · Bảng đối chiếu.": {"role": "explanatory-body", "selectedSpans": [{"start": 56, "end": 65, "text": "đồng hạng"}]}, "Năm vai trò và một kiểu nút chỉ có biểu tượng. Khóa/chờ là trạng thái, không tạo thêm loại tài sản.": {"role": "explanatory-body", "selectedSpans": [{"start": 47, "end": 69, "text": "Khóa/chờ là trạng thái"}]}, "Việc tiếp theo quan trọng nhất trong một nhóm.": {"role": "explanatory-body", "selectedSpans": [{"start": 15, "end": 30, "text": "quan trọng nhất"}]}, "Không đặt nhiều nút chính cạnh nhau; không dùng để đánh dấu trang đang xem.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 25, "text": "Không đặt nhiều nút chính"}]}, "Thao tác hỗ trợ bên cạnh nút chính: xem thêm, quay lại hoặc hủy.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 15, "text": "Thao tác hỗ trợ"}]}, "Không dùng khi cần nhấn mạnh hơn việc chính.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 10, "text": "Không dùng"}]}, "Ưu tiên riêng của ngữ cảnh, như dùng lại tài sản trong Thư viện.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 13, "text": "Ưu tiên riêng"}]}, "Không tô vàng mọi nút; vàng không tự có nghĩa hoàn thành.": {"role": "explanatory-body", "selectedSpans": [{"start": 28, "end": 56, "text": "không tự có nghĩa hoàn thành"}]}, "Nếu hai thao tác cùng nổi bật, hãy xác định việc người dùng cần hoàn thành trước. Liên kết mở một đích; nút chạy một hành động.": {"role": "explanatory-body", "selectedSpans": [{"start": 64, "end": 80, "text": "hoàn thành trước"}, {"start": 108, "end": 126, "text": "chạy một hành động"}]}, "Cần giữ dấu nhận biết của lựa chọn, kể cả sau khi bỏ con trỏ.": {"role": "explanatory-body", "selectedSpans": [{"start": 8, "end": 21, "text": "dấu nhận biết"}]}, "Không dùng phản hồi rê chuột để thay trạng thái chọn; không giả trang hiện tại.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 28, "text": "Không dùng phản hồi rê chuột"}]}, "Mở một đích hỗ trợ trong dòng chữ khi không cần khung nút.": {"role": "explanatory-body", "selectedSpans": [{"start": 38, "end": 57, "text": "không cần khung nút"}]}, "Không dùng liên kết để chạy thao tác; giữ gạch dưới để nhận biết.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 19, "text": "Không dùng liên kết"}]}, "Thao tác quen thuộc trong vùng hẹp; cần tên đọc được bằng công nghệ hỗ trợ.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 19, "text": "Thao tác quen thuộc"}]}, "Không dùng một hình mơ hồ cho hành động quan trọng; không bỏ tên gọi.": {"role": "explanatory-body", "selectedSpans": [{"start": 52, "end": 68, "text": "không bỏ tên gọi"}]}, "Dấu đang chọn cần tồn tại sau tương tác. Rê chuột, nhấn và tiêu điểm bàn phím là phản hồi tạm thời.": {"role": "explanatory-body", "selectedSpans": [{"start": 81, "end": 98, "text": "phản hồi tạm thời"}]}, "Chọn màu theo vai trò; giữ viền, bóng mềm và nhãn rõ.": {"role": "explanatory-body", "selectedSpans": [{"start": 23, "end": 31, "text": "giữ viền"}]}, "Phản hồi tạm thời; không coi là đang chọn hoặc hoàn tất.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 17, "text": "Phản hồi tạm thời"}]}, "Giữ vị trí/kích thước; nhấn chưa có nghĩa thao tác thành công.": {"role": "explanatory-body", "selectedSpans": [{"start": 4, "end": 21, "text": "vị trí/kích thước"}]}, "Giữ dấu viền rõ và khoảng trống quanh dấu; không chỉ đổi màu.": {"role": "explanatory-body", "selectedSpans": [{"start": 43, "end": 60, "text": "không chỉ đổi màu"}]}, "Giữ dấu nhận biết; trang, tab và nút bật/tắt dùng trạng thái đúng đối tượng.": {"role": "explanatory-body", "selectedSpans": [{"start": 50, "end": 65, "text": "trạng thái đúng"}]}, "Nêu lý do ngay cạnh nút; khóa thực sự, không chỉ tô màu nhạt.": {"role": "explanatory-body", "selectedSpans": [{"start": 25, "end": 37, "text": "khóa thực sự"}]}, "Báo đang xử lý; ngăn nhấn lặp và giữ vùng nút. Mẫu hiện tại mô phỏng cục bộ.": {"role": "explanatory-body", "selectedSpans": [{"start": 16, "end": 29, "text": "ngăn nhấn lặp"}]}, "Thông báo bằng chữ cạnh nút; chỉ hướng dẫn thử lại khi áp dụng được.": {"role": "explanatory-body", "selectedSpans": [{"start": 29, "end": 50, "text": "chỉ hướng dẫn thử lại"}]}, "Nhãn luôn hiện; hướng dẫn không nằm riêng trong placeholder.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 14, "text": "Nhãn luôn hiện"}]}, "Phần chọn hiển thị nội dung riêng; hỗ trợ phím mũi tên.": {"role": "explanatory-body", "selectedSpans": [{"start": 19, "end": 33, "text": "nội dung riêng"}]}, "Chỉ đánh dấu khi việc đã được kiểm; giữ nhãn sát đúng điều khiển.": {"role": "explanatory-body", "selectedSpans": [{"start": 17, "end": 34, "text": "việc đã được kiểm"}]}, "Đọc thêm rồi trở về đúng vị trí; đóng bằng Escape.": {"role": "explanatory-body", "selectedSpans": [{"start": 20, "end": 31, "text": "đúng vị trí"}]}, "So sánh một lượng giữa các nhóm; chọn hướng, nhóm con, giá trị có dấu hoặc mục tiêu theo mục đích đọc.": {"role": "explanatory-body", "selectedSpans": [{"start": 8, "end": 31, "text": "một lượng giữa các nhóm"}]}, "Số công việc: 8, 6, 10. Trục 0–12.": {"role": "role-exception", "selectedSpans": []}, "Không dùng thay phân bố theo khoảng, tổng cộng dồn, thời lượng hay hai lần đo theo cặp.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 15, "text": "Không dùng thay"}]}, "Biến thể trong cùng họ: Cột theo kỳ, Cột theo nhóm, Thanh hai phía, Chấm có trục so sánh, Thực tế và mục tiêu.": {"role": "role-exception", "selectedSpans": []}, "Theo dõi một hoặc nhiều lượng cùng đơn vị qua các mốc có thứ tự; chọn phần tô, nhiều ô nhỏ hoặc ngưỡng khi cần.": {"role": "explanatory-body", "selectedSpans": [{"start": 50, "end": 63, "text": "mốc có thứ tự"}]}, "Bốn kỳ: 2, 5, 4, 9. Trục 0–10.": {"role": "role-exception", "selectedSpans": []}, "Không nối các nhóm không có thứ tự, coi các tiêu chí độc lập là thời gian hoặc tự thêm trục đơn vị thứ hai.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 18, "text": "Không nối các nhóm"}]}, "Biến thể trong cùng họ: Vùng theo thời gian, Đường nhỏ theo nhóm, Chuỗi có ngưỡng theo dõi, Cột và đường cùng trục.": {"role": "role-exception", "selectedSpans": []}, "Đọc tỷ phần của một tổng đã biết; dùng vòng tiến độ khi có số hoàn tất và mục tiêu.": {"role": "explanatory-body", "selectedSpans": [{"start": 16, "end": 32, "text": "một tổng đã biết"}]}, "Xong 60, còn 40; tổng 100.": {"role": "role-exception", "selectedSpans": []}, "Không dùng cho phần âm, nhiều tổng không liên quan hoặc tiến độ chưa có mẫu số.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 22, "text": "Không dùng cho phần âm"}]}, "Biến thể trong cùng họ: Tròn cơ cấu, Vòng tiến độ.": {"role": "role-exception", "selectedSpans": []}, "So sánh các phần cộng thành tổng; chọn rõ số tuyệt đối hoặc tỷ lệ100%.": {"role": "explanatory-body", "selectedSpans": [{"start": 8, "end": 32, "text": "các phần cộng thành tổng"}]}, "A có 4+6=10; B có 3+5=8 mục.": {"role": "role-exception", "selectedSpans": []}, "Không đổi chế độ mà bỏ tổng, mẫu số hay đơn vị; không xếp chồng các đại lượng không cộng được.": {"role": "explanatory-body", "selectedSpans": [{"start": 48, "end": 63, "text": "không xếp chồng"}]}, "Biến thể trong cùng họ: Thanh cơ cấu 100%.": {"role": "role-exception", "selectedSpans": []}, "Xem quan hệ giữa hai lượng đo trên từng quan sát.": {"role": "explanatory-body", "selectedSpans": [{"start": 17, "end": 29, "text": "hai lượng đo"}]}, "Năm cặp x/y; hai trục 0–10. Không suy quan hệ nhân quả.": {"role": "role-exception", "selectedSpans": []}, "Không suy nhân quả, nối theo thời gian khi chưa có thứ tự hoặc coi tọa độ là địa lý.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 18, "text": "Không suy nhân quả"}]}, "Xem phân bố quan sát số theo các khoảng có ranh giới rõ.": {"role": "explanatory-body", "selectedSpans": [{"start": 43, "end": 55, "text": "ranh giới rõ"}]}, "Ba khoảng bằng nhau: 0–10 có 2, 10–20 có 5, 20–30 có 3 quan sát.": {"role": "role-exception", "selectedSpans": []}, "Không coi nhãn nhóm là khoảng số hoặc dùng tần số làm giá trị đo ban đầu.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 19, "text": "Không coi nhãn nhóm"}]}, "Đọc trung vị, tứ phân vị và khoảng nhỏ nhất/lớn nhất của mẫu.": {"role": "explanatory-body", "selectedSpans": [{"start": 14, "end": 24, "text": "tứ phân vị"}]}, "Tóm tắt mẫu: nhỏ nhất 2, tứ phân vị 4 và 8, trung vị 6, lớn nhất 10.": {"role": "role-exception", "selectedSpans": []}, "Không thay tứ phân vị bằng mở/đóng hoặc tự đổi râu thành quy tắc ngoại lệ.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 21, "text": "Không thay tứ phân vị"}]}, "Giải thích tổng cuối bằng tổng đầu và các khoản tăng/giảm theo thứ tự.": {"role": "explanatory-body", "selectedSpans": [{"start": 48, "end": 69, "text": "tăng/giảm theo thứ tự"}]}, "Bắt đầu 8, thêm 4, bớt 2, kết thúc 10. Giữ dấu tăng/giảm.": {"role": "role-exception", "selectedSpans": []}, "Không dùng các thanh có dấu độc lập mà không tính mốc cộng dồn.": {"role": "explanatory-body", "selectedSpans": [{"start": 39, "end": 62, "text": "không tính mốc cộng dồn"}]}, "Đối chiếu giá trị trong lưới; chọn tọa độ nhóm/kỳ, ngày/tuần hoặc nhóm bắt đầu/tuổi nhóm.": {"role": "explanatory-body", "selectedSpans": [{"start": 66, "end": 78, "text": "nhóm bắt đầu"}]}, "Hai nhóm, ba kỳ; mỗi ô giữ số. Màu hỗ trợ đọc, không thay số.": {"role": "role-exception", "selectedSpans": []}, "Không bỏ kiểu tọa độ, mẫu số, ô chưa quan sát hoặc dùng màu chú ý như thang đo liên tục.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 20, "text": "Không bỏ kiểu tọa độ"}]}, "Biến thể trong cùng họ: Lịch có giá trị, Giữ lại theo nhóm bắt đầu.": {"role": "role-exception", "selectedSpans": []}, "Theo dõi số còn lại của cùng một nhóm qua các bước nối tiếp.": {"role": "explanatory-body", "selectedSpans": [{"start": 24, "end": 37, "text": "cùng một nhóm"}]}, "Cùng một nhóm:20→12→6 mục qua ba bước.": {"role": "role-exception", "selectedSpans": []}, "Không gọi số lượng các nhóm độc lập là tỷ lệ chuyển bước.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 18, "text": "Không gọi số lượng"}]}, "Đọc các phần của một tổng theo diện tích ô chữ nhật.": {"role": "explanatory-body", "selectedSpans": [{"start": 31, "end": 51, "text": "diện tích ô chữ nhật"}]}, "Ba phần 50,30,20 mục; tổng 100.": {"role": "role-exception", "selectedSpans": []}, "Không đọc giá trị bằng riêng chiều rộng hoặc tuyên bố mẫu hiện có nhiều tầng phân cấp.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 17, "text": "Không đọc giá trị"}]}, "Đọc thời điểm bắt đầu, kết thúc, chồng lấn hoặc trạng thái trên một trục thời gian.": {"role": "explanatory-body", "selectedSpans": [{"start": 68, "end": 82, "text": "trục thời gian"}]}, "A ngày 1–3; B ngày 3–6; C ngày 5–8.": {"role": "role-exception", "selectedSpans": []}, "Không coi độ dài là lượng trạng thái hay tỷ lệ; phải giữ quy ước tính ngày đầu/cuối.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 16, "text": "Không coi độ dài"}]}, "Biến thể trong cùng họ: Dải trạng thái theo thời gian.": {"role": "role-exception", "selectedSpans": []}, "So sánh hai lần đo cùng đơn vị cho từng đối tượng; chọn bố cục dốc hoặc hai đầu theo hàng.": {"role": "explanatory-body", "selectedSpans": [{"start": 19, "end": 30, "text": "cùng đơn vị"}]}, "A 4→7; B 8→6; C 2→5 mục.": {"role": "role-exception", "selectedSpans": []}, "Không ghép khác đối tượng hoặc ngụ ý đã đo đường đi liên tục giữa hai đầu.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 25, "text": "Không ghép khác đối tượng"}]}, "Biến thể trong cùng họ: Hai đầu theo nhóm.": {"role": "role-exception", "selectedSpans": []}, "Đọc các quan hệ cần hoàn thành trước hoặc đầu vào phụ thuộc.": {"role": "explanatory-body", "selectedSpans": [{"start": 20, "end": 36, "text": "hoàn thành trước"}]}, "Không suy lượng luồng hay điều kiện lựa chọn từ cạnh phụ thuộc.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 21, "text": "Không suy lượng luồng"}]}, "Đọc lượng đi từ nguồn đến đích theo độ rộng luồng.": {"role": "explanatory-body", "selectedSpans": [{"start": 36, "end": 49, "text": "độ rộng luồng"}]}, "A 10 mục chia thành B 6 và C 4.": {"role": "role-exception", "selectedSpans": []}, "Không thay lượng bằng mũi tên bằng nhau hoặc bỏ quy tắc bảo toàn/thất thoát.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 16, "text": "Không thay lượng"}]}, "Đối chiếu một đối tượng trên nhiều tiêu chí độc lập.": {"role": "explanatory-body", "selectedSpans": [{"start": 35, "end": 51, "text": "tiêu chí độc lập"}]}, "Ba tiêu chí đều thang 0–10 điểm; hai nhóm A/B.": {"role": "role-exception", "selectedSpans": []}, "Không coi trục tiêu chí là các kỳ thời gian hoặc quên đơn vị/thang từng trục.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 23, "text": "Không coi trục tiêu chí"}]}, "Đọc mở, cao, thấp và đóng trong từng kỳ.": {"role": "explanatory-body", "selectedSpans": [{"start": 13, "end": 25, "text": "thấp và đóng"}]}, "Ba kỳ; mở/cao/thấp/đóng trên thang 0–10 điểm minh họa.": {"role": "role-exception", "selectedSpans": []}, "Không dùng thay hộp phân bố hoặc để mở/đóng nằm ngoài thấp/cao.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 27, "text": "Không dùng thay hộp phân bố"}]}, "Minh họa giá trị của các vùng tự tạo có nhãn rõ.": {"role": "explanatory-body", "selectedSpans": [{"start": 25, "end": 36, "text": "vùng tự tạo"}]}, "Ba vùng A 4; B 7; C 2 mục. Hình không theo địa lý thật.": {"role": "role-exception", "selectedSpans": []}, "Không nhận là địa giới thật, bản đồ số liệu địa lý hoặc diện tích tỷ lệ.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 27, "text": "Không nhận là địa giới thật"}]}, "Đọc một chỉ số tổng và các dòng số chi tiết cần đối chiếu.": {"role": "explanatory-body", "selectedSpans": [{"start": 8, "end": 19, "text": "chỉ số tổng"}]}, "Tổng 15 mục = Đọc 6 + Dựng 5 + Kiểm 4.": {"role": "role-exception", "selectedSpans": []}, "Không tính thẻ số là một kiểu mã hóa thống kê mới hoặc bỏ phép cộng đối chiếu.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 17, "text": "Không tính thẻ số"}]}, "Chọn hướng xử lý dựa trên các điều kiện có nhánh được ghi rõ.": {"role": "explanatory-body", "selectedSpans": [{"start": 30, "end": 48, "text": "điều kiện có nhánh"}]}, "Hai điều kiện: có nguồn và cần duyệt; ba hướng đi.": {"role": "role-exception", "selectedSpans": []}, "Không dùng cạnh phụ thuộc thay cho điều kiện hoặc bỏ tên nhánh có/không.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 25, "text": "Không dùng cạnh phụ thuộc"}]}, "Đọc hành động, điểm khó và cách cải thiện theo từng bước.": {"role": "explanatory-body", "selectedSpans": [{"start": 42, "end": 56, "text": "theo từng bước"}]}, "Ba bước; đối chiếu hành động, điểm khó và cách cải thiện.": {"role": "role-exception", "selectedSpans": []}, "Không coi văn bản định tính là mức nhiệt hay số đo trên ma trận.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 27, "text": "Không coi văn bản định tính"}]}, "Đọc vị trí và ranh giới các bang Hoa Kỳ; giữ Alaska và Hawaii trong khung.": {"role": "explanatory-body", "selectedSpans": [{"start": 45, "end": 61, "text": "Alaska và Hawaii"}]}, "50 tiểu bang và DC, Alaska và Hawaii ở ô phụ; chọn vùng để đọc tên.": {"role": "role-exception", "selectedSpans": []}, "Không coi màu hình dạng là số liệu, ô phụ là cùng tỷ lệ hoặc địa cầu là công cụ phân loại chủ quyền.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 23, "text": "Không coi màu hình dạng"}]}, "Đọc vị trí trên bản đồ Việt Nam; giữ đầy đủ nhãn đảo và quần đảo trong khung.": {"role": "explanatory-body", "selectedSpans": [{"start": 44, "end": 64, "text": "nhãn đảo và quần đảo"}]}, "Đất liền, lớp đảo nhỏ và bảy vị trí đại diện có nguồn; hai ô Hoàng Sa và Trường Sa.": {"role": "role-exception", "selectedSpans": []}, "Hoàng Sa và Trường Sa (Việt Nam) được giữ trong khung bản đồ và nhãn gốc. Ký hiệu vị trí không tạo thêm đường ranh giới biển.": {"role": "explanatory-body", "selectedSpans": [{"start": 89, "end": 124, "text": "không tạo thêm đường ranh giới biển"}]}, "Đọc vị trí trên quả địa cầu. Hình trong tài liệu là một góc nhìn tĩnh.": {"role": "explanatory-body", "selectedSpans": [{"start": 56, "end": 69, "text": "góc nhìn tĩnh"}]}, "Khối cầu xoay có kéo, phím, đổi góc nhìn và bản đồ phẳng dự phòng.": {"role": "role-exception", "selectedSpans": []}, "Hình tĩnh trong PDF. Mở mẫu HTML để xoay địa cầu và kiểm tra vị trí.": {"role": "explanatory-body", "selectedSpans": [{"start": 21, "end": 32, "text": "Mở mẫu HTML"}]}, "Quy tắc · Mẫu gốc · Cách dùng": {"role": "role-exception", "selectedSpans": []}, "Tổng quan · Biểu tượng · Nền thương hiệu · Trình chiếu · Giao diện · Biểu đồ": {"role": "role-exception", "selectedSpans": []}, "Số trang tính cả bìa. Bấm số trang để tới mẫu; dùng mã để gọi đúng loại.": {"role": "explanatory-body", "selectedSpans": [{"start": 22, "end": 34, "text": "Bấm số trang"}]}, "Chuẩn, tài sản và ứng dụng": {"role": "role-exception", "selectedSpans": []}, "Quy tắc định hình chữ, màu và bố cục; Thư viện lưu tài sản; Ứng dụng kết hợp chúng thành đầu ra. Cả ba dùng cùng mô hình và phiên bản KAI, không tạo ba bộ chuẩn.": {"role": "explanatory-body", "selectedSpans": [{"start": 18, "end": 26, "text": "chữ, màu"}, {"start": 108, "end": 133, "text": "cùng mô hình và phiên bản"}]}, "Lửa trại là logo chính KAI; giữ hình và bảng màu gốc, không thay bằng khiên, la bàn hoặc mascot. Hiệp sĩ chỉ dẫn chuyện và minh họa; cảnh trại trong ảnh nền không phải dấu logo.": {"role": "explanatory-body", "selectedSpans": [{"start": 12, "end": 22, "text": "logo chính"}, {"start": 40, "end": 48, "text": "bảng màu"}]}, "Chuẩn → Thư viện → Ứng dụng": {"role": "role-exception", "selectedSpans": []}, "Vai trò, giá trị, biến thể, tổ hợp, bố cục, giọng văn và phép kiểm có một nguồn; mẫu hiển thị và tài liệu sinh cùng phiên bản. Thư viện giữ mã ổn định, chức năng, cấu tạo, trạng thái, nguồn, quyền, phụ thuộc và bằng chứng; không tự thêm bộ chữ/màu. Ứng dụng kết hợp quy tắc với tài sản và liên kết phần đã dùng, không tạo chuẩn độc lập. Đọc chuẩn → phân loại chức năng → tìm tài sản → ánh xạ → dựng → kiểm nguồn/hiển thị → ghi bằng chứng → nhận đúng phạm vi. Mâu thuẫn chuẩn phải nêu quy tắc, ảnh hưởng và phương án tương thích. Ngoại lệ/sửa chuẩn cần phạm vi, lý do, phiên bản và bằng chứng; không âm thầm thêm cỡ, màu, font. Thay quy tắc phải kiểm các nơi bị ảnh hưởng. KAI hiện có Slide và tài liệu lý thuyết trong Ứng dụng. App/Web là loại đầu ra hệ thống có thể phục vụ, chưa có nghĩa đã được bổ sung hay kiểm trong gói này.": {"role": "explanatory-body", "selectedSpans": [{"start": 312, "end": 335, "text": "không tạo chuẩn độc lập"}, {"start": 776, "end": 789, "text": "chưa có nghĩa"}]}, "Xác định nội dung, hành động, dữ liệu, quan hệ và phần phải giữ; không bắt đầu bằng đổi màu. Chọn vai trò chữ, tổ hợp, cấu tạo và trạng thái đã có; phần chưa hỗ trợ cần bổ sung có phạm vi. Kiểm chữ, khoảng cách, tương phản, chuyển động, bàn phím và nội dung ở rộng/hẹp, sáng/tối. Giữ mã tài sản, phiên bản, nguồn, giá trị thiết kế và tệp cần thiết; chỉ nhận dùng khi đủ bằng chứng và quyền.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 17, "text": "Xác định nội dung"}, {"start": 50, "end": 63, "text": "phần phải giữ"}]}, "Lửa trại là logo chính; hiệp sĩ là mascot minh họa, không thay dấu. SVG 32 × 32; vùng mực x=3, y=2, rộng 26, cao 29. Giữ lửa, đế, lỗ bên trong, viewBox/đường/màu; contain và co giãn đều, không vẽ lại/kéo méo. Cảnh trại ảnh nền không phải logo.": {"role": "explanatory-body", "selectedSpans": [{"start": 52, "end": 66, "text": "không thay dấu"}, {"start": 174, "end": 185, "text": "co giãn đều"}]}, "Vùng trống và cỡ nhỏ — đề nghị": {"role": "role-exception", "selectedSpans": []}, "Chừa 3 đơn vị quanh vùng mực và khung màn hình tối thiểu 32 px là đề nghị xem cục bộ, chưa là chuẩn chính thức; ưu tiên bội số nguyên. Tăng đệm thay sửa dấu; cỡ in tối thiểu chưa kiểm, phải xem bản xuất thật.": {"role": "explanatory-body", "selectedSpans": [{"start": 86, "end": 110, "text": "chưa là chuẩn chính thức"}, {"start": 194, "end": 207, "text": "bản xuất thật"}]}, "kai-bonfire-light.svg: mực #233629; kai-bonfire-dark.svg: mực #F5F1E5; cả hai vàng #E2A336. Chọn theo nền ngay sau dấu, không theo chế độ toàn trang. Vector gốc trong suốt, không hình chữ nhật nền cố định/không cần AI xóa nền; hòa trộn/lọc không là xuất alpha.": {"role": "explanatory-body", "selectedSpans": [{"start": 102, "end": 118, "text": "nền ngay sau dấu"}]}, "Ưu tiên vùng kem/xanh yên; nền ảnh/video nhiễu thì đổi vị trí trước, thiếu vùng yên mới đề nghị mặt nền kín có đệm rõ. Đặt có chủ đích ở đầu trang/góc slide/khung kết, tránh đầu người/phụ đề/tiêu đề/điều khiển. Website hẹp giữ toàn hình dưới chữ, không cắt ngọn lửa.": {"role": "explanatory-body", "selectedSpans": [{"start": 51, "end": 67, "text": "đổi vị trí trước"}, {"start": 247, "end": 265, "text": "không cắt ngọn lửa"}]}, "Không gắn bóng, viền trang trí hoặc quầng sáng vào dấu; bóng thuộc lớp chức năng chứa dấu. Kiểm đúng SVG trên sáng/tối/ô caro ở 32/64 px và cỡ thật, tỷ lệ/vùng trống; không tạo lại vector trong suốt khi nguồn đã đúng.": {"role": "explanatory-body", "selectedSpans": [{"start": 140, "end": 147, "text": "cỡ thật"}, {"start": 167, "end": 187, "text": "không tạo lại vector"}]}, "Biến thể và đề nghị triển khai cục bộ chưa tự thành tài sản sản xuất đã đăng ký, quyền công bố hoặc quyền đưa vào bộ mặc định; dùng theo phạm vi xem xét cục bộ được chọn.": {"role": "explanatory-body", "selectedSpans": [{"start": 137, "end": 159, "text": "phạm vi xem xét cục bộ"}]}, "Giữ bảy vai trò đã khai báo; giãn chữ 0 px theo mẫu nguồn. Một ý chính và một cấp lớn nhất. Chỉ thêm tiêu đề phụ khi có phần phụ thật; không dùng tiêu đề làm nhãn điều khiển, chú thích thay thân bài hoặc chữ kỹ thuật thay giải thích thường. Cambria: tiêu đề và lời trích, độ đậm 400/700, dự phòng serif. Segoe UI: thân bài, nhãn, số liệu, liên kết và điều khiển, 400/700, dự phòng sans-serif. Consolas: lệnh/mã cần chép, 400, dự phòng monospace. Font nguồn là font hệ thống; không suy quyền đóng gói hay phân phối. Liên kết có đích thật, gạch chân và trạng thái bàn phím; không chỉ đổi màu. Lời trích giữ nguồn; không thêm đường dọc khi đã có dấu trích. Nhãn nhấn và nút dùng đậm 700.": {"role": "explanatory-body", "selectedSpans": [{"start": 4, "end": 15, "text": "bảy vai trò"}, {"start": 572, "end": 589, "text": "không chỉ đổi màu"}]}, "Tổ hợp và căn nội dung": {"role": "role-exception", "selectedSpans": []}, "Tổ hợp tiêu đề/tên nhóm/thân bài/chú thích: slide 1280 × 720 dùng 64/32/24/20 px; trang đọc dùng 48/24/20/16 px; màn hình hẹp dùng 32/16/16/16 px. Không lấy cỡ trung gian giữa các bộ. Tổ hợp theo ngữ cảnh: đọc dữ liệu rộng 40/20/16 px, hẹp 32/16/16 px; lời trích rộng 40/20/20/16 px, hẹp 32/16/16/16 px; khối kỹ thuật rộng 48/24/20/18/16 px, hẹp 32/16/16/16/16 px theo đúng vai trò được ghi ở nguồn. Khối chỉ có một nhãn/từ/các dòng ngang cấp dùng đậm 700 cho nhãn. Khối có phân cấp giữ vai trò riêng; nhãn trục, chú thích và đường nối giữ độ đậm theo chức năng. Đổi độ đậm phải kiểm lại độ rộng và khoảng hở. Một nhóm chữ/số/icon độc lập trong khung căn giữa hai chiều, nhiều dòng tính như một nhóm; cân khoảng hai bên trong sai số 1 px ở kích thước đọc, giữ đệm và không tính bóng vào tâm. Khối nhiều nhóm giữ cấu trúc đọc; không suy thành căn giữa cả thẻ. Đo sau tải font ở Thư viện, Ứng dụng, trang đọc và slide; kiểm dấu Việt và số: Ẩn / Đúng / 01 / 1.335 / 42,47%. Nội dung dài phải tăng khung, đổi bố cục hoặc tiếp trang; không giảm chữ.": {"role": "explanatory-body", "selectedSpans": [{"start": 547, "end": 561, "text": "theo chức năng"}, {"start": 767, "end": 790, "text": "không tính bóng vào tâm"}]}, "Nền chính cho nội dung; không dùng làm chữ trên nền sáng.": {"role": "explanatory-body", "selectedSpans": [{"start": 24, "end": 42, "text": "không dùng làm chữ"}]}, "Khung nội dung và điều khiển; không tạo thêm cấp chữ.": {"role": "explanatory-body", "selectedSpans": [{"start": 30, "end": 52, "text": "không tạo thêm cấp chữ"}]}, "Nội dung thường, số liệu và nhãn trên bề mặt thường.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 15, "text": "Nội dung thường"}]}, "Tiêu đề, biểu tượng và keyword giải thích đậm; không tô tất cả thân bài.": {"role": "explanatory-body", "selectedSpans": [{"start": 47, "end": 62, "text": "không tô tất cả"}]}, "Nhãn nhỏ có chữ trắng; đường và khung dẫn hướng; không dùng chữ vàng nhỏ trên giấy.": {"role": "explanatory-body", "selectedSpans": [{"start": 12, "end": 21, "text": "chữ trắng"}]}, "Vùng phân nhóm hoặc trạng thái phụ; luôn kiểm cặp chữ.": {"role": "explanatory-body", "selectedSpans": [{"start": 41, "end": 53, "text": "kiểm cặp chữ"}]}, "Khung nội dung ở chế độ tối.": {"role": "explanatory-body", "selectedSpans": [{"start": 17, "end": 27, "text": "chế độ tối"}]}, "Tiêu đề và nhấn hỗ trợ trên nền tối.": {"role": "explanatory-body", "selectedSpans": [{"start": 11, "end": 22, "text": "nhấn hỗ trợ"}]}, "Đệm rộng 32 px, hẹp 16 px, trong thẻ 24 px; trong nhóm 16 px, giữa nhóm hướng dẫn 32 px. Khoảng nhóm 24 px; kiểm lại khi mở chi tiết, xuống dòng hoặc đổi màn hình, không dựa vào khoảng mặc định. Khung nội dung/điều khiển bo 4 px, hình mang dữ liệu 2 px; phần nối sát nhau giữ thẳng, chỉ bo đường bao ngoài. Giữa thẻ ít nhất 24 px và còn ít nhất 24 px giữa phần đã vẽ, tính bóng, viền và vòng bàn phím. Khung có chú thích bên ngoài giữ ít nhất 24 px khoảng trống thực sau phần đã vẽ; mốc 16 px tăng 50% thành 24 px. Chú thích vẫn thuộc hình phía trên; không áp dụng khoảng này cho dòng chữ hoặc icon–chữ. Bóng 6 px không chạm thẻ bên cạnh; khi bóng đổi, tăng khoảng hộp để giữ khoảng trống thực.": {"role": "explanatory-body", "selectedSpans": [{"start": 356, "end": 366, "text": "phần đã vẽ"}, {"start": 449, "end": 466, "text": "khoảng trống thực"}]}, "Hình gốc, nét và tỷ lệ": {"role": "role-exception", "selectedSpans": []}, "Đo mép đã vẽ, gồm đầu nét và góc nối; chi tiết độc lập không chạm viền bao. Mối nối cấu tạo có chủ ý phải giữ và ghi lý do. Hình đối xứng dựng quanh trục; kim la bàn là hình thoi cân quanh tâm 16/16, không nắn đỉnh bằng mắt. Cùng chức năng giữ nét đo vuông góc cạnh, kể cả cạnh chéo. Khiên dùng viền 4 đơn vị SVG. Họ nón 32 đơn vị giữ khoảng hở đã vẽ tối thiểu 1 đơn vị; mắt 0,9 so với viền ngoài 2 đơn vị. Mào và cánh nối thân là cấu tạo có chủ ý, không làm mảnh mọi icon. Khung 32 có khoảng ngoài ít nhất 4 đơn vị. Cặp nhận diện cùng vai trò có vùng hình rộng 24 px, cao khoảng 24 px; sai lệch rộng/cao tối đa 5%, tâm tối đa 1 đơn vị. Đây là tiêu chí KAI, không áp cho mọi hình; hình dài/hẹp có lý do riêng, không kéo méo. Giữ tỷ lệ, tâm, nét và một hình gốc cho bản tĩnh/chuyển động. Đo vùng thực kể cả stroke, kiểm cặp ở 24/32/64 px và minh họa 220 px, sáng/tối; kiểm đầu/giữa/cuối/dừng sau hiệu chỉnh, không tăng CSS riêng từng nơi.": {"role": "explanatory-body", "selectedSpans": [{"start": 38, "end": 74, "text": "chi tiết độc lập không chạm viền bao"}, {"start": 725, "end": 744, "text": "Giữ tỷ lệ, tâm, nét"}]}, "Chữ, logo và dấu dữ liệu giữ phẳng; chừa khoảng cho phần bóng đã vẽ.": {"role": "explanatory-body", "selectedSpans": [{"start": 25, "end": 34, "text": "giữ phẳng"}]}, "Dùng đúng các vai trò và mã ở bảng màu gốc KAI; phần chưa có vai trò không tự được dùng. Nền không tự trở thành màu chữ; bề mặt không tạo thêm cấp chữ. Không thêm bảng màu riêng cho Thư viện hay Ứng dụng. Giấy và bề mặt sáng dùng chữ mực; nền xanh đậm dùng chữ sáng. Xanh hỗ trợ dành cho tiêu đề, icon và từ khóa giải thích đậm 700 theo cỡ thân bài; vàng dành cho nhãn có chữ trắng, đường, khung và chi tiết nhấn, không dùng chữ vàng nhỏ trên giấy. Chế độ tối dùng mực sáng và xanh hỗ trợ tối. Đổi giá trị màu phải kiểm lại tương phản, trạng thái và mọi nơi dùng bị ảnh hưởng. Trạng thái chọn giữ cả chữ và hình; màu không thay nhãn, quan hệ hoặc bằng chứng.": {"role": "explanatory-body", "selectedSpans": [{"start": 48, "end": 68, "text": "phần chưa có vai trò"}, {"start": 128, "end": 150, "text": "không tạo thêm cấp chữ"}]}, "Đây là thông số đề xuất theo yêu cầu, không tự thành quy định gốc của brandkit. KAI dùng bóng cứng; giữ màu, chữ, hình và chức năng nguồn. Thông số x/y/blur/spread, px; opacity 1: điều khiển 3/3/0/0; bề mặt và lớp nổi 6/6/0/0; hover 4/4/0/0; pressed 1/1/0/0. Disabled vẫn có bóng nhỏ 1 px. Thẻ, bảng, khung biểu đồ, giao diện và bố cục độc lập nhận một bóng ngoài. Nhóm nối liền nhận bóng trên đường bao chung; không đổ bóng lên mọi lớp con hoặc từng tab. Bóng thuộc khung biểu đồ; không thêm vào dấu dữ liệu, trục, nhãn, chữ hoặc số. Logo, ảnh và nét icon giữ nguồn; lớp chức năng chứa chúng mới nhận bóng khi cần. Giữ ít nhất 24 px phần đã vẽ giữa khối độc lập, tính viền bàn phím. Chọn màu bóng theo nền nhận trực tiếp, kể cả vùng sáng nằm trong trang tối. Áp dụng cùng vai trò ở website, ứng dụng, slide, PDF, thiết kế và biên tập; giữ bóng khi in. Chỉ chế độ màu tương phản của hệ thống được thay bóng bằng viền hệ thống. Kiểm bản xuất thật, thao tác và Tab; HTML không chứng minh PDF đã đạt.": {"role": "explanatory-body", "selectedSpans": [{"start": 38, "end": 65, "text": "không tự thành quy định gốc"}, {"start": 349, "end": 363, "text": "một bóng ngoài"}]}, "Áp dụng cho thân bài KAI viết/chuyển thể ở mọi đầu ra; nguyên văn, mã, đường dẫn và phần phải sao chép nguyên vẹn giữ nguồn. Nhấn khái niệm, định nghĩa, điều kiện, giới hạn, kết luận hoặc hành động bằng đậm 700, xanh hỗ trợ, kế thừa cỡ thân bài. Phần lớn câu giữ thường; không tô toàn đoạn, nhấn từ nối/nguồn/mọi số hoặc chọn từ theo số lượng cố định. Ý song song dùng danh sách; bước có thứ tự dùng số. Icon chỉ thay dấu đầu dòng khi thêm nghĩa; nếu không, giữ dấu thường. Đọc riêng các từ nhấn rồi đọc toàn đoạn để kiểm nghĩa, phủ định và phạm vi; kiểm khoảng cách/tương phản rộng–hẹp, sáng–tối.": {"role": "explanatory-body", "selectedSpans": [{"start": 246, "end": 269, "text": "Phần lớn câu giữ thường"}, {"start": 529, "end": 548, "text": "phủ định và phạm vi"}]}, "Khuyến nghị đối ứng dùng nhãn và dấu đối ứng: dấu kiểm là nên làm, × là nên tránh, không phải đã hoàn tất hoặc lỗi thực tế. Mỗi mục nên/tránh giữ dấu khi tách khỏi tiêu đề. Icon bổ trợ, không thay chữ: khung 24 px, nét 2 px, khoảng trống 4 px. Icon lặp nghĩa chữ ẩn khỏi trình đọc màn hình; icon chứa thông tin mới có tên/chú giải tương đương. Xanh cho khuyến nghị; vàng nhắc chú ý tránh, không phải trạng thái lỗi. Dấu tránh có thể dùng mực trên giấy cạnh nhãn vàng; không thêm đỏ/tím. Vàng dùng cho nền nhãn chữ trắng, đường/khung hoặc nhấn minh họa, không dùng chữ vàng nhỏ. Che màu vẫn phải hiểu quan hệ và trạng thái qua nhãn/hình; kiểm khoảng thở và thứ tự đọc cả hai chế độ.": {"role": "explanatory-body", "selectedSpans": [{"start": 186, "end": 200, "text": "không thay chữ"}, {"start": 389, "end": 414, "text": "không phải trạng thái lỗi"}]}, "Mỗi thành phần nêu chức năng, cấu tạo, biến thể và trạng thái. Nút thực hiện hành động; liên kết mở đích; tab chọn vùng nội dung. Nhãn luôn đậm 700. Kiểm thường, chọn, hover, bàn phím và disabled khi có. Không xác nhận thành công trước hành động thật; mẫu thử không lưu dữ liệu hoặc thực hiện việc bên ngoài. Thư viện lưu mẫu thật và nguồn. Mẫu tổng quan chỉ giải thích quy tắc, không tạo mã tài sản mới. Vòng bàn phím phải nhìn rõ theo chính sách SHADOW47 hiện hành, không suy từ màu nhấn lịch sử.": {"role": "explanatory-body", "selectedSpans": [{"start": 204, "end": 229, "text": "Không xác nhận thành công"}, {"start": 236, "end": 250, "text": "hành động thật"}]}, "Chọn cấu trúc và ký hiệu": {"role": "role-exception", "selectedSpans": []}, "Bảng để so cùng tiêu chí; số/bước cho thứ tự; biểu đồ cho lượng/quan hệ; lời trích cho phát biểu có nguồn. Chọn một cấp lớn nhất và tổ hợp đúng định dạng; không ép mọi nội dung thành thẻ hoặc lưới giống nhau. Giữ nội dung, nguồn, đơn vị, quan hệ và vai trò hình. Thử ít/thường/dài/vượt mức; khi vượt khả năng thì dàn lại, tiếp trang hoặc từ chối có lý do, không giảm chữ/đổi font/hạ vai trò. Mẫu hiện tại không chứng minh mọi PDF đều phù hợp. Chọn việc đọc → nghĩa đã khai báo → icon Thư viện → cấp nhóm/mục/nhãn → dựng và kiểm. Không có nghĩa phù hợp thì giữ chữ hoặc đề xuất icon mới có phạm vi; không bắt buộc icon ở mọi câu. Nên/tránh: mỗi mục một dấu; việc kiểm thật dùng ô chọn theo dữ liệu và hành vi thật. Kiến thức/định nghĩa/trích dẫn không giả checklist; nhóm cùng nghĩa có thể chỉ dùng một icon đầu nhóm. Bước có thứ tự giữ số là dấu chính, tối đa một icon chức năng phụ mỗi bước. Nhãn ngắn trong hình dùng một icon dẫn nghĩa; không thêm từng câu hoặc biến thành nút giả. Điều hướng/hành động dùng icon chức năng kèm nhãn, không dùng minh họa thương hiệu thay icon nhỏ. Đoạn dài/bảng nhiều số ưu tiên chữ, dữ liệu và từ khóa; mặc định không icon từng câu/ô, có thể một ở tiêu đề nhóm. Chỉ thêm trạng thái thật khi cần, giữ nhãn và đơn vị.": {"role": "explanatory-body", "selectedSpans": [{"start": 356, "end": 390, "text": "không giảm chữ/đổi font/hạ vai trò"}, {"start": 919, "end": 937, "text": "một icon dẫn nghĩa"}]}, "Mật độ tính theo đơn vị có nghĩa: tối đa một icon dẫn nghĩa mỗi mục/nhãn cùng cấp, không gộp trạng thái/thao tác riêng thành trang trí. Một danh sách dùng cách đánh dấu nhất quán; không trộn dấu thường, emoji và nhiều bộ nét cùng cấp. Icon tiêu đề thường không lặp từng câu, trừ cặp nên/tránh. Icon 24 px, nét 2 px; icon–chữ 12 px, giữa mục 16 px. Căn icon với dòng đầu khi chữ nhiều dòng; icon + một nhãn trong hình căn giữa cả nhóm, giữ đệm. Nội dung dài nhóm lại hoặc tiếp trang, không thu nhỏ chữ/icon. Giữ ul/ol thật. Điều khiển chỉ icon có tên truy cập. Không dùng icon khi mơ hồ, chật, cạnh tranh hình/số liệu chính, phá nguyên văn hoặc chỉ lấp chỗ trống. Bảng hẹp được cuộn ngang bằng bàn phím Tab rồi phím mũi tên. Đặt điều kiện/nguồn cạnh ý; áp dụng khoảng chú thích thực 24 px sau bóng đã nêu. Che màu, bỏ icon và đọc lướt vẫn phải hiểu đủ; kiểm câu 2–3 dòng, hẹp, sáng/tối, in/PDF, dừng chuyển động; đối chiếu icon/nguồn/màu/phiên bản Thư viện. Mật độ là đề xuất KAI, không định mức mọi thương hiệu.": {"role": "explanatory-body", "selectedSpans": [{"start": 155, "end": 178, "text": "cách đánh dấu nhất quán"}, {"start": 483, "end": 505, "text": "không thu nhỏ chữ/icon"}]}, "Chuyển động phải làm rõ chức năng; dữ liệu quan trọng không biến mất khi chạy/dừng. Dùng cùng hình gốc, tĩnh là dự phòng hợp lệ. Kim la bàn và khiên KAI 3 giây; lửa 2 giây; ease-in-out, trở về trạng thái đầu. Ưu tiên dừng toàn bộ; mẫu ngoài màn hình tạm dừng, tôn trọng giảm chuyển động. Kiểm bắt đầu/giữa/kết/dừng/chạy lại/giảm chuyển động; giữ hình, khoảng thở và nội dung. Không dùng chuyển động để lấp chỗ trống. Camera 1 giây, nhanh trước chậm dần; camera và bảng bắt đầu đồng thời. Bảng vào 2,99 giây, ra 1,81 giây, mờ và trượt. Đổi lựa chọn giữa chừng tiếp tục từ vị trí hiện tại; đóng/bấm lại trả đúng khung trước. Tắt chuyển động vẫn đủ nội dung/thao tác; trang không camera giữ cuộn và tiêu điểm.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 33, "text": "Chuyển động phải làm rõ chức năng"}, {"start": 35, "end": 53, "text": "dữ liệu quan trọng"}]}, "Xanh cho hệ thống, vàng nhấn hiếm có chủ ý. Giữ thông điệp/dữ liệu/hành động làm trọng tâm, nền sạch và đầy đủ hình tham chiếu quan trọng; căn số theo cột và giữ đơn vị. Kiểm dấu Việt, bàn phím và giảm chuyển động. Không để nền giả tưởng cản đọc/nhập liệu; không dùng glow, gradient hoặc kính mờ chỉ để gợi “AI”; nhãn chức năng không thành thuật ngữ game khó hiểu. Không dùng ảnh AI làm bằng chứng kinh doanh hoặc giấu dữ liệu theo vòng chuyển động. Phá lưới/tăng chuyển động chỉ khi giúp kể chuyện và đã kiểm đọc được; danh sách tránh không cấm mọi biểu đạt sáng tạo.": {"role": "explanatory-body", "selectedSpans": [{"start": 197, "end": 213, "text": "giảm chuyển động"}, {"start": 365, "end": 382, "text": "Không dùng ảnh AI"}]}, "Quy tắc thiết kế, thông số CSS và giá trị thiết kế cùng lấy nguồn từ mô hình KAI; các bản Markdown đi cùng gói để đọc/dùng lại. Đổi quy tắc phải cập nhật nguồn và kiểm nơi dùng, không sửa riêng tài liệu sinh ra.": {"role": "explanatory-body", "selectedSpans": [{"start": 145, "end": 159, "text": "cập nhật nguồn"}, {"start": 178, "end": 210, "text": "không sửa riêng tài liệu sinh ra"}]}, "Phần nhấn cách đường bao thật kể cả cạnh nghiêng; khiên KAI dùng lưới 32, khoảng hở tối thiểu 2 đơn vị trong toàn bộ chuyển động. Kiểm ở 24/32/64 px và cỡ minh họa. Khoảng hở bên trong khác khoảng từ icon đến khung, chữ hoặc hình bên cạnh; giữ một hình gốc ở mọi nơi dùng.": {"role": "explanatory-body", "selectedSpans": [{"start": 74, "end": 93, "text": "khoảng hở tối thiểu"}, {"start": 244, "end": 256, "text": "một hình gốc"}]}, "1 · Người đọc và công việc": {"role": "role-exception", "selectedSpans": []}, "Cụ thể, bình tĩnh và đồng hành. Mỗi nội dung chọn một nhóm và một việc: công việc cá nhân, website/ứng dụng, học AI hoặc dịch vụ KAI. Nêu việc, giới hạn và bước làm được; giải nghĩa thuật ngữ lần đầu, gọi mẫu là minh họa.": {"role": "explanatory-body", "selectedSpans": [{"start": 50, "end": 70, "text": "một nhóm và một việc"}, {"start": 144, "end": 169, "text": "giới hạn và bước làm được"}]}, "2 · Đặc tính và ranh giới": {"role": "role-exception", "selectedSpans": []}, "K01 Có ích: bước làm được, không lên gân; ẩn dụ không thay thao tác/che rủi ro. K02 Rõ, không lạnh: đúng đối tượng/hành động/hậu quả; không tự đặt người thực hiện. K03 Khích lệ bằng kết quả thật, không suy hiệu ứng thành lưu/đồng bộ/xuất bản. K04 Ấm ở dẫn, thẳng ở thao tác; tối đa một ẩn dụ hành trình mỗi đoạn truyền thông, không đùa/hiệp sĩ trong lỗi, xóa, bảo mật, thanh toán.": {"role": "explanatory-body", "selectedSpans": [{"start": 168, "end": 194, "text": "Khích lệ bằng kết quả thật"}, {"start": 196, "end": 214, "text": "không suy hiệu ứng"}]}, "3 · Tình huống và kênh": {"role": "role-exception", "selectedSpans": []}, "Bình thường: việc → thông tin → bước. Lần đầu: nhu cầu → khả năng thật → ví dụ → lời mời; không tự đặt giá/khách. Bắt đầu: mục tiêu → điều kiện → thao tác → kiểm, không mặc định dễ. Thành công: kết quả xác nhận; trống: phần thiếu và cách bắt đầu thật. Lỗi: thất bại → ảnh hưởng biết được → xử lý được hỗ trợ. Chưa chắc: đã biết → chưa biết → giới hạn quyết định. Xóa: đối tượng/phạm vi → hậu quả → điều kiện → lựa chọn. Tiền/quyền: tình trạng → bảo vệ/hỗ trợ đã xác nhận. Hỗ trợ hỏi dấu hiệu cần thiết, không trách/đoán nguyên nhân. Video: chủ đề thật → giải thích → cho thấy → thử; kết câu hỏi đã hứa trước. Bài học có việc/lý do/bước hoặc lệnh/kết quả/kiểm; không ép khuôn này vào nhãn/bài ngắn. Dịch vụ/cộng đồng dùng nhu cầu/quan sát cụ thể → ví dụ → bước hoặc câu hỏi; tách thật và minh họa.": {"role": "explanatory-body", "selectedSpans": [{"start": 90, "end": 102, "text": "không tự đặt"}, {"start": 194, "end": 210, "text": "kết quả xác nhận"}]}, "4 · Ngôn ngữ và lời nói": {"role": "role-exception", "selectedSpans": []}, "Gọi bạn; chúng tôi đúng đội KAI, mình đúng người kể; không suy tuổi/giới/thân mật. Viết tự nhiên, động từ cụ thể, rõ trách nhiệm/phủ định/điều kiện; không dịch khuôn Anh/lặp hãy. Giữ tên/mã/đường dẫn/đơn vị/lời trích; viết hoa phần tự viết, kiểm dấu/ngày/số/tiền. Đọc thành tiếng, tách chỗ khó thở, không trần số từ; nhịp nghỉ ngoài lời. EN rút gọn tự nhiên, đại từ rõ; thời lượng ước tính chưa phải đã đo.": {"role": "explanatory-body", "selectedSpans": [{"start": 98, "end": 112, "text": "động từ cụ thể"}, {"start": 390, "end": 405, "text": "chưa phải đã đo"}]}, "5 · Sự thật và giới hạn": {"role": "role-exception", "selectedSpans": []}, "Giữ chủ thể/sở hữu/thời điểm/lượng/đơn vị/quyền/phủ định/điều kiện/độ chắc chắn. Không tự hứa miễn phí, tốt nhất, đảm bảo, khan hiếm, tăng gấp nhiều lần, an toàn, khôi phục, hoàn tiền, hoàn tác hoặc đã lưu/đồng bộ/xuất bản. Không khẩn cấp giả; giữ có thể/dự kiến/chỉ khi và phần chưa biết cạnh quyết định; chưa biết xử lý thì không khuyên thử lại.": {"role": "explanatory-body", "selectedSpans": [{"start": 67, "end": 79, "text": "độ chắc chắn"}, {"start": 81, "end": 93, "text": "Không tự hứa"}]}, "6 · Chữ theo chức năng": {"role": "role-exception", "selectedSpans": []}, "Tiêu đề một ý, dài thì chia/đổi bố cục. Hành động: động từ + đối tượng/hậu quả, không giảm chữ. Ô nhập có nhãn luôn hiện, hướng dẫn/lỗi tối đa hai câu. Trống/xử lý: một trạng thái + bước thật. Xác nhận: một đoạn ngắn + lựa chọn, đủ hậu quả/điều kiện. Thông báo một–hai câu, phân biệt thử/lưu/đồng bộ/xuất bản. Biểu đồ giữ nhóm/nguồn/đơn vị/giới hạn, không suy doanh thu thành lợi nhuận. Trích/mã giữ ký tự khi chép; không tạo chức năng giả.": {"role": "explanatory-body", "selectedSpans": [{"start": 327, "end": 348, "text": "nguồn/đơn vị/giới hạn"}, {"start": 416, "end": 439, "text": "không tạo chức năng giả"}]}, "7 · Ví dụ có điều kiện": {"role": "role-exception", "selectedSpans": []}, "Minh họa xóa: xuất bản sao trước khi xóa bản nháp trên thiết bị, đám mây không đổi. Tránh “Xóa sạch mọi thứ.” Lỗi xuất/lưu chưa xác nhận phải nêu đúng phần chưa biết; ví dụ không chứng minh kết quả khách hàng.": {"role": "explanatory-body", "selectedSpans": [{"start": 19, "end": 40, "text": "bản sao trước khi xóa"}, {"start": 173, "end": 208, "text": "không chứng minh kết quả khách hàng"}]}, "8 · Nguồn và phép kiểm": {"role": "role-exception", "selectedSpans": []}, "251.2 là hướng đề xuất, chưa học từ mẫu thật/chưa đánh giá người đọc, không chứng nhận bản ngữ/ISO. Kallaway/RoboNuggets chỉ tham khảo tổ chức thông tin; không mượn chuyện/thành tích/lời hứa, nguồn lịch sử chưa kiểm web lại. Khóa dữ kiện → chọn người/việc/kênh/ngôn ngữ → viết → đối chiếu → đọc riêng → kiểm bản ghép. Ngoài EN/VI cần quy ước ngôn ngữ và bố cục riêng; dịch không chứng minh bản ngữ. KAI quyết định giọng; sửa chung cần quyền/phiên bản/bằng chứng, không tự gửi/xuất bản/kích hoạt skill.": {"role": "explanatory-body", "selectedSpans": [{"start": 24, "end": 44, "text": "chưa học từ mẫu thật"}, {"start": 192, "end": 205, "text": "nguồn lịch sử"}]}, "Chọn theo chức năng, giữ đủ các bản màu của nguồn.": {"role": "explanatory-body", "selectedSpans": [{"start": 5, "end": 19, "text": "theo chức năng"}]}, "Nhãn tài liệu, trang và hướng dẫn trong nhiều đầu ra.": {"role": "explanatory-body", "selectedSpans": [{"start": 5, "end": 13, "text": "tài liệu"}]}, "Tìm kiếm nội dung và lọc việc cần đọc.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 17, "text": "Tìm kiếm nội dung"}]}, "Dấu hoàn tất có chữ xác nhận đúng trạng thái.": {"role": "explanatory-body", "selectedSpans": [{"start": 16, "end": 28, "text": "chữ xác nhận"}]}, "Thông tin bổ sung, giải thích và trợ giúp theo ngữ cảnh.": {"role": "explanatory-body", "selectedSpans": [{"start": 33, "end": 55, "text": "trợ giúp theo ngữ cảnh"}]}, "Chuyển bước, mở phần tiếp theo và chỉ hướng có nhãn.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 11, "text": "Chuyển bước"}]}, "Giữ vùng dành cho chữ và kiểm tra tương phản trên nền thực.": {"role": "explanatory-body", "selectedSpans": [{"start": 4, "end": 21, "text": "vùng dành cho chữ"}]}, "Bề mặt nhận nguồn #F5F1E5; ví dụ lấy từ điều khiển gốc ở chế độ tương ứng. Giữ cặp chữ và bóng theo nền nhận.": {"role": "explanatory-body", "selectedSpans": [{"start": 100, "end": 108, "text": "nền nhận"}]}, "Bề mặt nhận nguồn #17241B; ví dụ lấy từ điều khiển gốc ở chế độ tương ứng. Giữ cặp chữ và bóng theo nền nhận.": {"role": "explanatory-body", "selectedSpans": [{"start": 100, "end": 108, "text": "nền nhận"}]}, "Cảnh trại, hai phiến đá rời và dương xỉ; vùng kem bên trái 45% dành cho chữ tách lớp. Giữ trọn hình ở màn hình hẹp. Cảnh trại không phải logo chính thức. Bản gốc đề xuất; chưa được nhận làm nền mặc định dùng lại và chưa được duyệt phóng lớn.": {"role": "explanatory-body", "selectedSpans": [{"start": 126, "end": 152, "text": "không phải logo chính thức"}, {"start": 215, "end": 240, "text": "chưa được duyệt phóng lớn"}]}, "Cần giải thích kết quả hoặc so sánh số liệu ngay trên trang. Gợi ý: S18 · Biểu đồ, chỉ số và giới hạn": {"role": "explanatory-body", "selectedSpans": [{"start": 28, "end": 43, "text": "so sánh số liệu"}]}, "Có quá nhiều mục nhỏ; chuyển chúng sang đầu từng phần. Gợi ý: S03 · Mở phần": {"role": "explanatory-body", "selectedSpans": [{"start": 68, "end": 75, "text": "Mở phần"}]}, "Cần trình bày lập luận hoặc bảng dữ liệu. Gợi ý: S23 · Các mục nhỏ": {"role": "explanatory-body", "selectedSpans": [{"start": 28, "end": 40, "text": "bảng dữ liệu"}]}, "Còn kết luận quan trọng chưa được giải thích. Gợi ý: S18 · Biểu đồ, chỉ số và giới hạn": {"role": "explanatory-body", "selectedSpans": [{"start": 4, "end": 23, "text": "kết luận quan trọng"}]}, "Cần đối chiếu hai hình có vai trò ngang nhau. Gợi ý: S11 · Hai hình đối chiếu": {"role": "explanatory-body", "selectedSpans": [{"start": 4, "end": 22, "text": "đối chiếu hai hình"}]}, "Hình thuộc các nhóm không liên quan hoặc không có thứ tự. Gợi ý: S07 · Bảng hình bốn lựa chọn": {"role": "explanatory-body", "selectedSpans": [{"start": 41, "end": 56, "text": "không có thứ tự"}]}, "Có sáu chi tiết hoặc một hình phải được ưu tiên rõ. Gợi ý: Sáu chi tiết: S12. Một hình chính: S05; có thêm hai cận cảnh: S09": {"role": "explanatory-body", "selectedSpans": [{"start": 78, "end": 92, "text": "Một hình chính"}, {"start": 107, "end": 119, "text": "hai cận cảnh"}]}, "Hai đối tượng cần đối chiếu trực tiếp theo cùng tiêu chí. Gợi ý: S11 · Hai hình đối chiếu": {"role": "explanatory-body", "selectedSpans": [{"start": 18, "end": 37, "text": "đối chiếu trực tiếp"}]}, "Các hình không có quan hệ chính–chi tiết, hoặc hình chính là ảnh ngang. Gợi ý: Hình ngang và hai góc bổ trợ: S10. Ba hình ngang vai cùng chủ đề: S06; khác chủ đề thì tách trang": {"role": "explanatory-body", "selectedSpans": [{"start": 9, "end": 40, "text": "không có quan hệ chính–chi tiết"}, {"start": 132, "end": 143, "text": "cùng chủ đề"}]}, "Các hình cần trọng lượng và kích thước bằng nhau. Gợi ý: S06 · Dải hình cùng chủ đề": {"role": "explanatory-body", "selectedSpans": [{"start": 28, "end": 48, "text": "kích thước bằng nhau"}]}, "Không có cơ sở so sánh hoặc khác thang đo mà không ghi rõ. Gợi ý: S05 · Hình lớn và giải thích": {"role": "explanatory-body", "selectedSpans": [{"start": 28, "end": 41, "text": "khác thang đo"}]}, "Một hình cần chú thích dài hoặc phải là điểm nhìn chính. Gợi ý: Tách thành nhiều trang nếu từng chi tiết cần giải thích dài. Nếu có ảnh chính: dùng S05; chỉ dùng S09 khi ảnh chính dọc đi cùng hai chi tiết của cùng đối tượng, hoặc S10 khi ảnh chính ngang đi cùng hai hình hỗ trợ liên quan.": {"role": "explanatory-body", "selectedSpans": [{"start": 40, "end": 55, "text": "điểm nhìn chính"}, {"start": 109, "end": 123, "text": "giải thích dài"}]}, "Ảnh phủ toàn nền; chữ đặt trên mặt phẳng KAI có nền kín.": {"role": "explanatory-body", "selectedSpans": [{"start": 48, "end": 55, "text": "nền kín"}]}, "Ảnh làm chữ khó đọc hoặc cần nhiều dữ liệu nhỏ. Gợi ý: S14 · Dải ảnh dọc và thông điệp": {"role": "explanatory-body", "selectedSpans": [{"start": 29, "end": 46, "text": "nhiều dữ liệu nhỏ"}]}, "Ảnh là bằng chứng chính cần xem đầy đủ chiều ngang. Gợi ý: S05 · Hình lớn và giải thích": {"role": "explanatory-body", "selectedSpans": [{"start": 7, "end": 23, "text": "bằng chứng chính"}]}, "Không có tiêu chí chung hoặc chỉ có một con số nổi bật. Gợi ý: S18 · Biểu đồ, chỉ số và giới hạn": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 23, "text": "Không có tiêu chí chung"}]}, "Hai bảng thực ra là một bảng bị chia tùy tiện. Gợi ý: S15 · Bảng đối chiếu": {"role": "explanatory-body", "selectedSpans": [{"start": 32, "end": 45, "text": "chia tùy tiện"}]}, "Công việc có thứ tự bắt buộc hoặc quan hệ phụ thuộc. Gợi ý: S19 · Kế hoạch bốn điểm kiểm": {"role": "explanatory-body", "selectedSpans": [{"start": 34, "end": 51, "text": "quan hệ phụ thuộc"}]}, "Chưa có số liệu hoặc đang ghép các chỉ số khác mẫu số. Gợi ý: Thu thập và kiểm dữ liệu trước. Khi cần đối chiếu giá trị cụ thể thay vì xu hướng, dùng S15; bảng cũng phải có dữ liệu hợp lệ": {"role": "explanatory-body", "selectedSpans": [{"start": 42, "end": 53, "text": "khác mẫu số"}, {"start": 74, "end": 92, "text": "kiểm dữ liệu trước"}]}, "Công việc diễn ra song song và không có chuỗi bắt buộc. Gợi ý: S17 · Ba nhóm nội dung": {"role": "explanatory-body", "selectedSpans": [{"start": 31, "end": 54, "text": "không có chuỗi bắt buộc"}]}, "Chỉ đang gom nhiều biểu đồ không cùng một câu hỏi. Gợi ý: S18 · Một biểu đồ và diễn giải": {"role": "explanatory-body", "selectedSpans": [{"start": 27, "end": 49, "text": "không cùng một câu hỏi"}]}, "Tỷ trọng không cộng được hoặc nguồn/phạm vi không tương thích. Gợi ý: S18 · Biểu đồ, chỉ số và giới hạn": {"role": "explanatory-body", "selectedSpans": [{"start": 30, "end": 61, "text": "nguồn/phạm vi không tương thích"}]}, "Hai hàng cần đối chiếu trực tiếp nhưng khác cột hoặc đơn vị. Gợi ý: S15 · Bảng đối chiếu": {"role": "explanatory-body", "selectedSpans": [{"start": 39, "end": 59, "text": "khác cột hoặc đơn vị"}]}, "Mỗi mục cần nhiều bằng chứng hoặc dữ liệu chi tiết riêng. Gợi ý: S15 · Bảng đối chiếu": {"role": "explanatory-body", "selectedSpans": [{"start": 34, "end": 50, "text": "dữ liệu chi tiết"}]}, "Các cột không phải các bước hoặc thứ tự không có ý nghĩa. Gợi ý: S15 · Bảng đối chiếu tiêu chí": {"role": "explanatory-body", "selectedSpans": [{"start": 33, "end": 56, "text": "thứ tự không có ý nghĩa"}]}, "Các phần không cùng tổng hoặc số minh họa bị nhận là số kinh doanh thật. Gợi ý: S18 · Biểu đồ, chỉ số và giới hạn": {"role": "explanatory-body", "selectedSpans": [{"start": 9, "end": 24, "text": "không cùng tổng"}]}, "Tiêu chí không đồng nhất hoặc dữ liệu thiếu bị nhận là điểm yếu. Gợi ý: S15 · Bảng đối chiếu": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 24, "text": "Tiêu chí không đồng nhất"}]}, "Không có cơ sở xếp hạng, khác kỳ hoặc bỏ qua trường hợp đồng hạng. Gợi ý: S15 · Bảng đối chiếu": {"role": "explanatory-body", "selectedSpans": [{"start": 56, "end": 65, "text": "đồng hạng"}]}, "Chọn đúng vai trò trước khi chọn màu. Ví dụ lấy từ các điều khiển KAI hiện có.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 17, "text": "Chọn đúng vai trò"}]}, "Không đặt nhiều hành động chính cạnh nhau; không dùng để đánh dấu trang hiện tại.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 31, "text": "Không đặt nhiều hành động chính"}]}, "Lựa chọn hỗ trợ bên cạnh hành động chính, như xem chi tiết hoặc quay lại.": {"role": "explanatory-body", "selectedSpans": [{"start": 25, "end": 40, "text": "hành động chính"}]}, "Không dùng khi cần nổi bật hơn việc chính.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 10, "text": "Không dùng"}]}, "Thao tác ưu tiên riêng của ngữ cảnh, như tái sử dụng tài sản trong Thư viện.": {"role": "explanatory-body", "selectedSpans": [{"start": 9, "end": 22, "text": "ưu tiên riêng"}]}, "Không tô vàng mọi nút; không dùng vàng để ngụ ý hoàn thành.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 13, "text": "Không tô vàng"}]}, "Trang đang ở hoặc lựa chọn quan trọng cần giữ dấu nhận biết. Nền xanh, chữ sáng, gạch vàng dưới.": {"role": "explanatory-body", "selectedSpans": [{"start": 46, "end": 59, "text": "dấu nhận biết"}]}, "Không đánh dấu nhiều trang cùng đang ở. Với hành động, chỉ dùng khi có lý do ưu tiên rõ.": {"role": "explanatory-body", "selectedSpans": [{"start": 77, "end": 87, "text": "ưu tiên rõ"}]}, "Mở một đích hỗ trợ trong đoạn văn, khi không cần khung nút.": {"role": "explanatory-body", "selectedSpans": [{"start": 39, "end": 58, "text": "không cần khung nút"}]}, "Không dùng liên kết để chạy thao tác; không bỏ gạch dưới làm mất dấu nhận biết.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 19, "text": "Không dùng liên kết"}]}, "Thao tác gọn khi biểu tượng đã có nhãn truy cập rõ; nguồn dùng nút “Đặt lại mẫu”.": {"role": "explanatory-body", "selectedSpans": [{"start": 34, "end": 47, "text": "nhãn truy cập"}]}, "Không để người đọc đoán công việc của nút; giữ tên truy cập và dấu bàn phím.": {"role": "explanatory-body", "selectedSpans": [{"start": 43, "end": 59, "text": "giữ tên truy cập"}]}, "Phân biệt vai trò lâu dài và phản hồi tạm thời. Giữ điều kiện và giới hạn của từng trạng thái.": {"role": "explanatory-body", "selectedSpans": [{"start": 29, "end": 46, "text": "phản hồi tạm thời"}]}, "Hành động chính xanh, phụ nền giấy, cần chú ý vàng. Không đổi vai trò bằng màu khi tương tác.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 15, "text": "Hành động chính"}]}, "Chỉ khi thiết bị có chuột và nút khả dụng. Không dùng viền nổi cách xa khung; không lấy hover thay trạng thái đang chọn.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 25, "text": "Chỉ khi thiết bị có chuột"}, {"start": 78, "end": 93, "text": "không lấy hover"}]}, "Phản hồi tạm thời khi giữ chuột, Space hoặc Enter theo hành vi thật. Thả ra trở về; không đồng nghĩa hoàn thành.": {"role": "explanatory-body", "selectedSpans": [{"start": 84, "end": 111, "text": "không đồng nghĩa hoàn thành"}]}, "Luôn nhìn thấy mục có tiêu điểm; không bỏ dấu bàn phím khi bỏ viền hover. Dấu không làm đổi kích thước khung.": {"role": "explanatory-body", "selectedSpans": [{"start": 22, "end": 31, "text": "tiêu điểm"}]}, "Trang: aria-current; nút bật/tắt: aria-pressed; tab: aria-selected. Nút chạy một lần và liên kết trong câu không có trạng thái chọn.": {"role": "explanatory-body", "selectedSpans": [{"start": 107, "end": 131, "text": "không có trạng thái chọn"}]}, "Nút dùng disabled. Không giả khóa chỉ bằng màu hoặc để nút vẫn thực hiện thao tác; liên kết cần chặn cả chuột và bàn phím nếu thật sự khóa.": {"role": "explanatory-body", "selectedSpans": [{"start": 19, "end": 33, "text": "Không giả khóa"}, {"start": 83, "end": 91, "text": "liên kết"}]}, "Chỉ với thao tác có chờ. Không gán cho liên kết thường hoặc cho hiệu ứng chạy mãi. Thông báo tiến độ ở cạnh nút.": {"role": "explanatory-body", "selectedSpans": [{"start": 93, "end": 111, "text": "tiến độ ở cạnh nút"}]}, "Chỉ báo kết quả có thật. Không dùng màu xanh/vàng hoặc trạng thái chọn để tự khẳng định đã thành công.": {"role": "explanatory-body", "selectedSpans": [{"start": 8, "end": 23, "text": "kết quả có thật"}]}, "Dữ liệu minh họa · áp dụng cả 37 mẫu số liệu": {"role": "role-exception", "selectedSpans": []}, "Dữ liệu minh họa có giới hạn; kiểm lại nội dung mới và từng đầu ra. Không tự đăng ký hay công bố.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 28, "text": "Dữ liệu minh họa có giới hạn"}]}, "Đơn vị và phạm vi đã nêu trong nguồn": {"role": "role-exception", "selectedSpans": []}, "Giữ nguyên đơn vị và phạm vi của từng giá trị nguồn.": {"role": "explanatory-body", "selectedSpans": [{"start": 11, "end": 28, "text": "đơn vị và phạm vi"}]}, "Mẫu chưa xác định đơn vị đo": {"role": "role-exception", "selectedSpans": []}, "Cột theo kỳ, Đường xu hướng, Vùng theo thời gian, Phân tán hai biến, Phân bố theo khoảng, Hộp và khoảng biến thiên, Đóng góp tăng và giảm, Ma trận có giá trị: giá trị minh họa; nguồn chưa xác định đơn vị đo cụ thể.": {"role": "explanatory-body", "selectedSpans": [{"start": 183, "end": 206, "text": "chưa xác định đơn vị đo"}]}, "Cách đọc · áp dụng cả ba bản đồ": {"role": "role-exception", "selectedSpans": []}, "Đọc hình dạng, vị trí địa lý cùng nguồn và giới hạn dữ liệu. Chọn Hoa Kỳ, Việt Nam hoặc địa cầu xoay trong chi tiết hoặc từ các liên kết cũ.": {"role": "explanatory-body", "selectedSpans": [{"start": 34, "end": 59, "text": "nguồn và giới hạn dữ liệu"}]}, "Giới hạn · áp dụng cả ba bản đồ": {"role": "role-exception", "selectedSpans": []}, "Không coi màu hình dạng là số liệu, ô phụ là cùng tỷ lệ hay địa cầu là công cụ phân loại chủ quyền. Không dùng để đo đạc, phân định chủ quyền hoặc suy ra số liệu thống kê chưa có trong nguồn.": {"role": "explanatory-body", "selectedSpans": [{"start": 100, "end": 120, "text": "Không dùng để đo đạc"}]}, "Bản PDF · áp dụng cả ba bản đồ": {"role": "role-exception", "selectedSpans": []}, "PDF chỉ giữ ảnh tĩnh toàn khung. Tìm kiếm, chọn vùng, xoay và các thao tác tương tác ở HTML gốc; phương án bản phẳng của địa cầu cũng ở đó.": {"role": "explanatory-body", "selectedSpans": [{"start": 12, "end": 31, "text": "ảnh tĩnh toàn khung"}]}, "Dùng khi — So sánh một lượng giữa các nhóm; chọn hướng, nhóm con, giá trị có dấu hoặc mục tiêu trong phần chi tiết.": {"role": "explanatory-body", "selectedSpans": [{"start": 19, "end": 42, "text": "một lượng giữa các nhóm"}]}, "Tránh — Không dùng thay phân bố theo khoảng, tổng cộng dồn, thời lượng hay hai lần đo theo cặp.": {"role": "explanatory-body", "selectedSpans": [{"start": 8, "end": 23, "text": "Không dùng thay"}]}, "Thanh ngang — Giữ mốc 0, trục 0–12 và cùng đơn vị để so độ dài. Dữ liệu: Tạo: 8 · Làm: 6 · Xong: 10.": {"role": "explanatory-body", "selectedSpans": [{"start": 38, "end": 49, "text": "cùng đơn vị"}]}, "Cột theo kỳ — Giữ trục 0–10, thứ tự các kỳ và cùng đơn vị. Đổi hướng không tạo họ mới. Dữ liệu: T1: 4 · T2: 7 · T3: 9.": {"role": "explanatory-body", "selectedSpans": [{"start": 29, "end": 35, "text": "thứ tự"}, {"start": 46, "end": 57, "text": "cùng đơn vị"}]}, "Cột theo nhóm — Giữ riêng nhóm và chuỗi; hai cột cạnh nhau không mặc nhiên cộng thành tổng. Dữ liệu: A · Đọc/Dựng: 4 / 7 mục · B · Đọc/Dựng: 6 / 5 mục · C · Đọc/Dựng: 3 / 8 mục.": {"role": "explanatory-body", "selectedSpans": [{"start": 59, "end": 90, "text": "không mặc nhiên cộng thành tổng"}]}, "Thanh hai phía — Giữ dấu và mốc tham chiếu chung; các thanh độc lập, không nối thành tổng cộng dồn. Dữ liệu: A: −4 mục · B: +6 mục · C: −2 mục · D: +3 mục.": {"role": "explanatory-body", "selectedSpans": [{"start": 28, "end": 48, "text": "mốc tham chiếu chung"}, {"start": 60, "end": 67, "text": "độc lập"}]}, "Chấm có trục so sánh — Giữ mốc 0 và trục 0–10; nét và chấm không thêm lần đo thứ hai. Dữ liệu: A: 4 mục · B: 7 mục · C: 9 mục.": {"role": "explanatory-body", "selectedSpans": [{"start": 59, "end": 84, "text": "không thêm lần đo thứ hai"}]}, "Thực tế và mục tiêu — Mục tiêu là mốc tham chiếu; không cộng vào thực tế. Mẫu chưa có dải đánh giá định tính. Dữ liệu: Thực tế: 7 mục · Mục tiêu: 9 mục · Thang đo: 0–12 mục.": {"role": "explanatory-body", "selectedSpans": [{"start": 50, "end": 72, "text": "không cộng vào thực tế"}]}, "Dùng khi — Theo dõi một hoặc nhiều lượng cùng đơn vị qua các mốc có thứ tự; chọn phần tô, nhiều ô nhỏ hoặc ngưỡng khi cần.": {"role": "explanatory-body", "selectedSpans": [{"start": 41, "end": 52, "text": "cùng đơn vị"}, {"start": 61, "end": 74, "text": "mốc có thứ tự"}]}, "Tránh — Không nối các nhóm không có thứ tự, coi các tiêu chí độc lập là thời gian hoặc tự thêm trục đơn vị thứ hai.": {"role": "explanatory-body", "selectedSpans": [{"start": 8, "end": 26, "text": "Không nối các nhóm"}]}, "Đường xu hướng — Nối các mốc có thứ tự có ý nghĩa; trục 0–10. Không nối nhóm rời hay tiêu chí độc lập thành chuỗi thời gian. Dữ liệu: T1: 2 · T2: 5 · T3: 4 · T4: 9.": {"role": "explanatory-body", "selectedSpans": [{"start": 25, "end": 38, "text": "mốc có thứ tự"}, {"start": 62, "end": 80, "text": "Không nối nhóm rời"}]}, "Vùng theo thời gian — Phần tô giữ đường rõ, chỉ đổi cách thể hiện cùng chuỗi đường; không thêm dữ liệu tích lũy, xếp chồng hay khoảng biến thiên. Dữ liệu: T1: 2 · T2: 5 · T3: 4 · T4: 9.": {"role": "explanatory-body", "selectedSpans": [{"start": 84, "end": 111, "text": "không thêm dữ liệu tích lũy"}]}, "Đường nhỏ theo nhóm — Giữ tên nhóm, thứ tự kỳ và thang 0–10 chung khi so độ lớn. Dữ liệu: A · Kỳ 1–4: 2 / 4 / 3 / 6 mục · B · Kỳ 1–4: 5 / 3 / 4 / 7 mục.": {"role": "explanatory-body", "selectedSpans": [{"start": 26, "end": 34, "text": "tên nhóm"}, {"start": 49, "end": 65, "text": "thang 0–10 chung"}]}, "Chuỗi có ngưỡng theo dõi — Giữ ý nghĩa và đơn vị của ngưỡng tham chiếu; không phải giới hạn kiểm soát suy ra từ thống kê. Dữ liệu: Kỳ 1–4: 2 / 5 / 4 / 8 mục · Ngưỡng: 6 mục.": {"role": "explanatory-body", "selectedSpans": [{"start": 72, "end": 101, "text": "không phải giới hạn kiểm soát"}]}, "Cột và đường cùng trục — Giữ tên chuỗi, chú giải và thang chung; không có trục hay đơn vị đo thứ hai. Dữ liệu: Kỳ 1 · Nhận/Xong: 4 / 3 mục · Kỳ 2 · Nhận/Xong: 7 / 5 mục · Kỳ 3 · Nhận/Xong: 9 / 8 mục.": {"role": "explanatory-body", "selectedSpans": [{"start": 65, "end": 100, "text": "không có trục hay đơn vị đo thứ hai"}]}, "Dùng khi — Đọc tỷ phần của một tổng đã biết; dùng vòng tiến độ khi có số hoàn tất và mục tiêu.": {"role": "explanatory-body", "selectedSpans": [{"start": 27, "end": 43, "text": "một tổng đã biết"}]}, "Tránh — Không dùng cho phần âm, nhiều tổng không liên quan hoặc tiến độ chưa có mẫu số.": {"role": "explanatory-body", "selectedSpans": [{"start": 8, "end": 30, "text": "Không dùng cho phần âm"}]}, "Vòng cơ cấu — Xong 60, còn 40; tổng 100. Các phần không âm và cùng thuộc một tổng. Không so độ lớn giữa các vòng có tổng khác nhau mà không ghi rõ tổng. Dữ liệu: Xong: 60% · Còn: 40%.": {"role": "explanatory-body", "selectedSpans": [{"start": 41, "end": 58, "text": "Các phần không âm"}, {"start": 140, "end": 151, "text": "ghi rõ tổng"}]}, "Tròn cơ cấu — Hai phần 60 và 40, tổng 100; nhãn ghi trực tiếp tỷ lệ. Giữ cùng tổng và các phần không âm. Có hay không có lỗ tròn chỉ đổi cách thể hiện, không đổi câu hỏi dữ liệu. Dữ liệu: Nhóm A: 60% · Nhóm B: 40%.": {"role": "explanatory-body", "selectedSpans": [{"start": 86, "end": 103, "text": "các phần không âm"}]}, "Vòng tiến độ — Hoàn tất 6 trên 10 mục; tỷ lệ 60%. Giữ số hoàn tất, mẫu số mục tiêu và phép tính tỷ lệ; không biến các nhóm cơ cấu thông thường thành tiến độ. Dữ liệu: Hoàn tất: 6 mục · Tổng: 10 mục · Tỷ lệ: 60%.": {"role": "explanatory-body", "selectedSpans": [{"start": 67, "end": 73, "text": "mẫu số"}, {"start": 86, "end": 101, "text": "phép tính tỷ lệ"}]}, "Dùng khi — So sánh các phần cộng thành tổng; chọn rõ số tuyệt đối hoặc tỷ lệ100%.": {"role": "explanatory-body", "selectedSpans": [{"start": 19, "end": 43, "text": "các phần cộng thành tổng"}]}, "Tránh — Không đổi chế độ mà bỏ tổng, mẫu số hay đơn vị; không xếp chồng các đại lượng không cộng được.": {"role": "explanatory-body", "selectedSpans": [{"start": 56, "end": 71, "text": "không xếp chồng"}]}, "Thanh cơ cấu 100% — Hai nhóm 60% và 40%; không dùng cho số tuyệt đối. Giữ mẫu số và chuẩn hóa 100%; không dùng trục số tuyệt đối hoặc đổi số lượng sang tỷ lệ mà không nói rõ. Dữ liệu: Nhóm A: 60% · Nhóm B: 40%.": {"role": "explanatory-body", "selectedSpans": [{"start": 74, "end": 80, "text": "mẫu số"}]}, "Thanh chồng số tuyệt đối — A có 4+6=10; B có 3+5=8 mục. Các phần phải cộng được và cùng đơn vị; giữ hai tổng khác nhau là 10 và 8, không tự chuẩn hóa để làm chúng bằng nhau. Dữ liệu: A · Đọc: 4 mục · A · Dựng: 6 mục · B · Đọc: 3 mục · B · Dựng: 5 mục.": {"role": "explanatory-body", "selectedSpans": [{"start": 83, "end": 94, "text": "cùng đơn vị"}, {"start": 131, "end": 149, "text": "không tự chuẩn hóa"}]}, "Dùng khi — Xem quan hệ giữa hai lượng đo trên từng quan sát.": {"role": "explanatory-body", "selectedSpans": [{"start": 28, "end": 40, "text": "hai lượng đo"}]}, "Tránh — Không suy nhân quả, nối theo thời gian khi chưa có thứ tự hoặc coi tọa độ là địa lý.": {"role": "explanatory-body", "selectedSpans": [{"start": 8, "end": 26, "text": "Không suy nhân quả"}]}, "Phân tán hai biến — Năm cặp x/y; hai trục 0–10. Không suy quan hệ nhân quả. Các điểm không mặc nhiên có thứ tự nối; không suy nhân quả hay coi tọa độ hai lượng đo là tọa độ địa lý. Dữ liệu: x = 1: y = 2 · x = 3: y = 4 · x = 4: y = 3 · x = 6: y = 7 · x = 8: y = 6.": {"role": "explanatory-body", "selectedSpans": [{"start": 48, "end": 74, "text": "Không suy quan hệ nhân quả"}, {"start": 85, "end": 114, "text": "không mặc nhiên có thứ tự nối"}]}, "Dùng khi — Xem phân bố quan sát số theo các khoảng có ranh giới rõ.": {"role": "explanatory-body", "selectedSpans": [{"start": 54, "end": 66, "text": "ranh giới rõ"}]}, "Tránh — Không coi nhãn nhóm là khoảng số hoặc dùng tần số làm giá trị đo ban đầu.": {"role": "explanatory-body", "selectedSpans": [{"start": 8, "end": 27, "text": "Không coi nhãn nhóm"}]}, "Phân bố theo khoảng — Ba khoảng bằng nhau: 0–10 có 2, 10–20 có 5, 20–30 có 3 quan sát. Giữ ranh giới và quy tắc tính hai đầu mỗi khoảng. Tần số là số quan sát, không phải giá trị đo ban đầu; khoảng rộng không đều cần quy tắc mật độ riêng. Dữ liệu: 0 ≤ x < 10: 2 quan sát · 10 ≤ x < 20: 5 quan sát · 20 ≤ x ≤ 30: 3 quan sát.": {"role": "explanatory-body", "selectedSpans": [{"start": 87, "end": 100, "text": "Giữ ranh giới"}, {"start": 137, "end": 158, "text": "Tần số là số quan sát"}]}, "Dùng khi — Đọc trung vị, tứ phân vị và khoảng nhỏ nhất/lớn nhất của mẫu.": {"role": "explanatory-body", "selectedSpans": [{"start": 25, "end": 35, "text": "tứ phân vị"}]}, "Tránh — Không thay tứ phân vị bằng mở/đóng hoặc tự đổi râu thành quy tắc ngoại lệ.": {"role": "explanatory-body", "selectedSpans": [{"start": 8, "end": 29, "text": "Không thay tứ phân vị"}]}, "Hộp và khoảng biến thiên — Tóm tắt mẫu: nhỏ nhất 2, tứ phân vị 4 và 8, trung vị 6, lớn nhất 10. Râu hiện là nhỏ nhất và lớn nhất, không tự đổi thành giới hạn ngoại lệ. Không thay tứ phân vị bằng mở/đóng hoặc tự thêm điểm ngoại lệ. Dữ liệu: Nhỏ nhất: 2 · Tứ phân vị dưới: 4 · Trung vị: 6 · Tứ phân vị trên: 8 · Lớn nhất: 10.": {"role": "explanatory-body", "selectedSpans": [{"start": 130, "end": 166, "text": "không tự đổi thành giới hạn ngoại lệ"}]}, "Dùng khi — Giải thích tổng cuối bằng tổng đầu và các khoản tăng/giảm theo thứ tự.": {"role": "explanatory-body", "selectedSpans": [{"start": 59, "end": 80, "text": "tăng/giảm theo thứ tự"}]}, "Tránh — Không dùng các thanh có dấu độc lập mà không tính mốc cộng dồn.": {"role": "explanatory-body", "selectedSpans": [{"start": 47, "end": 70, "text": "không tính mốc cộng dồn"}]}, "Đóng góp tăng và giảm — Bắt đầu 8, thêm 4, bớt 2, kết thúc 10. Giữ dấu tăng/giảm. Thanh đóng góp nối mốc cộng dồn. Tổng cuối bằng tổng đầu cộng các khoản tăng/giảm; thanh có dấu độc lập không thay được phép tính này. Dữ liệu: Bắt đầu: 8 · Thêm: +4 → 12 · Bớt: −2 → 10 · Kết thúc: 10.": {"role": "explanatory-body", "selectedSpans": [{"start": 101, "end": 113, "text": "mốc cộng dồn"}, {"start": 186, "end": 211, "text": "không thay được phép tính"}]}, "Dùng khi — Đối chiếu giá trị trong lưới; chọn tọa độ nhóm/kỳ, ngày/tuần hoặc nhóm bắt đầu/tuổi nhóm.": {"role": "explanatory-body", "selectedSpans": [{"start": 77, "end": 89, "text": "nhóm bắt đầu"}]}, "Tránh — Không bỏ kiểu tọa độ, mẫu số, ô chưa quan sát hoặc dùng màu chú ý như thang đo liên tục.": {"role": "explanatory-body", "selectedSpans": [{"start": 8, "end": 28, "text": "Không bỏ kiểu tọa độ"}]}, "Ma trận có giá trị — Giữ số trong mỗi ô; độ đậm biểu thị giá trị theo thang chú giải. Tách ô thiếu dữ liệu khỏi ô 0; không dùng màu chú ý để giả thành mức đo. Dữ liệu: Nhóm A · T1: 2 · Nhóm A · T2: 5 · Nhóm A · T3: 8 · Nhóm B · T1: 6 · Nhóm B · T2: 3 · Nhóm B · T3: 7.": {"role": "explanatory-body", "selectedSpans": [{"start": 41, "end": 47, "text": "độ đậm"}, {"start": 86, "end": 106, "text": "Tách ô thiếu dữ liệu"}]}, "Lịch có giá trị — Giữ 21 ngày minh họa, giá trị 0–4, cột đầu Thứ hai và đúng mã ngày; độ đậm theo chú giải. Đây chưa phải lịch có ngày tháng thật. Dữ liệu: Ngày1: 0 mục · Ngày2: 3 mục · Ngày3: 1 mục · Ngày4: 4 mục · Ngày5: 2 mục · Ngày6: 0 mục · Ngày7: 3 mục · Ngày8: 1 mục · Ngày9: 4 mục · Ngày10: 2 mục · Ngày11: 0 mục · Ngày12: 3 mục · Ngày13: 1 mục · Ngày14: 4 mục · Ngày15: 2 mục · Ngày16: 0 mục · Ngày17: 3 mục · Ngày18: 1 mục · Ngày19: 4 mục · Ngày20: 2 mục · Ngày21: 0 mục.": {"role": "explanatory-body", "selectedSpans": [{"start": 72, "end": 84, "text": "đúng mã ngày"}, {"start": 112, "end": 145, "text": "chưa phải lịch có ngày tháng thật"}]}, "Giữ lại theo nhóm bắt đầu — Cột là tuổi nhóm từ lúc bắt đầu, không phải kỳ lịch chung. Giữ mẫu số và thời gian đủ điều kiện quan sát; ô chưa đến kỳ không đổi thành 0. Dữ liệu: Nhóm A · Kỳ 0/1/2: 100 / 70 / 50% · Nhóm B · Kỳ 0/1: 100 / 80% · Nhóm C · Kỳ 0: 100%.": {"role": "explanatory-body", "selectedSpans": [{"start": 13, "end": 25, "text": "nhóm bắt đầu"}, {"start": 114, "end": 123, "text": "điều kiện"}]}, "Dùng khi — Theo dõi số còn lại của cùng một nhóm qua các bước nối tiếp.": {"role": "explanatory-body", "selectedSpans": [{"start": 35, "end": 48, "text": "cùng một nhóm"}]}, "Tránh — Không gọi số lượng các nhóm độc lập là tỷ lệ chuyển bước.": {"role": "explanatory-body", "selectedSpans": [{"start": 8, "end": 26, "text": "Không gọi số lượng"}]}, "Phễu theo bước — Cùng một nhóm:20→12→6 mục qua ba bước. Giữ cùng nhóm quan sát, các bước lồng tiếp nhau, thứ tự và khoảng thời gian theo dõi. Nhóm độc lập không chứng minh chuyển bước. Dữ liệu: Tiếp nhận: 20 mục · Xử lý: 12 mục · Hoàn tất: 6 mục.": {"role": "explanatory-body", "selectedSpans": [{"start": 17, "end": 30, "text": "Cùng một nhóm"}, {"start": 142, "end": 154, "text": "Nhóm độc lập"}]}, "Dùng khi — Đọc các phần của một tổng theo diện tích ô chữ nhật.": {"role": "explanatory-body", "selectedSpans": [{"start": 42, "end": 62, "text": "diện tích ô chữ nhật"}]}, "Tránh — Không đọc giá trị bằng riêng chiều rộng hoặc tuyên bố mẫu hiện có nhiều tầng phân cấp.": {"role": "explanatory-body", "selectedSpans": [{"start": 8, "end": 25, "text": "Không đọc giá trị"}]}, "Ô diện tích cơ cấu — Ba phần 50,30,20 mục; tổng 100. Mẫu chỉ có một tầng. Đọc giá trị bằng diện tích, không riêng chiều rộng; không coi ô là hình địa lý hay tuyên bố có nhiều tầng lồng nhau. Dữ liệu: A: 50 mục · B: 30 mục · C: 20 mục.": {"role": "explanatory-body", "selectedSpans": [{"start": 2, "end": 11, "text": "diện tích"}]}, "Dùng khi — Đọc thời điểm bắt đầu, kết thúc, chồng lấn hoặc trạng thái trên một trục thời gian.": {"role": "explanatory-body", "selectedSpans": [{"start": 79, "end": 93, "text": "trục thời gian"}]}, "Tránh — Không coi độ dài là lượng trạng thái hay tỷ lệ; phải giữ quy ước tính ngày đầu/cuối.": {"role": "explanatory-body", "selectedSpans": [{"start": 8, "end": 24, "text": "Không coi độ dài"}]}, "Lịch công việc — A ngày 1–3; B ngày 3–6; C ngày 5–8. Mẫu tính cả ngày đầu và cuối; không lấy ngày cuối trừ ngày đầu để đổi thời lượng khi chưa nêu quy tắc chuyển ranh giới. Dữ liệu: A: Ngày 1–3 · B: Ngày 3–6 · C: Ngày 5–8.": {"role": "explanatory-body", "selectedSpans": [{"start": 57, "end": 81, "text": "tính cả ngày đầu và cuối"}, {"start": 83, "end": 115, "text": "không lấy ngày cuối trừ ngày đầu"}]}, "Dải trạng thái theo thời gian — Ngày 1–2 Chờ;3–5 Làm;6–8 Kiểm. Độ dài đoạn là thời gian; trạng thái là nhãn định tính, không phải tỷ lệ 100% hay giá trị số. Dữ liệu: Chờ: Ngày 1–2 · Làm: Ngày 3–5 · Kiểm: Ngày 6–8.": {"role": "explanatory-body", "selectedSpans": [{"start": 63, "end": 87, "text": "Độ dài đoạn là thời gian"}, {"start": 103, "end": 117, "text": "nhãn định tính"}]}, "Dùng khi — So sánh hai lần đo cùng đơn vị cho từng đối tượng; chọn bố cục dốc hoặc hai đầu theo hàng.": {"role": "explanatory-body", "selectedSpans": [{"start": 30, "end": 41, "text": "cùng đơn vị"}]}, "Tránh — Không ghép khác đối tượng hoặc ngụ ý đã đo đường đi liên tục giữa hai đầu.": {"role": "explanatory-body", "selectedSpans": [{"start": 8, "end": 33, "text": "Không ghép khác đối tượng"}]}, "Độ dốc giữa hai kỳ — A 4→7; B 8→6; C 2→5 mục. Ghép đúng đối tượng qua hai lần đo; hai đầu không chứng minh đã quan sát đường đi liên tục giữa chúng. Dữ liệu: A: 4→7 mục · B: 8→6 mục · C: 2→5 mục.": {"role": "explanatory-body", "selectedSpans": [{"start": 51, "end": 65, "text": "đúng đối tượng"}, {"start": 70, "end": 80, "text": "hai lần đo"}]}, "Hai đầu theo nhóm — A 3→7; B 5→8; C 2→6 mục. Giữ cả hai giá trị, nhãn hai đầu, cùng đơn vị và đúng cặp đối tượng. Chấm có chân chỉ mang một giá trị không thay thế được mẫu này. Dữ liệu: A: 3→7 mục · B: 5→8 mục · C: 2→6 mục.": {"role": "explanatory-body", "selectedSpans": [{"start": 79, "end": 90, "text": "cùng đơn vị"}]}, "Dùng khi — Đọc các quan hệ cần hoàn thành trước hoặc đầu vào phụ thuộc.": {"role": "explanatory-body", "selectedSpans": [{"start": 31, "end": 47, "text": "hoàn thành trước"}]}, "Tránh — Không suy lượng luồng hay điều kiện lựa chọn từ cạnh phụ thuộc.": {"role": "explanatory-body", "selectedSpans": [{"start": 8, "end": 29, "text": "Không suy lượng luồng"}]}, "Quan hệ phụ thuộc — A→B; A→C; B→D; C→D. Cạnh là phụ thuộc, không phải luồng có lượng hay nhánh điều kiện. Mẫu hỗ trợ một nút đầu, hai nút giữa, một nút cuối; tên nút tối đa bốn ký tự. Cấu trúc khác báo chưa hỗ trợ. Dữ liệu: Cạnh: A→B · Cạnh: A→C · Cạnh: B→D · Cạnh: C→D.": {"role": "explanatory-body", "selectedSpans": [{"start": 40, "end": 57, "text": "Cạnh là phụ thuộc"}]}, "Dùng khi — Đọc lượng đi từ nguồn đến đích theo độ rộng luồng.": {"role": "explanatory-body", "selectedSpans": [{"start": 47, "end": 60, "text": "độ rộng luồng"}]}, "Tránh — Không thay lượng bằng mũi tên bằng nhau hoặc bỏ quy tắc bảo toàn/thất thoát.": {"role": "explanatory-body", "selectedSpans": [{"start": 8, "end": 24, "text": "Không thay lượng"}]}, "Luồng có lượng — A 10 mục chia thành B 6 và C 4. Giữ lượng trên từng luồng và quy tắc bảo toàn/thất thoát. Mũi tên rộng bằng nhau không thay được độ rộng theo lượng. Dữ liệu: A→B: 6 mục · A→C: 4 mục · Tổng vào/ra: 10 / 10 mục.": {"role": "explanatory-body", "selectedSpans": [{"start": 78, "end": 94, "text": "quy tắc bảo toàn"}]}, "Dùng khi — Đối chiếu một đối tượng trên nhiều tiêu chí độc lập.": {"role": "explanatory-body", "selectedSpans": [{"start": 46, "end": 62, "text": "tiêu chí độc lập"}]}, "Tránh — Không coi trục tiêu chí là các kỳ thời gian hoặc quên đơn vị/thang từng trục.": {"role": "explanatory-body", "selectedSpans": [{"start": 8, "end": 31, "text": "Không coi trục tiêu chí"}]}, "Nhiều tiêu chí song song — Ba tiêu chí đều thang 0–10 điểm; hai nhóm A/B. Mỗi trục là một tiêu chí độc lập, không phải kỳ thời gian. Giữ đơn vị, thang từng trục và ảnh hưởng của thứ tự tiêu chí. Dữ liệu: A · X/Y/Z: 2 / 8 / 4 · B · X/Y/Z: 7 / 3 / 9.": {"role": "explanatory-body", "selectedSpans": [{"start": 90, "end": 106, "text": "tiêu chí độc lập"}, {"start": 145, "end": 160, "text": "thang từng trục"}]}, "Dùng khi — Đọc mở, cao, thấp và đóng trong từng kỳ.": {"role": "explanatory-body", "selectedSpans": [{"start": 15, "end": 36, "text": "mở, cao, thấp và đóng"}]}, "Tránh — Không dùng thay hộp phân bố hoặc để mở/đóng nằm ngoài thấp/cao.": {"role": "explanatory-body", "selectedSpans": [{"start": 8, "end": 35, "text": "Không dùng thay hộp phân bố"}]}, "Nến khoảng và hai thời điểm — Ba kỳ; mở/cao/thấp/đóng trên thang 0–10 điểm minh họa. Mở/đóng không phải hai tứ phân vị và phải nằm giữa thấp/cao. Màu chỉ hướng tăng/giảm, không phải trạng thái ngoại lệ. Dữ liệu: Kỳ 1 · Mở/Cao/Thấp/Đóng: 4 / 8 / 2 / 6 · Kỳ 2 · Mở/Cao/Thấp/Đóng: 6 / 9 / 3 / 5 · Kỳ 3 · Mở/Cao/Thấp/Đóng: 5 / 10 / 4 / 8.": {"role": "explanatory-body", "selectedSpans": [{"start": 85, "end": 118, "text": "Mở/đóng không phải hai tứ phân vị"}, {"start": 122, "end": 144, "text": "phải nằm giữa thấp/cao"}]}, "Dùng khi — Minh họa giá trị của các vùng tự tạo có nhãn rõ.": {"role": "explanatory-body", "selectedSpans": [{"start": 36, "end": 47, "text": "vùng tự tạo"}]}, "Tránh — Không nhận là địa giới thật, bản đồ số liệu địa lý hoặc diện tích tỷ lệ.": {"role": "explanatory-body", "selectedSpans": [{"start": 8, "end": 35, "text": "Không nhận là địa giới thật"}]}, "Bản đồ vùng sơ đồ — Ba vùng A 4; B 7; C 2 mục. Hình không theo địa lý thật. Các vùng là hình tự tạo, không phải địa giới thật, bản đồ địa lý tô màu theo số liệu hay diện tích tỷ lệ với giá trị. Dữ liệu: Vùng A: 4 mục · Vùng B: 7 mục · Vùng C: 2 mục.": {"role": "explanatory-body", "selectedSpans": [{"start": 52, "end": 74, "text": "không theo địa lý thật"}, {"start": 101, "end": 125, "text": "không phải địa giới thật"}]}, "Dùng khi — Đọc một chỉ số tổng và các dòng số chi tiết cần đối chiếu.": {"role": "explanatory-body", "selectedSpans": [{"start": 19, "end": 30, "text": "chỉ số tổng"}]}, "Tránh — Không tính thẻ số là một kiểu mã hóa thống kê mới hoặc bỏ phép cộng đối chiếu.": {"role": "explanatory-body", "selectedSpans": [{"start": 8, "end": 25, "text": "Không tính thẻ số"}]}, "Chỉ số và bảng chi tiết — Tổng 15 mục = Đọc 6 + Dựng 5 + Kiểm 4. Đây là chỉ số kèm bảng số, không phải cách mã hóa thống kê riêng; giữ phép cộng đối chiếu. Dữ liệu: Tổng: 15 mục · Đọc: 6 mục · Dựng: 5 mục · Kiểm: 4 mục.": {"role": "explanatory-body", "selectedSpans": [{"start": 135, "end": 154, "text": "phép cộng đối chiếu"}]}, "Dùng khi — Chọn hướng xử lý dựa trên các điều kiện có nhánh được ghi rõ.": {"role": "explanatory-body", "selectedSpans": [{"start": 41, "end": 59, "text": "điều kiện có nhánh"}]}, "Tránh — Không dùng cạnh phụ thuộc thay cho điều kiện hoặc bỏ tên nhánh có/không.": {"role": "explanatory-body", "selectedSpans": [{"start": 8, "end": 33, "text": "Không dùng cạnh phụ thuộc"}]}, "Cây lựa chọn — Hai điều kiện: có nguồn và cần duyệt; ba hướng đi. Nhánh ghi điều kiện và kết quả có/không, không phải phụ thuộc hay lượng chảy. Mẫu chỉ hỗ trợ “Có nguồn?” và “Cần duyệt?”; điều kiện khác báo chưa hỗ trợ. Dữ liệu: Chưa có nguồn: Bổ sung · Có nguồn · Cần duyệt: Xin duyệt · Có nguồn · Không cần duyệt: Dựng.": {"role": "explanatory-body", "selectedSpans": [{"start": 19, "end": 28, "text": "điều kiện"}, {"start": 30, "end": 38, "text": "có nguồn"}]}, "Dùng khi — Đọc hành động, điểm khó và cách cải thiện theo từng bước.": {"role": "explanatory-body", "selectedSpans": [{"start": 53, "end": 67, "text": "theo từng bước"}]}, "Tránh — Không coi văn bản định tính là mức nhiệt hay số đo trên ma trận.": {"role": "explanatory-body", "selectedSpans": [{"start": 8, "end": 35, "text": "Không coi văn bản định tính"}]}, "Hành trình theo bước — Ba bước; đối chiếu hành động, điểm khó và cách cải thiện. Đây là bảng hành trình định tính, không phải ma trận số; giữ vai trò từng dòng và thứ tự bước. Không đọc văn bản như mức nhiệt hay số đo. Dữ liệu: Đọc: Đọc tài liệu / Thiếu nguồn / Bổ sung nguồn · Dựng: Dựng mẫu / Vai trò chưa rõ / Ánh xạ vai trò · Kiểm: Kiểm đầu ra / Lỗi hiển thị / Sửa lại.": {"role": "explanatory-body", "selectedSpans": [{"start": 88, "end": 113, "text": "bảng hành trình định tính"}, {"start": 138, "end": 159, "text": "giữ vai trò từng dòng"}]}, "Phạm vi và nguồn — Giữ đủ 50 tiểu bang và Washington, DC. Nguồn U.S. Census 2017 qua us-atlas 3.0.1; ghi nhận 17/10/2026. Alaska và Hawaii đổi vị trí; Alaska thu nhỏ tương đối. Không dùng để đo đạc.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 16, "text": "Phạm vi và nguồn"}, {"start": 177, "end": 197, "text": "Không dùng để đo đạc"}]}, "Cách đọc — Màu chỉ đánh dấu hình dạng, không phải số liệu thống kê. Tìm hoặc chọn từng tiểu bang/DC trong HTML; các nhãn Alaska, Hawaii và Washington, DC được giữ.": {"role": "explanatory-body", "selectedSpans": [{"start": 39, "end": 66, "text": "không phải số liệu thống kê"}]}, "Nguồn và phạm vi — Natural Earth v5.1.2, độ khái quát 1:10 triệu; đất liền, một số đảo và lớp đảo nhỏ riêng. Ghi nhận nguồn 17/10/2026. Chấm là vị trí đại diện; hình đảo nhỏ từ địa hình khái quát, không thay hải đồ. Bảy điểm không phải danh mục đầy đủ đảo, đá, bãi cạn hay bãi ngầm.": {"role": "role-exception", "selectedSpans": []}, "Tên gọi và bối cảnh — Giữ tên Hoàng Sa, Trường Sa và thể hiện chủ quyền theo nguồn chính thức Việt Nam; chủ quyền tại hai quần đảo có tranh chấp quốc tế. Natural Earth không thay nguồn chính thức về chủ quyền.": {"role": "explanatory-body", "selectedSpans": [{"start": 62, "end": 71, "text": "chủ quyền"}, {"start": 77, "end": 93, "text": "nguồn chính thức"}]}, "Giới hạn địa lý — Không thể hiện ranh giới biển; điểm đại diện không phải đơn vị hành chính như mẫu Hoa Kỳ. Không dùng để đo đạc, phân định chủ quyền hoặc xác định ranh giới hành chính hiện hành.": {"role": "explanatory-body", "selectedSpans": [{"start": 18, "end": 47, "text": "Không thể hiện ranh giới biển"}, {"start": 108, "end": 128, "text": "Không dùng để đo đạc"}]}, "Đường bao và nhãn — Phú Quốc và đảo chính Côn Đảo có trong dữ liệu nền. Nhãn Côn Đảo gắn với hình đảo, không dùng tọa độ tự nhận là đo đạc chính thức.": {"role": "explanatory-body", "selectedSpans": [{"start": 103, "end": 128, "text": "không dùng tọa độ tự nhận"}]}, "Nhãn và lưới tọa độ — VIỆT NAM · Quần đảo Hoàng Sa (Việt Nam) · Quần đảo Trường Sa (Việt Nam) · BIỂN ĐÔNG · Phú Quốc · Côn Đảo. Kinh tuyến: 102°Đ, 106°Đ, 110°Đ, 114°Đ, 118°Đ. Vĩ tuyến: 8°B, 12°B, 16°B, 20°B, 24°B.": {"role": "role-exception", "selectedSpans": []}, "10 độ 14 phút 26.2 giây  Bắc; 103 độ 58 phút 21.2 giây  Đông. Số thập phân: 10.2406111 / 103.9725556. Nguồn S1; loại K1.": {"role": "role-exception", "selectedSpans": []}, "16 độ 32 phút 0 giây  Bắc; 111 độ 36 phút 7 giây  Đông. Số thập phân: 16.5333333 / 111.6019444. Nguồn S2; loại K1.": {"role": "role-exception", "selectedSpans": []}, "16 độ 50 phút 2 giây  Bắc; 112 độ 20 phút 0 giây  Đông. Số thập phân: 16.8338889 / 112.3333333. Nguồn S2; loại K1.": {"role": "role-exception", "selectedSpans": []}, "15 độ 47 phút 2 giây  Bắc; 111 độ 11 phút 8 giây  Đông. Số thập phân: 15.7838889 / 111.1855556. Nguồn S2; loại K1.": {"role": "role-exception", "selectedSpans": []}, "8 độ 38 phút 30 giây  Bắc; 111 độ 55 phút 55 giây  Đông. Số thập phân: 8.6416667 / 111.9319444. Nguồn S3; loại K1.": {"role": "role-exception", "selectedSpans": []}, "Bia chủ quyền đảo Song Tử Tây": {"role": "role-exception", "selectedSpans": []}, "11 độ 25 phút 55 giây  Bắc; 114 độ 18 phút 00 giây  Đông. Số thập phân: 11.4319444 / 114.3. Nguồn S4; loại K2.": {"role": "role-exception", "selectedSpans": []}, "Bia chủ quyền đảo Nam Yết": {"role": "role-exception", "selectedSpans": []}, "10 độ 10 phút 45 giây  Bắc; 114 độ 22 phút 00 giây  Đông. Số thập phân: 10.1791667 / 114.3666667. Nguồn S4; loại K2.": {"role": "role-exception", "selectedSpans": []}, "Tọa độ theo bài giới thiệu địa lý.": {"role": "role-exception", "selectedSpans": []}, "Tọa độ bia chủ quyền; không phải tâm đảo.": {"role": "role-exception", "selectedSpans": []}, "Nguồn và tỷ lệ — Đường bờ Natural Earth 4.1.0 qua world-atlas 2.0.2; độ khái quát 1:110 triệu, đảo rất nhỏ có thể không hiện. Ghi nhận nguồn 17/10/2026. Bề mặt chỉ có đường bờ tự nhiên, không phân loại chủ quyền.": {"role": "role-exception", "selectedSpans": []}, "Khối cầu và bản phẳng — Giữ khối cầu thật, tương tác và bản phẳng dự phòng khi không dựng được khối cầu. Xoay, đổi góc nhìn trong HTML; khi thiết bị yêu cầu giảm chuyển động, khối cầu đứng yên mặc định. Không thay bản đồ chi tiết Việt Nam.": {"role": "explanatory-body", "selectedSpans": [{"start": 157, "end": 173, "text": "giảm chuyển động"}]}, "Tránh — Không biến khối cầu thành hình trang trí, công cụ phân loại chủ quyền hay bản đồ tô màu theo số liệu.": {"role": "explanatory-body", "selectedSpans": [{"start": 8, "end": 27, "text": "Không biến khối cầu"}]}, "Cách dựng — Khối cầu WebGL viết riêng, không dùng mã chạy Three.js hoặc D3.": {"role": "explanatory-body", "selectedSpans": [{"start": 12, "end": 26, "text": "Khối cầu WebGL"}]}, "Đọc quy tắc. Chọn mẫu. Triển khai theo đúng ngữ cảnh.": {"role": "explanatory-body", "selectedSpans": [{"start": 4, "end": 11, "text": "quy tắc"}]}, "Quy tắc định hình chữ, màu và bố cục; Thư viện lưu tài sản; Ứng dụng kết hợp chúng thành đầu ra. Cả ba dùng cùng mô hình và phiên bản HAHA, không tạo ba bộ chuẩn.": {"role": "explanatory-body", "selectedSpans": [{"start": 18, "end": 26, "text": "chữ, màu"}, {"start": 108, "end": 133, "text": "cùng mô hình và phiên bản"}]}, "Giữ logo, đen–trắng và Be Vietnam Pro từ tài sản HAHA; không tạo dấu nhận diện thứ hai. Nêu vấn đề doanh nghiệp, cách xử lý và bước triển khai, dùng thứ bậc chữ và khoảng trắng.": {"role": "explanatory-body", "selectedSpans": [{"start": 55, "end": 86, "text": "không tạo dấu nhận diện thứ hai"}, {"start": 164, "end": 176, "text": "khoảng trắng"}]}, "Vai trò, giá trị, biến thể, tổ hợp, bố cục, giọng văn và phép kiểm có một nguồn; mẫu hiển thị và tài liệu sinh cùng phiên bản. Thư viện giữ mã ổn định, chức năng, cấu tạo, trạng thái, nguồn, quyền, phụ thuộc và bằng chứng; không tự thêm bộ chữ/màu. Ứng dụng kết hợp quy tắc với tài sản và liên kết phần đã dùng, không tạo chuẩn độc lập. Đọc chuẩn → phân loại chức năng → tìm tài sản → ánh xạ → dựng → kiểm nguồn/hiển thị → ghi bằng chứng → nhận đúng phạm vi. Mâu thuẫn chuẩn phải nêu quy tắc, ảnh hưởng và phương án tương thích. Ngoại lệ/sửa chuẩn cần phạm vi, lý do, phiên bản và bằng chứng; không âm thầm thêm cỡ, màu, font. Thay quy tắc phải kiểm các nơi bị ảnh hưởng. Ứng dụng gồm Slide, PDF, Website, App, Design và Edit; mẫu vẫn phải kiểm với nội dung và đầu ra thật của nhiệm vụ.": {"role": "explanatory-body", "selectedSpans": [{"start": 140, "end": 150, "text": "mã ổn định"}, {"start": 312, "end": 335, "text": "không tạo chuẩn độc lập"}]}, "PNG gốc 1920×1080; mực đen (421,337)–(1499,682), 1078×345 px, khoảng 3,125:1; mực trắng (303,329)–(1617,750), 1314×421 px. Không dùng crop đen cho trắng; canvas không là vùng an toàn. Chọn theo hash/variant, contain, opacity 1; không vẽ/gõ lại, recolor, kéo méo hoặc gắn bóng/viền.": {"role": "explanatory-body", "selectedSpans": [{"start": 228, "end": 243, "text": "không vẽ/gõ lại"}]}, "H là cao nét nhìn thấy; 1H mỗi cạnh là đề xuất bản thử, chưa là số đo HAHA chính thức. Kiểm cỡ nhỏ ở đầu ra thật; không suy cỡ in tối thiểu từ HTML.": {"role": "explanatory-body", "selectedSpans": [{"start": 39, "end": 46, "text": "đề xuất"}, {"start": 114, "end": 123, "text": "không suy"}]}, "Chọn theo màu thật: Logo white.png chứa bản đen; Logo black.png chứa bản trắng. Đen trên nền sáng, trắng trên nền tối; giữ nét chữ và tỷ lệ. Đổi vị trí/bản trước khi thêm nền đỡ.": {"role": "explanatory-body", "selectedSpans": [{"start": 10, "end": 18, "text": "màu thật"}, {"start": 89, "end": 97, "text": "nền sáng"}]}, "Nền đủ yên/tương phản thì không cần nền đỡ. Tránh mặt, tiêu đề, dữ liệu, phụ đề. Nền thay sáng–tối hoặc không có chỗ rõ thì dùng nền đỡ đen/trắng có chủ đích và khoảng thở; kiểm mọi khung video và cỡ nhỏ nhất.": {"role": "explanatory-body", "selectedSpans": [{"start": 11, "end": 21, "text": "tương phản"}, {"start": 197, "end": 203, "text": "cỡ nhỏ"}]}, "HTML multiply cho PNG đen/canvas trắng, screen cho trắng/canvas đen là hòa trộn hiển thị, không tạo alpha. Nhu cầu alpha/vector chưa có nguồn đạt thì chưa xác nhận. Tách nền AI chỉ từ nguồn khóa, kiểm alpha 0–255, lỗ chữ, contour, khoảng cách/tỷ lệ trên sáng/tối/ảnh; từ chối hình bị lệch.": {"role": "explanatory-body", "selectedSpans": [{"start": 133, "end": 141, "text": "có nguồn"}, {"start": 150, "end": 163, "text": "chưa xác nhận"}]}, "Ưu tiên vector/PNG alpha đã xác nhận khi cần. Quyền công khai, vector/alpha chính thức, lockup và cỡ in tối thiểu chưa xác nhận; giữ nguồn không cấp thêm quyền công bố/đăng ký.": {"role": "explanatory-body", "selectedSpans": [{"start": 114, "end": 127, "text": "chưa xác nhận"}, {"start": 129, "end": 138, "text": "giữ nguồn"}]}, "Giữ bảy vai trò đã khai báo; giãn chữ 0 px theo mẫu nguồn. Một ý chính và một cấp lớn nhất. Chỉ thêm tiêu đề phụ khi có phần phụ thật; không dùng tiêu đề làm nhãn điều khiển, chú thích thay thân bài hoặc chữ kỹ thuật thay giải thích thường. Be Vietnam Pro dùng cho cả ba nhóm: tiêu đề/lời trích 400/700; thân bài/nhãn/số liệu/liên kết/điều khiển 400/700; lệnh/mã 400. Dự phòng Arial hoặc sans-serif theo vai trò. Năm TTF cục bộ có trong nguồn; kiểm quyền trước khi phân phối. Liên kết có đích thật, gạch chân và trạng thái bàn phím; không chỉ đổi màu. Lời trích giữ nguồn; không thêm đường dọc khi đã có dấu trích. Nhãn nhấn và nút dùng đậm 700.": {"role": "explanatory-body", "selectedSpans": [{"start": 4, "end": 15, "text": "bảy vai trò"}, {"start": 533, "end": 550, "text": "không chỉ đổi màu"}]}, "Tổ hợp tiêu đề/tên nhóm/thân bài/chú thích: slide 1280 × 720 dùng 64/32/24/20 px; trang đọc dùng 48/24/20/16 px; màn hình hẹp dùng 32/16/16/16 px. Không lấy cỡ trung gian giữa các bộ. Các cỡ theo vai trò và giãn dòng phải giữ từ bảng chữ gốc; không đổi font, giảm chữ hoặc hạ vai trò để vừa nội dung. Khối chỉ có một nhãn/từ/các dòng ngang cấp dùng đậm 700 cho nhãn. Khối có phân cấp giữ vai trò riêng; nhãn trục, chú thích và đường nối giữ độ đậm theo chức năng. Đổi độ đậm phải kiểm lại độ rộng và khoảng hở. Một nhóm chữ/số/icon độc lập trong khung căn giữa hai chiều, nhiều dòng tính như một nhóm; cân khoảng hai bên trong sai số 1 px ở kích thước đọc, giữ đệm và không tính bóng vào tâm. Khối nhiều nhóm giữ cấu trúc đọc; không suy thành căn giữa cả thẻ. Đo sau tải font ở Thư viện, Ứng dụng, trang đọc và slide; kiểm dấu Việt và số: Ẩn / Đúng / 01 / 1.335 / 42,47%. Nội dung dài phải tăng khung, đổi bố cục hoặc tiếp trang; không giảm chữ.": {"role": "explanatory-body", "selectedSpans": [{"start": 448, "end": 462, "text": "theo chức năng"}, {"start": 668, "end": 691, "text": "không tính bóng vào tâm"}]}, "Nền đọc sáng; dùng mực đen, giữ khoảng trắng.": {"role": "explanatory-body", "selectedSpans": [{"start": 32, "end": 44, "text": "khoảng trắng"}]}, "Cùng nền giấy; phân cấp bằng vị trí, đường viền và bóng của lớp chịu trách nhiệm.": {"role": "explanatory-body", "selectedSpans": [{"start": 69, "end": 80, "text": "trách nhiệm"}]}, "Nội dung chính trên nền sáng.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 14, "text": "Nội dung chính"}]}, "Nhấn thông tin có nghĩa bằng đen và độ đậm; không nhấn mọi yếu tố.": {"role": "explanatory-body", "selectedSpans": [{"start": 36, "end": 42, "text": "độ đậm"}]}, "Xám đậm với chữ trắng; không tự ngụ ý hoàn thành hay lỗi.": {"role": "explanatory-body", "selectedSpans": [{"start": 23, "end": 37, "text": "không tự ngụ ý"}]}, "Phân vùng nhẹ; nhãn và hình vẫn cần đọc rõ.": {"role": "explanatory-body", "selectedSpans": [{"start": 36, "end": 42, "text": "đọc rõ"}]}, "Dùng mực sáng và kiểm tương phản theo nền thật.": {"role": "explanatory-body", "selectedSpans": [{"start": 22, "end": 32, "text": "tương phản"}]}, "Giữ thứ bậc trong chế độ tối.": {"role": "explanatory-body", "selectedSpans": [{"start": 18, "end": 28, "text": "chế độ tối"}]}, "Giữ dấu nhấn, viền bàn phím và quan hệ khi đổi chế độ.": {"role": "explanatory-body", "selectedSpans": [{"start": 14, "end": 27, "text": "viền bàn phím"}]}, "Đệm rộng 32 px, hẹp 16 px, trong thẻ 24 px; trong nhóm 16 px, giữa nhóm hướng dẫn 32 px. Khoảng nhóm 24 px; kiểm lại khi mở chi tiết, xuống dòng hoặc đổi màn hình, không dựa vào khoảng mặc định. Khung nội dung/điều khiển bo 4 px, hình mang dữ liệu 2 px; phần nối sát nhau giữ thẳng, chỉ bo đường bao ngoài. Giữa thẻ ít nhất 24 px và còn ít nhất 16 px giữa phần đã vẽ, tính bóng, viền và vòng bàn phím. Khung có chú thích bên ngoài giữ ít nhất 24 px khoảng trống thực sau phần đã vẽ; mốc 16 px tăng 50% thành 24 px. Chú thích vẫn thuộc hình phía trên; không áp dụng khoảng này cho dòng chữ hoặc icon–chữ. Khoảng hộp tới chú thích = 24 px + phần bóng nhô về phía chú thích: phẳng 24, nút thường 26, hover 27, lớp nổi 28 px. Tính phần viền/vòng bàn phím vượt mép riêng; dấu dữ liệu không bóng vẫn giữ 24 px.": {"role": "explanatory-body", "selectedSpans": [{"start": 356, "end": 366, "text": "phần đã vẽ"}, {"start": 449, "end": 466, "text": "khoảng trống thực"}]}, "Đo mép đã vẽ, gồm đầu nét và góc nối; chi tiết độc lập không chạm viền bao. Mối nối cấu tạo có chủ ý phải giữ và ghi lý do. Hình đối xứng dựng quanh trục; kim la bàn là hình thoi cân quanh tâm 16/16, không nắn đỉnh bằng mắt. Cùng chức năng giữ nét đo vuông góc cạnh, kể cả cạnh chéo, theo master từng họ; không áp độ dày hoặc khuôn mặt mascot KAI cho HAHA. Chi tiết trong có thể mảnh hơn viền nếu rõ ở cỡ thật; nét nhập viền hoặc mất ở 24 px phải đơn giản hóa hay dùng biến thể nhỏ. Khung 32 có khoảng ngoài ít nhất 4 đơn vị. Cặp nhận diện cùng vai trò có vùng hình rộng 24 px, cao khoảng 24 px; sai lệch rộng/cao tối đa 5%, tâm tối đa 1 đơn vị. Đây là tiêu chí HAHA, không áp cho mọi hình; hình dài/hẹp có lý do riêng, không kéo méo. Giữ tỷ lệ, tâm, nét và một hình gốc cho bản tĩnh/chuyển động. Đo vùng thực kể cả stroke, kiểm cặp ở 24/32/64 px và minh họa 220 px, sáng/tối; kiểm đầu/giữa/cuối/dừng sau hiệu chỉnh, không tăng CSS riêng từng nơi.": {"role": "explanatory-body", "selectedSpans": [{"start": 38, "end": 74, "text": "chi tiết độc lập không chạm viền bao"}, {"start": 735, "end": 754, "text": "Giữ tỷ lệ, tâm, nét"}]}, "Dùng đúng các vai trò và mã ở bảng màu gốc HAHA; phần chưa có vai trò không tự được dùng. Nền không tự trở thành màu chữ; bề mặt không tạo thêm cấp chữ. Không thêm bảng màu riêng cho Thư viện hay Ứng dụng. Đen–trắng và trung tính tạo thứ bậc bằng vị trí, độ đậm, khoảng trắng, viền và bóng của lớp chịu trách nhiệm. Nhãn trên nền nhấn dùng chữ trắng; từ khóa giải thích dùng trung tính, đậm 700 theo cỡ thân bài. Kiểm cặp chữ trên nền sáng, dịu và tối. Đổi giá trị màu phải kiểm lại tương phản, trạng thái và mọi nơi dùng bị ảnh hưởng. Trạng thái chọn giữ cả chữ và hình; màu không thay nhãn, quan hệ hoặc bằng chứng.": {"role": "explanatory-body", "selectedSpans": [{"start": 49, "end": 69, "text": "phần chưa có vai trò"}, {"start": 129, "end": 151, "text": "không tạo thêm cấp chữ"}]}, "Đây là thông số đề xuất theo yêu cầu, không tự thành quy định gốc của brandkit. HAHA dùng bóng cứng; giữ màu, chữ, hình và chức năng nguồn. Thông số x/y/blur/spread, px; opacity 1: điều khiển 2/2/0/0; bề mặt và lớp nổi 4/4/0/0; hover 3/3/0/0; pressed 1/1/0/0. Disabled vẫn có bóng nhỏ 1 px. Thẻ, bảng, khung biểu đồ, giao diện và bố cục độc lập nhận một bóng ngoài. Nhóm nối liền nhận bóng trên đường bao chung; không đổ bóng lên mọi lớp con hoặc từng tab. Bóng thuộc khung biểu đồ; không thêm vào dấu dữ liệu, trục, nhãn, chữ hoặc số. Logo, ảnh và nét icon giữ nguồn; lớp chức năng chứa chúng mới nhận bóng khi cần. Giữ ít nhất 16 px phần đã vẽ giữa khối độc lập, tính viền bàn phím. Chọn màu bóng theo nền nhận trực tiếp, kể cả vùng sáng nằm trong trang tối. Áp dụng cùng vai trò ở website, ứng dụng, slide, PDF, thiết kế và biên tập; giữ bóng khi in. Chỉ chế độ màu tương phản của hệ thống được thay bóng bằng viền hệ thống. Kiểm bản xuất thật, thao tác và Tab; HTML không chứng minh PDF đã đạt.": {"role": "explanatory-body", "selectedSpans": [{"start": 38, "end": 65, "text": "không tự thành quy định gốc"}, {"start": 350, "end": 364, "text": "một bóng ngoài"}]}, "Áp dụng cho thân bài HAHA viết/chuyển thể ở mọi đầu ra; nguyên văn, mã, đường dẫn và phần phải sao chép nguyên vẹn giữ nguồn. Nhấn khái niệm, định nghĩa, điều kiện, giới hạn, kết luận hoặc hành động bằng đậm 700, màu trung tính hỗ trợ, kế thừa cỡ thân bài. Phần lớn câu giữ thường; không tô toàn đoạn, nhấn từ nối/nguồn/mọi số hoặc chọn từ theo số lượng cố định. Ý song song dùng danh sách; bước có thứ tự dùng số. Icon chỉ thay dấu đầu dòng khi thêm nghĩa; nếu không, giữ dấu thường. Đọc riêng các từ nhấn rồi đọc toàn đoạn để kiểm nghĩa, phủ định và phạm vi; kiểm khoảng cách/tương phản rộng–hẹp, sáng–tối.": {"role": "explanatory-body", "selectedSpans": [{"start": 257, "end": 280, "text": "Phần lớn câu giữ thường"}, {"start": 540, "end": 559, "text": "phủ định và phạm vi"}]}, "Khuyến nghị đối ứng dùng nhãn và dấu đối ứng: dấu kiểm là nên làm, × là nên tránh, không phải đã hoàn tất hoặc lỗi thực tế. Mỗi mục nên/tránh giữ dấu khi tách khỏi tiêu đề. Icon bổ trợ, không thay chữ: khung 24 px, nét 2 px, khoảng trống 4 px. Icon lặp nghĩa chữ ẩn khỏi trình đọc màn hình; icon chứa thông tin mới có tên/chú giải tương đương. Phân biệt khuyến nghị/điều tránh bằng nhãn, dấu và bố cục đen–trắng/trung tính; không chỉ dựa màu. Kiểm tương phản theo nền thật. Che màu vẫn phải hiểu quan hệ và trạng thái qua nhãn/hình; kiểm khoảng thở và thứ tự đọc cả hai chế độ.": {"role": "explanatory-body", "selectedSpans": [{"start": 186, "end": 200, "text": "không thay chữ"}, {"start": 552, "end": 562, "text": "thứ tự đọc"}]}, "Mật độ tính theo đơn vị có nghĩa: tối đa một icon dẫn nghĩa mỗi mục/nhãn cùng cấp, không gộp trạng thái/thao tác riêng thành trang trí. Một danh sách dùng cách đánh dấu nhất quán; không trộn dấu thường, emoji và nhiều bộ nét cùng cấp. Icon tiêu đề thường không lặp từng câu, trừ cặp nên/tránh. Icon 24 px, nét 2 px; icon–chữ 12 px, giữa mục 16 px. Căn icon với dòng đầu khi chữ nhiều dòng; icon + một nhãn trong hình căn giữa cả nhóm, giữ đệm. Nội dung dài nhóm lại hoặc tiếp trang, không thu nhỏ chữ/icon. Giữ ul/ol thật. Điều khiển chỉ icon có tên truy cập. Không dùng icon khi mơ hồ, chật, cạnh tranh hình/số liệu chính, phá nguyên văn hoặc chỉ lấp chỗ trống. Bảng hẹp được cuộn ngang bằng bàn phím Tab rồi phím mũi tên. Đặt điều kiện/nguồn cạnh ý; áp dụng khoảng chú thích thực 24 px sau bóng đã nêu. Che màu, bỏ icon và đọc lướt vẫn phải hiểu đủ; kiểm câu 2–3 dòng, hẹp, sáng/tối, in/PDF, dừng chuyển động; đối chiếu icon/nguồn/màu/phiên bản Thư viện. Mật độ là đề xuất HAHA, không định mức mọi thương hiệu.": {"role": "explanatory-body", "selectedSpans": [{"start": 155, "end": 178, "text": "cách đánh dấu nhất quán"}, {"start": 483, "end": 505, "text": "không thu nhỏ chữ/icon"}]}, "Chuyển động phải làm rõ chức năng; dữ liệu quan trọng không biến mất khi chạy/dừng. Dùng cùng hình gốc, tĩnh là dự phòng hợp lệ. Kim la bàn và biểu trưng chữ HAHA 3 giây; lửa 2 giây; ease-in-out, trở về trạng thái đầu. Ưu tiên dừng toàn bộ; mẫu ngoài màn hình tạm dừng, tôn trọng giảm chuyển động. Kiểm bắt đầu/giữa/kết/dừng/chạy lại/giảm chuyển động; giữ hình, khoảng thở và nội dung. Không dùng chuyển động để lấp chỗ trống.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 33, "text": "Chuyển động phải làm rõ chức năng"}, {"start": 35, "end": 53, "text": "dữ liệu quan trọng"}]}, "Đen–trắng, độ đậm và khoảng trắng dẫn hướng; không nhấn mọi yếu tố. Giữ thông điệp/dữ liệu/hành động làm trọng tâm, nền sạch và đầy đủ hình tham chiếu quan trọng; căn số theo cột và giữ đơn vị. Kiểm dấu Việt, bàn phím và giảm chuyển động. Không để nền giả tưởng cản đọc/nhập liệu; không dùng glow, gradient hoặc kính mờ chỉ để gợi “AI”; nhãn chức năng không thành thuật ngữ game khó hiểu. Không dùng ảnh AI làm bằng chứng kinh doanh hoặc giấu dữ liệu theo vòng chuyển động. Phá lưới/tăng chuyển động chỉ khi giúp kể chuyện và đã kiểm đọc được; danh sách tránh không cấm mọi biểu đạt sáng tạo.": {"role": "explanatory-body", "selectedSpans": [{"start": 221, "end": 237, "text": "giảm chuyển động"}, {"start": 389, "end": 406, "text": "Không dùng ảnh AI"}]}, "Quy tắc thiết kế, thông số CSS và giá trị thiết kế cùng lấy nguồn từ mô hình HAHA; các bản Markdown đi cùng gói để đọc/dùng lại. Đổi quy tắc phải cập nhật nguồn và kiểm nơi dùng, không sửa riêng tài liệu sinh ra.": {"role": "explanatory-body", "selectedSpans": [{"start": 146, "end": 160, "text": "cập nhật nguồn"}, {"start": 179, "end": 211, "text": "không sửa riêng tài liệu sinh ra"}]}, "Phần nhấn cách đường bao thật kể cả cạnh nghiêng; khiên HAHA dùng lưới 32, khoảng hở tối thiểu 2 đơn vị trong toàn bộ chuyển động. Kiểm ở 24/32/64 px và cỡ minh họa. Kiểm chi tiết thêm ở 16 px; nếp gấp, quai và vách chia có chủ ý được giữ. Khoảng hở bên trong khác khoảng từ icon đến khung, chữ hoặc hình bên cạnh; giữ một hình gốc ở mọi nơi dùng.": {"role": "explanatory-body", "selectedSpans": [{"start": 75, "end": 94, "text": "khoảng hở tối thiểu"}, {"start": 319, "end": 331, "text": "một hình gốc"}]}, "Viết cho chủ doanh nghiệp/người phụ trách thương hiệu, thương mại, vận hành Việt Nam; chọn đúng nhóm và quyết định. HAHA tư vấn gắn triển khai thị trường–thương hiệu–thương mại, không chỉ công cụ/hình ảnh. Lời nói ưu tiên đội triển khai, từng bước, theo lựa chọn đã xác nhận.": {"role": "explanatory-body", "selectedSpans": [{"start": 26, "end": 41, "text": "người phụ trách"}]}, "H1 Chuyên môn: nối thông tin–quyết định–vận hành, không phô thuật ngữ; nhãn ngắn không cần giảng. H2 Trực tiếp: vướng mắc/quyết định có căn cứ, tôn trọng chủ doanh nghiệp; không chẩn đoán thiếu dữ kiện/gây áp lực trong lỗi. H3 Thực tế: ưu tiên, người/việc/đối tượng/kiểm; không làm mọi kênh, thiếu căn cứ có thể phải chờ. H4 Trung thực: tách biết/giả định/mục tiêu/kết quả đo, giới hạn cạnh kết luận, không rải cảnh báo vô can. H5 Hỗ trợ: rõ trách nhiệm HAHA/doanh nghiệp đã thống nhất; chưa chốt gọi đề xuất, không nhận mọi việc/hứa vận hành hoàn hảo.": {"role": "explanatory-body", "selectedSpans": [{"start": 442, "end": 453, "text": "trách nhiệm"}, {"start": 510, "end": 529, "text": "không nhận mọi việc"}]}, "3 · Tình huống và trình tự": {"role": "role-exception", "selectedSpans": []}, "Bình thường: bài toán → thông tin → lựa chọn → bước. Lần đầu: nhóm doanh nghiệp → việc HAHA tham gia → nhu cầu. Hợp tác: mục tiêu chốt → phạm vi → trách nhiệm → bước, không giả đồng ý. Thành công chỉ đầu ra thật, không thành tăng trưởng. Trống nêu thiếu/cách bắt đầu thật. Lỗi: thất bại → ảnh hưởng biết → xử lý hỗ trợ, không đùa/hứa đã lưu/thử lại an toàn. Chưa chắc: biết → chưa biết → tác động → xác minh. Xóa: đối tượng/phạm vi → hậu quả → điều kiện → lựa chọn, hành vi phải thật. Tiền/thông tin: tình trạng → tác động → hành động được phép → hỗ trợ xác nhận; không xin bí mật/tự đặt giá/trấn an. Hỗ trợ: vướng → ảnh hưởng → người phụ trách → bước thống nhất, không đổ lỗi/hứa ngày mới. Đội: đầu ra → điều kiện → từng bước → kiểm → phần thiếu; thiếu quyền/dữ liệu thì giữ bước phụ thuộc.": {"role": "explanatory-body", "selectedSpans": [{"start": 167, "end": 183, "text": "không giả đồng ý"}, {"start": 525, "end": 544, "text": "hành động được phép"}]}, "4 · Ngôn ngữ, viết và nói": {"role": "role-exception", "selectedSpans": []}, "Website nêu vai trò/vấn đề/việc làm với ai; đề xuất tách nhận định/đầu ra/phối hợp; báo cáo mở kết luận, kết quyết định; mạng xã hội dùng tình huống kinh doanh, không chỉ mẹo công cụ. Giao diện nêu hành động/trạng thái thật. Đội triển khai nghe mỗi nhịp một người–việc–đối tượng–kiểm; điều kiện trước bước, kết việc báo lại, không đọc danh mục/quảng cáo. Giọng âm thanh/thời lượng cần xác nhận riêng. HAHA/chúng tôi cho trách nhiệm đơn vị; bạn ở lời mời, doanh nghiệp khi phân tích. Anh/chị/tên/chức danh cần quan hệ xác nhận, chúng ta chỉ việc cùng làm. Ý Việt/động từ cụ thể, không trần tiếng Anh. Giữ HAHA Group/tên giao diện; thuật ngữ giải 1–9 từ Việt lần đầu. Viết hoa/đủ dấu, giữ trích/mã; ngày văn xuôi ngày 10 tháng 10 năm 2026, bảng 10/10/2026; giữ đơn vị/kỳ/đồng hoặc VND, không quy đổi. Bỏ cảm thán/emoji ở lỗi/cảnh báo/tiền.": {"role": "explanatory-body", "selectedSpans": [{"start": 52, "end": 66, "text": "tách nhận định"}, {"start": 562, "end": 576, "text": "động từ cụ thể"}]}, "Giữ chủ thể/doanh nghiệp/dịch vụ/nguồn/số/đơn vị/kỳ/phủ định/điều kiện/trách nhiệm. Giá/thời gian/kết quả cần nguồn nhiệm vụ, định vị không thay dữ kiện. Không thêm doanh thu/lợi nhuận/khách/chứng nhận/lời chứng/tiết kiệm/tiến độ; số website không là kiểm toán, tư vấn miễn phí không làm mọi dịch vụ miễn phí. Không nhận đã lưu/gửi/xóa/xong khi chưa có bằng chứng; nêu phần thiếu và tác động, không bịa khôi phục hoặc biến mục tiêu thành kết quả.": {"role": "explanatory-body", "selectedSpans": [{"start": 71, "end": 82, "text": "trách nhiệm"}, {"start": 353, "end": 363, "text": "bằng chứng"}]}, "Tiêu đề một ý; nút một hành động thật, không lời hứa. Trường có nhãn độc lập/gợi ý đúng; lỗi cạnh trường, chỉ bắt buộc khi thật. Trống/đang tải là hai trạng thái, không giả báo cáo/thời gian. Xác nhận sau bằng chứng, không hứa phản hồi. Đổi phạm vi nêu thay đổi và cách xem thật trước chốt. Biểu đồ giữ chỉ số/đơn vị/kỳ/nguồn; thay chỗ trống bằng dữ kiện, không suy loại chi phí. Bước có người/việc/đối tượng/kiểm và điều kiện nguồn.": {"role": "explanatory-body", "selectedSpans": [{"start": 23, "end": 37, "text": "hành động thật"}, {"start": 205, "end": 215, "text": "bằng chứng"}]}, "7 · Ví dụ có dữ kiện": {"role": "role-exception", "selectedSpans": []}, "Minh họa: có đơn hàng nhưng thiếu chi phí quảng cáo cùng kỳ thì chưa đủ căn cứ tăng ngân sách. Đội chọn kỳ, lấy hai nguồn đúng kỳ, kiểm rồi mới kết luận; thiếu thì ghi. Giao việc theo phân công hai bên chốt, thiếu người nhận thì báo doanh nghiệp xác nhận; ví dụ không là kết quả khách hoặc tự cấp quyền.": {"role": "explanatory-body", "selectedSpans": [{"start": 64, "end": 78, "text": "chưa đủ căn cứ"}, {"start": 144, "end": 152, "text": "kết luận"}]}, "Đặc tính từ Brand Guideline 2026 trang 11; bối cảnh trang 2/website ghi nhận 10/10/2026. Triển khai/xưng hô/ví dụ 0.10-trial-draft309 là đề xuất; ưu tiên nói với đội được xác nhận. Chưa đủ mẫu duyệt/đánh giá độc lập/bản thu, biến thể EN/người duyệt; không nhận giọng đã học/bản ngữ chứng nhận/hiệu quả đo. Khóa dữ kiện → chọn người/việc/ngôn ngữ/kênh → H1–H5 phù hợp → kiểm nghĩa/nhịp → bản ghép thật; không suy từ màu/ảnh/ép đủ đặc tính vào nhãn. Giữ một mô hình/phiên bản, ghi và kiểm phần sửa; không tự đổi chung/gửi/xuất bản.": {"role": "explanatory-body", "selectedSpans": [{"start": 181, "end": 198, "text": "Chưa đủ mẫu duyệt"}, {"start": 369, "end": 384, "text": "kiểm nghĩa/nhịp"}]}, "Nhận biết nội dung hoặc nguồn cần mở; dùng rộng trong thư viện và hướng dẫn.": {"role": "explanatory-body", "selectedSpans": [{"start": 24, "end": 36, "text": "nguồn cần mở"}]}, "Dùng cho tìm kiếm và tra cứu, với tên truy cập rõ.": {"role": "explanatory-body", "selectedSpans": [{"start": 34, "end": 49, "text": "tên truy cập rõ"}]}, "Đánh dấu việc đã kiểm thật; không biến minh họa thành xác nhận kết quả.": {"role": "explanatory-body", "selectedSpans": [{"start": 17, "end": 26, "text": "kiểm thật"}]}, "Gọi ra một gợi ý hoặc hướng xử lý cần xem xét.": {"role": "explanatory-body", "selectedSpans": [{"start": 22, "end": 33, "text": "hướng xử lý"}]}, "Đi tới bước hoặc nội dung tiếp theo trong đúng thứ tự.": {"role": "explanatory-body", "selectedSpans": [{"start": 47, "end": 53, "text": "thứ tự"}]}, "Nguồn colors.paper: #FFFFFF; chữ đen, vùng đọc yên.": {"role": "role-exception", "selectedSpans": []}, "Nguồn colors.muted: #E8E8E8; phân vùng nhẹ, giữ nhãn và tương phản.": {"role": "role-exception", "selectedSpans": []}, "Nguồn colors.dark: #080808; chữ trắng, kiểm logo và ảnh theo nền thật.": {"role": "role-exception", "selectedSpans": []}, "Ảnh gốc 1672×941 px, không upscale. Nhóm người và không gian làm việc là minh họa hư cấu, không phải bằng chứng khách hàng hay danh tính thật. Giữ toàn ảnh rộng cho slide; vùng chữ x5–34%, y12–62%; không che đầu, tay hoặc máy tính. Chữ và logo đặt riêng, không ghi vào ảnh. Trên mobile, giữ toàn ảnh rộng và đặt chữ ở khối riêng; không ép crop dọc. Không tự cấp quyền dùng các ảnh stock tham khảo. Đổi chủ thể theo công việc; kiểm tương phản ở đầu ra thật.": {"role": "explanatory-body", "selectedSpans": [{"start": 90, "end": 122, "text": "không phải bằng chứng khách hàng"}, {"start": 330, "end": 347, "text": "không ép crop dọc"}]}, "Mở báo cáo trước mục lục.": {"role": "explanatory-body", "selectedSpans": [{"start": 3, "end": 10, "text": "báo cáo"}]}, "Chủ đề, thời gian, người trình bày và ảnh đúng bối cảnh.": {"role": "explanatory-body", "selectedSpans": [{"start": 19, "end": 34, "text": "người trình bày"}]}, "Khi cần trình bày dữ liệu chi tiết. Gợi ý: Chọn mẫu nội dung có bảng hoặc biểu đồ.": {"role": "explanatory-body", "selectedSpans": [{"start": 18, "end": 34, "text": "dữ liệu chi tiết"}]}, "Dẫn đường cho toàn báo cáo sau trang mở đầu.": {"role": "explanatory-body", "selectedSpans": [{"start": 31, "end": 43, "text": "trang mở đầu"}]}, "Các phần lớn theo đúng thứ tự; tên ngắn và mô tả nếu cần. Tên các phần lớn theo đúng thứ tự; số phần và mô tả ngắn nếu cần.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 12, "text": "Các phần lớn"}, {"start": 23, "end": 29, "text": "thứ tự"}]}, "Mục lục toàn báo cáo: chỉ liệt kê các phần lớn theo thứ tự. Mẫu này có ba phần; thêm phần phải kiểm lại hoặc tách trang. Đặt sau trang mở đầu. Không liệt kê các mục chi tiết bên trong từng phần.": {"role": "explanatory-body", "selectedSpans": [{"start": 34, "end": 46, "text": "các phần lớn"}, {"start": 129, "end": 141, "text": "trang mở đầu"}]}, "Không dùng để liệt kê mọi mục nhỏ trong một phần. Gợi ý: Dùng Mở phần cho các mục bên trong một phần.": {"role": "explanatory-body", "selectedSpans": [{"start": 78, "end": 91, "text": "mục bên trong"}]}, "Bắt đầu một phần và chỉ ra các mục thuộc phần đó.": {"role": "explanatory-body", "selectedSpans": [{"start": 8, "end": 16, "text": "một phần"}]}, "Số phần, tên phần và các mục bên trong. Số và tên phần; tối đa ba mục ngắn bên trong phần; cụm ảnh liên quan.": {"role": "explanatory-body", "selectedSpans": [{"start": 25, "end": 38, "text": "mục bên trong"}]}, "Mở phần 01: tên phần, ba mục bên trong và cụm ảnh định hướng. Ba nhãn ngắn; giải thích và phân tích nằm ở các slide nội dung tiếp theo. Đặt trước mỗi phần. Danh sách này là mục con, không lặp danh sách phần của mục lục.": {"role": "explanatory-body", "selectedSpans": [{"start": 25, "end": 38, "text": "mục bên trong"}, {"start": 46, "end": 60, "text": "ảnh định hướng"}]}, "Khi cần dẫn đường cho toàn báo cáo. Gợi ý: Dùng Mục lục cho toàn báo cáo.": {"role": "explanatory-body", "selectedSpans": [{"start": 27, "end": 34, "text": "báo cáo"}]}, "Khép lại báo cáo và chỉ ra người phụ trách.": {"role": "explanatory-body", "selectedSpans": [{"start": 27, "end": 42, "text": "người phụ trách"}]}, "Lời kết, chủ đề, người trình bày và hình đúng ngữ cảnh. Lời cảm ơn, chủ đề báo cáo, năm hình liên quan và tên nhóm trình bày.": {"role": "explanatory-body", "selectedSpans": [{"start": 17, "end": 32, "text": "người trình bày"}, {"start": 68, "end": 82, "text": "chủ đề báo cáo"}]}, "Lời cảm ơn, chủ đề báo cáo, dải năm ảnh và người trình bày. Một lời cảm ơn và một dòng giới thiệu; chọn ảnh cùng chủ đề. Trang cuối; không thêm bảng phân tích hay bước công việc vào mẫu cảm ơn.": {"role": "explanatory-body", "selectedSpans": [{"start": 12, "end": 26, "text": "chủ đề báo cáo"}, {"start": 43, "end": 58, "text": "người trình bày"}]}, "Không dùng thay một kết luận còn cần bằng chứng. Gợi ý: Trình bày kết luận ở trang nội dung trước khi kết thúc.": {"role": "explanatory-body", "selectedSpans": [{"start": 37, "end": 47, "text": "bằng chứng"}]}, "Một hình lớn là điểm nhìn chính, cần lời giải thích ngắn.": {"role": "explanatory-body", "selectedSpans": [{"start": 16, "end": 31, "text": "điểm nhìn chính"}]}, "Một hình ngang có nguồn và lời giải thích.": {"role": "explanatory-body", "selectedSpans": [{"start": 4, "end": 14, "text": "hình ngang"}]}, "Khi nhiều hình cần vị thế ngang nhau. Gợi ý: Dùng Bảng hình cho các lựa chọn đồng cấp.": {"role": "explanatory-body", "selectedSpans": [{"start": 68, "end": 85, "text": "lựa chọn đồng cấp"}]}, "Ba hình cùng chủ đề hoặc theo thứ tự.": {"role": "explanatory-body", "selectedSpans": [{"start": 8, "end": 19, "text": "cùng chủ đề"}]}, "Ba hình ngang, thứ tự và nhãn rõ.": {"role": "explanatory-body", "selectedSpans": [{"start": 3, "end": 13, "text": "hình ngang"}]}, "Ba hình bằng nhau theo một chuỗi; mỗi hình một nhãn. Câu hỏi đầy đủ: Ba hình cùng một chủ đề hoặc một chuỗi có thứ tự.": {"role": "explanatory-body", "selectedSpans": [{"start": 18, "end": 32, "text": "theo một chuỗi"}, {"start": 108, "end": 117, "text": "có thứ tự"}]}, "Khi các hình không liên quan hoặc cần đọc nhiều chi tiết. Gợi ý: Tách trang nếu chủ đề khác nhau; dùng Bộ hình nếu cần nhiều chi tiết cùng nhóm.": {"role": "explanatory-body", "selectedSpans": [{"start": 13, "end": 28, "text": "không liên quan"}, {"start": 87, "end": 96, "text": "khác nhau"}]}, "Bốn lựa chọn đồng cấp cần xem cùng nhau.": {"role": "explanatory-body", "selectedSpans": [{"start": 4, "end": 21, "text": "lựa chọn đồng cấp"}]}, "Bốn hình, cùng tiêu chí và nhãn.": {"role": "explanatory-body", "selectedSpans": [{"start": 10, "end": 23, "text": "cùng tiêu chí"}]}, "Khi một hình phải nổi trội hoặc cần ảnh ưu tiên. Gợi ý: S12 nếu cần sáu chi tiết có vai trò ngang nhau. Nếu có ảnh chính: dùng S05; chỉ dùng S09 khi ảnh chính dọc đi cùng hai chi tiết của cùng đối tượng, hoặc S10 khi ảnh chính ngang đi cùng hai hình hỗ trợ liên quan.": {"role": "explanatory-body", "selectedSpans": [{"start": 84, "end": 102, "text": "vai trò ngang nhau"}, {"start": 188, "end": 202, "text": "cùng đối tượng"}]}, "Hai hình cần gắn mỗi hình với một đoạn ngữ cảnh.": {"role": "explanatory-body", "selectedSpans": [{"start": 34, "end": 47, "text": "đoạn ngữ cảnh"}]}, "Hai hình nhỏ và hai phần giải thích tương ứng.": {"role": "explanatory-body", "selectedSpans": [{"start": 25, "end": 45, "text": "giải thích tương ứng"}]}, "Khi chỉ cần một hình chủ đạo. Gợi ý: Dùng Hình lớn · lời giải thích.": {"role": "explanatory-body", "selectedSpans": [{"start": 16, "end": 28, "text": "hình chủ đạo"}]}, "Một hình dọc cần hai cận cảnh hỗ trợ.": {"role": "explanatory-body", "selectedSpans": [{"start": 17, "end": 29, "text": "hai cận cảnh"}]}, "Một ảnh chính và hai chi tiết của cùng đối tượng.": {"role": "explanatory-body", "selectedSpans": [{"start": 34, "end": 48, "text": "cùng đối tượng"}]}, "Khi các hình là những đối tượng không liên quan. Gợi ý: Tách trang theo đối tượng hoặc dùng bố cục đồng cấp.": {"role": "explanatory-body", "selectedSpans": [{"start": 32, "end": 47, "text": "không liên quan"}]}, "Một toàn cảnh đi cùng hai góc nhìn liên quan.": {"role": "explanatory-body", "selectedSpans": [{"start": 22, "end": 34, "text": "hai góc nhìn"}]}, "Một hình ngang và hai hình phụ cùng bối cảnh.": {"role": "explanatory-body", "selectedSpans": [{"start": 31, "end": 44, "text": "cùng bối cảnh"}]}, "Khi ba ảnh cần ưu tiên ngang nhau. Gợi ý: Dùng Dải hình cho chuỗi cùng chủ đề.": {"role": "explanatory-body", "selectedSpans": [{"start": 15, "end": 33, "text": "ưu tiên ngang nhau"}]}, "Hai hình có cùng một tiêu chí để đối chiếu.": {"role": "explanatory-body", "selectedSpans": [{"start": 33, "end": 42, "text": "đối chiếu"}]}, "Hai hình, nhãn ngữ cảnh và tiêu chí chung.": {"role": "explanatory-body", "selectedSpans": [{"start": 27, "end": 41, "text": "tiêu chí chung"}]}, "Khi hai hình không có quan hệ để đối chiếu. Gợi ý: Tách thành hai trang với câu hỏi riêng.": {"role": "explanatory-body", "selectedSpans": [{"start": 76, "end": 89, "text": "câu hỏi riêng"}]}, "Sáu chi tiết cùng một nhóm cần xem tổng thể.": {"role": "explanatory-body", "selectedSpans": [{"start": 13, "end": 26, "text": "cùng một nhóm"}]}, "Sáu hình và nhãn cho từng khung.": {"role": "explanatory-body", "selectedSpans": [{"start": 21, "end": 31, "text": "từng khung"}]}, "Khi từng chi tiết cần giải thích dài hoặc có một hình ưu tiên. Gợi ý: Tách thành nhiều trang nếu từng chi tiết cần giải thích dài. Nếu có ảnh chính: dùng S05; chỉ dùng S09 khi ảnh chính dọc đi cùng hai chi tiết của cùng đối tượng, hoặc S10 khi ảnh chính ngang đi cùng hai hình hỗ trợ liên quan.": {"role": "explanatory-body", "selectedSpans": [{"start": 22, "end": 36, "text": "giải thích dài"}, {"start": 215, "end": 229, "text": "cùng đối tượng"}]}, "Ảnh phủ toàn nền; chữ đặt trên mặt phẳng HAHA có nền kín.": {"role": "explanatory-body", "selectedSpans": [{"start": 49, "end": 56, "text": "nền kín"}]}, "Một ảnh làm nền và còn vùng chữ tương phản đủ rõ.": {"role": "explanatory-body", "selectedSpans": [{"start": 32, "end": 42, "text": "tương phản"}]}, "Ảnh có nguồn, vùng đặt chữ yên và mặt chữ có nền kín khi cần.": {"role": "explanatory-body", "selectedSpans": [{"start": 4, "end": 12, "text": "có nguồn"}]}, "Khi ảnh làm chữ khó đọc hoặc che chủ thể. Gợi ý: Tách hình và chữ bằng Hình lớn · lời giải thích.": {"role": "explanatory-body", "selectedSpans": [{"start": 29, "end": 40, "text": "che chủ thể"}]}, "Một dải hình dọc đi cùng thông điệp lớn riêng biệt.": {"role": "explanatory-body", "selectedSpans": [{"start": 25, "end": 39, "text": "thông điệp lớn"}]}, "Ảnh phù hợp crop dọc và một thông điệp rõ.": {"role": "explanatory-body", "selectedSpans": [{"start": 12, "end": 20, "text": "crop dọc"}]}, "Khi ảnh cần giữ toàn khung ngang. Gợi ý: Dùng Hình lớn · lời giải thích để giữ toàn ảnh.": {"role": "explanatory-body", "selectedSpans": [{"start": 16, "end": 32, "text": "toàn khung ngang"}]}, "Đối chiếu theo nhiều tiêu chí và chốt một nhận định.": {"role": "explanatory-body", "selectedSpans": [{"start": 38, "end": 51, "text": "một nhận định"}]}, "Đối tượng, tiêu chí, dữ liệu có nguồn và nhận định.": {"role": "explanatory-body", "selectedSpans": [{"start": 21, "end": 37, "text": "dữ liệu có nguồn"}]}, "Khi chưa có dữ liệu đủ so sánh. Gợi ý: Bổ sung dữ liệu trước; không đổi mẫu để che thiếu bằng chứng.": {"role": "explanatory-body", "selectedSpans": [{"start": 4, "end": 30, "text": "chưa có dữ liệu đủ so sánh"}]}, "Hai nhóm dữ kiện khác nhau cần trình bày theo chiều đọc.": {"role": "explanatory-body", "selectedSpans": [{"start": 17, "end": 26, "text": "khác nhau"}]}, "Hai bảng, tên nhóm, đơn vị và nguồn.": {"role": "explanatory-body", "selectedSpans": [{"start": 10, "end": 18, "text": "tên nhóm"}]}, "Khi hai bảng chỉ lặp cùng một bộ số liệu. Gợi ý: Gộp thành một bảng đối chiếu rõ tiêu chí.": {"role": "explanatory-body", "selectedSpans": [{"start": 68, "end": 77, "text": "đối chiếu"}]}, "Ba nhóm có cùng cấu trúc việc làm và đầu ra.": {"role": "explanatory-body", "selectedSpans": [{"start": 25, "end": 43, "text": "việc làm và đầu ra"}]}, "Ba nhóm nội dung và trường thông tin tương ứng.": {"role": "explanatory-body", "selectedSpans": [{"start": 27, "end": 46, "text": "thông tin tương ứng"}]}, "Khi các nhóm không ngang cấp. Gợi ý: Tách trang hoặc dùng bố cục ưu tiên một ý chính.": {"role": "explanatory-body", "selectedSpans": [{"start": 13, "end": 28, "text": "không ngang cấp"}]}, "Một biểu đồ cần đi cùng chỉ số, giải thích và giới hạn.": {"role": "explanatory-body", "selectedSpans": [{"start": 32, "end": 54, "text": "giải thích và giới hạn"}]}, "Dữ liệu, đơn vị, kỳ đo, nguồn và giới hạn.": {"role": "explanatory-body", "selectedSpans": [{"start": 24, "end": 41, "text": "nguồn và giới hạn"}]}, "Khi số liệu chưa được kiểm. Gợi ý: Hoàn thiện đầu vào trước; không thay biểu đồ bằng một kết luận không nguồn.": {"role": "explanatory-body", "selectedSpans": [{"start": 12, "end": 26, "text": "chưa được kiểm"}]}, "Kế hoạch có bốn điểm cần kiểm theo thứ tự.": {"role": "explanatory-body", "selectedSpans": [{"start": 25, "end": 41, "text": "kiểm theo thứ tự"}]}, "Mốc, công việc, người phụ trách và kết quả kiểm.": {"role": "explanatory-body", "selectedSpans": [{"start": 16, "end": 31, "text": "người phụ trách"}]}, "Khi các việc không có thứ tự hoặc quan hệ bước. Gợi ý: Dùng nhóm thông tin đồng cấp hoặc bảng trách nhiệm.": {"role": "explanatory-body", "selectedSpans": [{"start": 13, "end": 28, "text": "không có thứ tự"}]}, "Đọc xu hướng tiêu dùng qua ba vùng thông tin.": {"role": "explanatory-body", "selectedSpans": [{"start": 4, "end": 22, "text": "xu hướng tiêu dùng"}]}, "Dữ liệu theo thời gian, hành vi/kênh và ảnh hưởng; đơn vị, kỳ đo, nguồn. Thói quen, tiêu chí, trở ngại; số liệu cùng kỳ; ba cách dùng sản phẩm.": {"role": "explanatory-body", "selectedSpans": [{"start": 51, "end": 57, "text": "đơn vị"}, {"start": 104, "end": 119, "text": "số liệu cùng kỳ"}]}, "Tín hiệu tiêu dùng, biểu đồ theo kỳ và ba nhóm sản phẩm minh họa. Ba tín hiệu ngắn, một biểu đồ và ba nhóm sản phẩm. Tách phần nghiên cứu chi tiết. Khi cần giải thích người dùng muốn gì và nhóm sản phẩm nào đáp ứng.": {"role": "explanatory-body", "selectedSpans": [{"start": 39, "end": 55, "text": "ba nhóm sản phẩm"}]}, "Khi cần cơ cấu quy mô thị trường tại một thời điểm. Gợi ý: Dùng Quy mô thị trường · cơ cấu và động lực khi đủ dữ liệu phù hợp.": {"role": "explanatory-body", "selectedSpans": [{"start": 15, "end": 32, "text": "quy mô thị trường"}]}, "Giải thích quy mô thị trường, cơ cấu và động lực.": {"role": "explanatory-body", "selectedSpans": [{"start": 11, "end": 28, "text": "quy mô thị trường"}]}, "Quy mô, năm/kỳ đo, phân nhóm và nguồn. Phạm vi, đơn vị, kỳ hiện tại và kỳ so sánh; tỷ trọng nhóm; nhu cầu và điểm cần kiểm.": {"role": "explanatory-body", "selectedSpans": [{"start": 48, "end": 54, "text": "đơn vị"}, {"start": 56, "end": 67, "text": "kỳ hiện tại"}]}, "Khung phạm vi, biểu đồ tỷ trọng, ba chỉ số và bảng nhóm thị trường. Ba nhóm, ba chỉ số; không dùng tỷ trọng để suy ra lợi nhuận. Khi mở phần phân tích thị trường; giữ nguồn và điều kiện ngay cạnh số.": {"role": "explanatory-body", "selectedSpans": [{"start": 15, "end": 31, "text": "biểu đồ tỷ trọng"}, {"start": 163, "end": 172, "text": "giữ nguồn"}]}, "Khi câu hỏi chính là xu hướng thay đổi theo thời gian. Gợi ý: Dùng Xu hướng tiêu dùng khi có chuỗi số liệu đúng kỳ.": {"role": "explanatory-body", "selectedSpans": [{"start": 30, "end": 53, "text": "thay đổi theo thời gian"}]}, "Hai nhóm cần bảng đi cùng hình minh họa đúng nhóm.": {"role": "explanatory-body", "selectedSpans": [{"start": 31, "end": 49, "text": "minh họa đúng nhóm"}]}, "Hai bảng/nhóm và hình tương ứng có nguồn.": {"role": "explanatory-body", "selectedSpans": [{"start": 17, "end": 31, "text": "hình tương ứng"}]}, "Khi hình chỉ lấp chỗ hoặc không liên quan dữ kiện. Gợi ý: Bỏ hình không cần thiết hoặc dùng Hai bảng.": {"role": "explanatory-body", "selectedSpans": [{"start": 26, "end": 41, "text": "không liên quan"}]}, "Nhiều mục nhỏ đi cùng một hình dọc liên quan.": {"role": "explanatory-body", "selectedSpans": [{"start": 26, "end": 44, "text": "hình dọc liên quan"}]}, "Các mục có thứ tự đọc và hình phù hợp crop dọc.": {"role": "explanatory-body", "selectedSpans": [{"start": 11, "end": 21, "text": "thứ tự đọc"}]}, "Khi hình cần toàn khung ngang hoặc nội dung quá dài. Gợi ý: Tách trang hoặc dùng cột chữ với hình ngang riêng.": {"role": "explanatory-body", "selectedSpans": [{"start": 35, "end": 51, "text": "nội dung quá dài"}]}, "Đọc hành trình theo từng bước và các hàng đối ứng.": {"role": "explanatory-body", "selectedSpans": [{"start": 15, "end": 29, "text": "theo từng bước"}]}, "Các bước, hành động, cảm nhận, điểm khó và cải thiện.": {"role": "explanatory-body", "selectedSpans": [{"start": 31, "end": 52, "text": "điểm khó và cải thiện"}]}, "Khi chỉ là một danh sách việc không có hành trình. Gợi ý: Dùng kế hoạch hoặc danh sách theo cấu trúc thực.": {"role": "explanatory-body", "selectedSpans": [{"start": 30, "end": 49, "text": "không có hành trình"}]}, "So sánh cơ cấu bán hàng, sản lượng và doanh thu.": {"role": "explanatory-body", "selectedSpans": [{"start": 8, "end": 23, "text": "cơ cấu bán hàng"}]}, "Nhóm sản phẩm, sản lượng, doanh thu, đơn vị, kỳ đo, nguồn và hình đúng sản phẩm. Sản phẩm, số lượng, tỷ trọng, doanh thu cùng kỳ; hình nhận diện và nhận định có điều kiện.": {"role": "explanatory-body", "selectedSpans": [{"start": 37, "end": 43, "text": "đơn vị"}, {"start": 161, "end": 170, "text": "điều kiện"}]}, "Biểu đồ tỷ trọng và hình sản phẩm; bảng số liệu và nhận định thương mại. Hai sản phẩm và tổng; tăng số dòng phải tách tiếp, không thu nhỏ chữ. Khi chọn sản phẩm chủ lực hoặc kiểm giả định về cơ cấu bán hàng.": {"role": "explanatory-body", "selectedSpans": [{"start": 51, "end": 71, "text": "nhận định thương mại"}, {"start": 124, "end": 141, "text": "không thu nhỏ chữ"}]}, "Khi thiếu một thước đo cần để kết luận cơ cấu. Gợi ý: Bổ sung dữ liệu hoặc giới hạn câu hỏi; không tự suy doanh thu từ sản lượng.": {"role": "explanatory-body", "selectedSpans": [{"start": 4, "end": 22, "text": "thiếu một thước đo"}, {"start": 30, "end": 38, "text": "kết luận"}]}, "Đối chiếu đối thủ theo tiêu chí và xác định khoảng trống.": {"role": "explanatory-body", "selectedSpans": [{"start": 35, "end": 56, "text": "xác định khoảng trống"}]}, "Đối thủ, tiêu chí so sánh, nguồn và các câu hỏi kết luận. Định vị, điểm mạnh, điểm yếu, mức giá cùng đơn vị; nhóm đối thủ và câu hỏi về cơ hội.": {"role": "explanatory-body", "selectedSpans": [{"start": 40, "end": 56, "text": "câu hỏi kết luận"}, {"start": 96, "end": 107, "text": "cùng đơn vị"}]}, "Bảng so sánh nhiều tiêu chí; bốn câu hỏi kết luận ở cột riêng. Ba đối thủ và bốn câu hỏi; dùng trang tiếp theo cho đối thủ còn lại. Khi chọn chỗ đứng cạnh tranh; phân biệt dữ kiện và giả thuyết.": {"role": "explanatory-body", "selectedSpans": [{"start": 33, "end": 49, "text": "câu hỏi kết luận"}, {"start": 162, "end": 193, "text": "phân biệt dữ kiện và giả thuyết"}]}, "Khi bằng chứng về đối thủ chưa đủ đối chiếu. Gợi ý: Thu thập thêm hoặc ghi rõ phần chưa biết trước khi kết luận.": {"role": "explanatory-body", "selectedSpans": [{"start": 4, "end": 14, "text": "bằng chứng"}]}, "Xếp hạng sản phẩm theo chỉ số có thể kiểm.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 17, "text": "Xếp hạng sản phẩm"}]}, "Sản phẩm, hạng, chỉ số, đơn vị, nguồn và ghi chú. Hạng, sản phẩm, nhóm, giá, số lượng trong cùng kỳ và ghi chú; tiêu chí xếp hạng và nguồn.": {"role": "explanatory-body", "selectedSpans": [{"start": 24, "end": 30, "text": "đơn vị"}, {"start": 112, "end": 129, "text": "tiêu chí xếp hạng"}]}, "Bảng có hạng, chỉ số, đơn vị và ghi chú; kết luận theo nhiều hàng. Năm hàng; danh sách dài hơn dùng trang tiếp theo với cùng cột và tiêu chí. Khi kiểm sản phẩm dẫn đầu theo chỉ số đã nêu. Không đánh đồng thứ hạng với chất lượng.": {"role": "explanatory-body", "selectedSpans": [{"start": 41, "end": 49, "text": "kết luận"}, {"start": 188, "end": 212, "text": "Không đánh đồng thứ hạng"}]}, "Khi chưa chốt cùng một tiêu chí xếp hạng. Gợi ý: Chốt tiêu chí và dữ liệu trước; dùng bảng mô tả nếu chưa thể xếp hạng.": {"role": "explanatory-body", "selectedSpans": [{"start": 9, "end": 31, "text": "chốt cùng một tiêu chí"}]}, "Vai trò quyết định cách trình bày; khóa và chờ là trạng thái.": {"role": "explanatory-body", "selectedSpans": [{"start": 35, "end": 60, "text": "khóa và chờ là trạng thái"}]}, "Không tô màu nhấn mọi nút; không dùng màu nhấn để ngụ ý hoàn thành.": {"role": "explanatory-body", "selectedSpans": [{"start": 27, "end": 46, "text": "không dùng màu nhấn"}]}, "Trang đang ở hoặc lựa chọn quan trọng cần giữ dấu nhận biết. Nền trung tính, chữ sáng, gạch màu nhấn dưới.": {"role": "explanatory-body", "selectedSpans": [{"start": 46, "end": 59, "text": "dấu nhận biết"}]}, "Thao tác quen thuộc có tên truy cập, như Đặt lại mẫu.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 19, "text": "Thao tác quen thuộc"}]}, "Không dùng một hình khó đoán thay cho nhãn cần giải thích.": {"role": "explanatory-body", "selectedSpans": [{"start": 20, "end": 28, "text": "khó đoán"}]}, "Phân biệt lựa chọn còn hiệu lực với phản hồi tạm thời.": {"role": "explanatory-body", "selectedSpans": [{"start": 36, "end": 53, "text": "phản hồi tạm thời"}]}, "Hành động chính trung tính, phụ nền giấy, cần chú ý màu nhấn. Không đổi vai trò bằng màu khi tương tác.": {"role": "explanatory-body", "selectedSpans": [{"start": 0, "end": 15, "text": "Hành động chính"}]}, "Chỉ báo kết quả có thật. Không dùng màu trung tính/màu nhấn hoặc trạng thái chọn để tự khẳng định đã thành công. Nội dung minh họa nguồn: Lỗi minh họa: thao tác bị dừng. Bạn có thể thử lại bằng “Chạy mẫu”.": {"role": "explanatory-body", "selectedSpans": [{"start": 8, "end": 23, "text": "kết quả có thật"}, {"start": 25, "end": 59, "text": "Không dùng màu trung tính/màu nhấn"}]}, "Giới hạn nguồn lịch sử — Một số trang dùng địa danh hành chính cũ: chỉ lấy vị trí địa lý, không coi tỉnh/huyện cũ là trạng thái hiện nay. Khác biệt tọa độ trong bảng Hoàng Sa chưa dùng làm đường bao đầy đủ.": {"role": "explanatory-body", "selectedSpans": [{"start": 9, "end": 22, "text": "nguồn lịch sử"}, {"start": 90, "end": 113, "text": "không coi tỉnh/huyện cũ"}]}, "Nhãn trên hình — VIỆT NAM · Quần đảo Hoàng Sa (Việt Nam) · Quần đảo Trường Sa (Việt Nam) · BIỂN ĐÔNG · Phú Quốc · Côn Đảo · Hoàng Sa · Phú Lâm · Tri Tôn · Trường Sa Lớn · Song Tử Tây · Nam Yết.": {"role": "role-exception", "selectedSpans": []}, "Nguồn và tỷ lệ — Đường bờ Natural Earth qua world-atlas 2.0.2; độ khái quát 1:110 triệu, đảo rất nhỏ có thể không hiện. Ghi nhận nguồn 17/10/2026. Bề mặt chỉ có đường bờ tự nhiên, không phân loại chủ quyền.": {"role": "role-exception", "selectedSpans": []}};
