function choose(text){const lower=text.toLocaleLowerCase('vi'),found=[];for(const phrase of phraseList){let start=lower.indexOf(phrase);if(start<0)continue;const end=start+phrase.length;if(/[\p{L}\p{N}]/u.test(lower[start-1]||'')||/[\p{L}\p{N}]/u.test(lower[end]||''))continue;const prefix=lower.slice(Math.max(0,start-65),start),negative=prefix.match(/(?:^|[\s;,.])((?:không|chưa|đừng|do not|not)\s+(?:[^\s;,.]+\s+){0,6})$/u);if(negative)start-=negative[1].length;if(end-start>text.trim().length*.48)continue;if(found.some(x=>start<x.end&&end>x.start))continue;found.push({start,end,text:text.slice(start,end),reason:'concept/action/condition from task-reviewed vocabulary; negation retained'});if(found.length>3)break;}return found.sort((a,b)=>a.start-b.start).slice(0,text.length>150?2:1);}
function target(e){if(e.closest(blocked)||e.querySelector('p,li,dd,td,[data-role="body"],.body-copy,.body-text'))return false;const t=e.textContent.trim();if(t.length<36||!/[\p{L}]/u.test(t)||t.replace(/[\p{L}]/gu,'').length/t.length>.65)return false;if(e.matches('td')&&t.length<55)return false;return true;}
function selectedFor(text){const trimmed=text.trim(),exact=typeof exactUnits!=='undefined'?exactUnits[trimmed]:null;if(exact){if(exact.role==='role-exception')return [];const leading=text.indexOf(trimmed);return exact.selectedSpans.map(x=>({start:leading+Array.from(trimmed).slice(0,x.start).join('').length,end:leading+Array.from(trimmed).slice(0,x.end).join('').length,text:x.text,reason:'exact reviewed semantic unit'}));}return choose(text);}
function annotate(e,doc){if(!target(e))return;if(versions.get(e)===e.textContent)return;if(versions.has(e)){for(const mark of e.querySelectorAll('[data-body-emphasis="keyword58"]'))mark.replaceWith(mark.textContent);e.removeAttribute('data-body-emphasis-owner');}let s=stats.get(doc),original=e.textContent,matches=selectedFor(original);const walker=doc.createTreeWalker(e,4),nodes=[];let offset=0;while(walker.nextNode()){const n=walker.currentNode,start=offset;offset+=n.textContent.length;if(n.parentElement.closest('strong,b,'+blocked))continue;nodes.push({node:n,start,end:offset});}
let selected=[];for(const item of nodes){const n=item.node,local=matches.filter(x=>x.start<item.end&&x.end>item.start).map(x=>({start:Math.max(0,x.start-item.start),end:Math.min(n.textContent.length,x.end-item.start)}));if(!local.length)continue;const frag=doc.createDocumentFragment();let from=0;for(const match of local){frag.append(n.textContent.slice(from,match.start));const mark=doc.createElement('strong');mark.setAttribute('data-body-emphasis','keyword58');mark.textContent=n.textContent.slice(match.start,match.end);frag.append(mark);from=match.end;selected.push(mark.textContent);}frag.append(n.textContent.slice(from));n.replaceWith(frag);}
versions.set(e,original);if(selected.length){if(e.textContent!==original)throw Error('Body text conservation failed');e.dataset.bodyEmphasisOwner='body58';s.records.push({tag:e.tagName,id:e.id,classes:e.className,text:original,selected});}
}
function boot(doc){if(!doc||doc.__body58boot)return;doc.__body58boot=true;stats.set(doc,{records:[],exceptions:[]});const style=doc.createElement('style');style.id='body-keyword-style58';style.textContent='[data-body-emphasis="keyword58"]{display:inline!important;font-family:inherit!important;font-size:inherit!important;line-height:inherit!important;font-weight:700!important;font-style:inherit!important;letter-spacing:inherit!important;color:inherit!important;white-space:inherit!important;vertical-align:baseline!important;background:none!important;border:0!important;border-radius:0!important;box-shadow:none!important;text-shadow:none!important;padding:0!important;margin:0!important}';doc.head.append(style);
let timer=0;function run(){timer=0;for(const e of doc.querySelectorAll(selector))annotate(e,doc);for(const frame of doc.querySelectorAll('iframe')){if(!frame.__body58load){frame.__body58load=true;frame.addEventListener('load',()=>{try{boot(frame.contentDocument)}catch{}})}try{if(frame.contentDocument?.readyState==='complete')boot(frame.contentDocument)}catch{}}}
function schedule(){if(!timer)timer=setTimeout(run,35)};new MutationObserver(schedule).observe(doc.body,{subtree:true,childList:true,characterData:true});run();doc.fonts.ready.then(run);}
window.BodyKeyword58={version:'task-body58-2',choose:selectedFor,boot,records:()=>stats.get(document)?.records||[],scan:()=>{for(const e of document.querySelectorAll(selector))annotate(e,document)}};
